// ==========================================
// ★ K 의 방 — S1 『표본실 — 착륙 이후』
// ==========================================
kDungeon('S1', {
  name: '『표본실 — 착륙 이후』',
  concept: '무언가 떨어진 뒤 봉쇄된 지하 표본실. 깨진 표본병, 사람 몸에 둥지를 트는 실, 쇠를 녹이는 맑은 피, 환기구와 기밀실, 문 여는 법을 배운 사냥꾼을 지나 맨 아래 0호 격납고의 어미 앞에서 지상 승강기를 탄다.',
  intro: `산비탈에 둥근 구덩이가 있다. 가운데가 유리처럼 녹아 굳었다. 석 달 전에 무언가 떨어진 자리다.<br><br>
    구덩이 밑에 표본실이 있다. 떨어진 것을 주워 와 병에 담고 이름을 붙이던 곳이다.<br>
    이번에 떨어진 것도 주워 왔다. 검은 돌이었다. 냉장고만 했다. 기록에는 따뜻했다고 적혀 있다.<br><br>
    입구 유리문에 종이가 붙어 있다. 격리 중. 손글씨다.<br>
    일행이 들어서자 등 뒤에서 문이 잠겼다. 격리는 그렇게 한다.<br><br>
    나가는 길은 맨 아래 0호 격납고의 지상 승강기 하나다. 거기까지 여덟 층이다.`,
  outro: `승강기가 멈췄다. 철창 문이 열린다. 바람이 들어온다. 차다.<br>
    찬 것이 이렇게 반가운 적이 없다.<br><br>
    구덩이 가장자리다. 녹아 굳은 바닥이 발밑에서 반짝인다. 다들 한참 하늘만 봤다.<br>
    한 사람이 뒤를 봤다. 구덩이 바닥에 구멍이 하나 더 있다. 작다. 가장자리 흙이 아직 김을 낸다.<br><br>
    승강기 문 옆 작은 화면에 표본실 재실 인원이 떠 있다. 0.<br>
    그 밑에 처음 보는 칸이 켜졌다. 반입 예정 1.`,
  floors: [

    // ───────── 1층 ─────────
    { name:'1층 — 반입구', scenes:[

      { t:'반입구 — 재실 인원판',
        x:`유리문 안쪽은 하역장이다. 천장이 높고 바닥에 노란 선이 그어져 있다.<br><br>
          벽에 재실 인원판이 걸려 있다. 붉은 숫자로 서른넷. 사람이 드나들면 옆의 작은 등이 깜박인다.<br>
          일행이 들어설 때 등이 깜박였다. 숫자는 서른넷 그대로다.<br><br>
          구석에 배급 상자가 쌓여 있다. 봉인 테이프가 성하다.<br>
          바닥에 끌린 자국이 하나 있다. 벽 환기구까지 간다. 자국 폭이 사람 어깨만 하다.`,
        o:[
          { l:'① 봉인된 배급 상자를 뜯는다.', k:'fix', dc:23,
            ok:`테이프를 칼로 그었다. 상자 안에 은박 봉지가 줄지어 있다. 말린 고기다.<br><br>봉지마다 날짜가 찍혀 있다. 전부 석 달 전 것이다. 떨어진 날 바로 다음 날 들어왔다.<br>봉지를 하나씩 눌러 봤다. 바람 빠진 것은 없다.<br><br>상자 바닥에 반입 확인서가 붙어 있다. 받은 사람 칸에 서명이 없다.`,
            ng:`테이프를 긋는데 상자 밑이 물렁하다.<br><br>밑에서 두 번째 상자가 젖어 있다. 젖은 데서 식초 냄새가 난다.<br>손을 뺐을 때 손끝 살갗이 하얗게 일어나 있다. 쓰리다. 쓰린 게 손목까지 올라온다.<br><br>상자는 다시 안 건드렸다. 위의 상자도.`,
            win:{ exp:16, dream:2, item:'말린 고기' },
            lose:{ hp:-26, mind:-14 } },
          { l:'② 끌린 자국을 따라 환기구를 들여다본다.', k:'gaze', dc:24,
            doom:{ title:'하역장 환기구', what:'환기구 안으로 끌려갑니다', dc:18, sec:55,
              text:`덮개에 얼굴을 댔다. 안이 깊다. 바람이 이쪽으로 분다. 따뜻하다.<br><br>덮개 나사 넷이 다 풀려 있다. 나사 머리가 안쪽을 보고 있다. 안에서 푼 것이다.<br>그걸 알아챘을 때 덮개가 안으로 열린다. 문처럼.<br><br>어둠에서 무언가 펴진다. 접혀 있던 자가 펴지듯 마디마디. 끝이 옷깃을 잡았다. 당긴다. 어깨가 덮개 틀에 걸린다. 틀이 휜다.`,
              dieText:`환기구 덮개는 다시 닫혔다. 나사 넷이 안쪽에서 조여졌다.<br><br>바닥에 끌린 자국이 하나 더 생겼다. 먼저 있던 것 옆에 나란히.<br>재실 인원판 등이 한 번 깜박였다.` },
            ok:`얼굴을 대지 않았다. 손전등을 비스듬히 넣고 덮개 틈으로만 봤다.<br><br>나사 넷이 풀려 있다. 안에서 풀었다. 이 덮개는 안에서 여는 문이다.<br>불빛 끝에 신발 한 짝이 걸려 있다. 끈이 묶인 채다.<br><br>물러서서 일행에게 말했다. 덮개 앞에는 서지 말 것. 그다음부터 다들 벽과 벽 사이 한가운데로 걸었다.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 경비실 일지를 넘겨 본다.', k:'sense', dc:23, only:'sense',
            ok:`경비실 책상에 일지가 펼쳐져 있다. 볼펜이 끼워져 있다.<br><br>마지막 장을 읽었다. 환기 차단 요청. 세 번 적혀 있다. 세 번 다 반려.<br>그 밑에 연필로 작게 적혀 있다. 놈들은 따뜻한 쪽으로 간다. 추우면 느리다.<br><br>책상 서랍에 손난로가 한 상자 있다. 손난로는 두고 왔다. 일지는 챙겼다.`,
            ng:`일지를 넘기는데 책상 밑에 발이 하나 보인다. 경비복 바지다.<br><br>의자를 빼 봤다. 아무도 없다. 바지만 서 있다. 안쪽에 하얀 막이 말라붙어 바지 모양을 잡고 있다.<br>막에서 바스락 소리가 났다. 다들 한참 숨을 안 쉬었다. 일지는 거기 두고 나왔다.`,
            win:{ exp:16, dream:2, mind:6 },
            lose:{ mind:-15, spirit:-16 } }
        ] },

      { t:'반입구 — 소독실',
        x:`하역장과 안쪽 사이에 소독실이 있다. 지나가면 물이 저절로 쏟아지는 방이다.<br><br>
          배수구 둘레에 물때가 하얗다. 물은 빠지지 않고 고여 있다. 김이 오른다.<br>
          소독수는 차가워야 한다. 여기 물은 따뜻하다. 누가 온수 밸브를 끝까지 돌려놓았다.<br><br>
          고인 물 표면이 가끔 오그라든다. 바람은 없다.`,
        o:[
          { l:'① 숨을 참고 소독실을 그대로 통과한다.', k:'steady', dc:24,
            doom:{ title:'따뜻한 소독수', what:'실이 귓속으로 들어갔습니다', dc:18, sec:55,
              text:`발을 들이자 물이 쏟아진다. 따뜻하다. 몸이 먼저 풀린다.<br><br>반쯤 갔을 때 귓바퀴가 간지럽다. 물이 흐르는 것과 다르다. 거슬러 올라온다.<br>손가락을 넣었다. 미끈한 것이 손가락을 피해 더 안쪽으로 간다. 머리카락보다 굵다. 따뜻한 쪽을 안다.<br><br>귓속이 조용해진다. 소리가 하나씩 멀어진다.`,
              dieText:`실은 아프게 하지 않는다. 아프면 숙주가 긁으니까.<br><br>그날 밤 그 사람은 일찍 잠들었다. 몸이 따뜻했다. 다음 날 아침 침낭이 비어 있었다.<br>천장 환기구 덮개가 조금 열려 있었다.` },
            ok:`물이 쏟아지기 전에 뛰었다. 첫 물줄기가 등을 치고 지나갔다.<br><br>나와서 바로 옷을 털고 귀를 막았던 손을 뗐다. 아무것도 따라오지 않았다.<br>돌아보니 배수구에서 하얀 실 몇 가닥이 고개를 들고 있다. 이쪽 체온이 지나간 자리를 향해.`,
            win:{ exp:18, dream:3 } },
          { l:'② 배관을 더듬어 온수 밸브를 잠근다.', k:'sense', dc:23,
            ok:`소독실 옆 점검문을 열자 배관이 얽혀 있다. 따뜻한 관과 찬 관. 손등으로 하나씩 짚었다.<br><br>제일 뜨거운 관의 밸브를 끝까지 잠갔다. 물이 식는다. 고인 물에서 김이 걷힌다.<br>표면이 오그라드는 게 멎었다. 배수구 쪽으로 무언가 천천히 내려간다. 졸린 듯이.<br><br>식은 물을 밟고 지났다. 발목이 시리다. 시린 건 괜찮다.`,
            ng:`밸브를 잠갔는데 물이 더 뜨거워진다. 찬물 밸브였다.<br><br>김이 문틈으로 쏟아져 나온다. 고인 물 표면이 한꺼번에 일어선다. 가는 실이 수백.<br>장화로 문틈을 막고 짓이겼다. 결국 소독실을 맨발로 뛰어 지났다. 발바닥이 데었다. 데인 자리를 한참 들여다봤다. 아무것도 안 들어갔는지.`,
            win:{ exp:16, dream:2 },
            lose:{ hp:-27, mind:-14, spirit:-15 } },
          { l:'③ 마력으로 고인 물을 얼려 길을 낸다.', k:'fix', dc:23, cost:{ mana:26 },
            ok:`손바닥을 바닥에 대고 찬 기운을 흘렸다. 고인 물이 하얗게 언다.<br><br>얼음 속에 실이 갇혔다. 셀 수 없이 많다. 다 같은 쪽으로 몸을 뻗고 굳었다. 문 쪽이다.<br>얼음 위로 일행이 지났다. 샤워 꼭지는 손으로 막았다.<br><br>추우면 느리다. 어디선가 읽은 말이 맞았다. 맞아서 더 무섭다.`,
            ng:`얼리는 데 시간이 걸렸다. 물이 따뜻해서다.<br><br>가장자리가 다 얼기 전에 실 몇 가닥이 손등으로 올라왔다. 털어 냈다. 하나는 손톱 밑으로 들어가려다 잘렸다.<br>잘린 반이 손톱 밑에서 한참 꿈틀거렸다. 일행이 바늘로 빼냈다. 손가락이 퉁퉁 부었다.`,
            win:{ exp:18, dream:2 },
            lose:{ hp:-25, mind:-15, spirit:-16 } }
        ] },

      { t:'반입구 — 멈춘 지게차',
        x:`하역장 가운데에 지게차가 서 있다. 집게에 포대가 실려 있다. 제설용 소금이다.<br><br>
          시동은 꺼졌다. 그런데 엔진 덮개에 손을 대니 따뜻하다. 석 달 동안 꺼져 있던 기계가.<br>
          지게차 밑 그늘에 하얀 막이 거미줄처럼 쳐져 있다. 막이 아주 조금씩 부풀었다 꺼진다.<br><br>
          소금 포대 하나가 터져 바닥에 하얗게 쏟아졌다. 쏟아진 둘레만 막이 없다.`,
        o:[
          { l:'① 지게차 밑의 막을 걷어 낸다.', k:'break', dc:24,
            doom:{ title:'지게차 밑 그늘', what:'지게차 밑으로 끌려 들어갑니다', dc:18, sec:52,
              text:`막대로 막을 걷었다. 끈적하다. 걷히는 대신 막대에 감긴다.<br><br>막 안쪽에 고양이만 한 것들이 다리를 접고 붙어 있다. 열이 넘는다. 엔진이 따뜻한 이유다.<br>막대를 당기자 그것들이 한꺼번에 깬다. 다리가 너무 많다. 막대가 아니라 막대 쥔 손목을 문다.<br><br>당긴다. 작은 것들이 같이 당긴다. 몸이 바닥을 미끄러져 그늘로 끌려 들어간다. 그늘이 생각보다 깊다.`,
              dieText:`지게차 밑은 사람이 들어갈 만큼 높지 않다.<br><br>그래도 들어갔다. 작은 것들은 일을 나눠서 한다.<br>다음 날 아침 엔진 덮개가 조금 더 따뜻했다.` },
            ok:`막대를 길게 잡고 끝만 막에 댔다. 감기려는 순간 놓았다.<br><br>막대가 그늘로 끌려 들어간다. 안에서 다리 많은 것들이 막대를 두고 다툰다. 고양이만 하다. 열이 넘는다.<br>그것들이 막대에 정신 팔린 사이 지게차를 돌아 지났다.<br><br>막대는 돌아오지 않았다. 돌아올 거라고 생각한 사람도 없다.`,
            win:{ exp:17, dream:3 } },
          { l:'② 쏟아진 소금만 밟고 가서 포대를 챙긴다.', k:'luck', dc:23,
            ok:`소금이 쏟아진 데로만 디뎠다. 하얀 둘레 안에는 막이 없다.<br><br>터지지 않은 포대 귀퉁이를 찢어 소금 덩이를 꺼냈다. 습기를 먹어 주먹만 하게 뭉쳤다.<br>막이 소금을 피한다. 짠 것을 싫어한다. 아니면 마른 것을.<br><br>덩이를 하나 더 주머니에 넣었다. 먹으려는 것만은 아니다.`,
            ng:`소금 둘레 끝을 디뎠는데 발밑에서 바스락 소리가 난다. 소금이 아니다.<br><br>막이 소금 밑으로도 깔려 있었다. 밟은 데가 꺼지면서 발목까지 빠졌다.<br>끈적한 것이 발목에 감긴다. 빼는 데 신발 한 짝을 두고 왔다. 발목 살갗이 벗겨졌다.`,
            win:{ exp:16, dream:2, item:'소금 덩이' },
            lose:{ hp:-28, spirit:-15 } },
          { l:'③ 무력으로 지게차를 밀어 환기구를 막는다.', k:'steady', dc:23, cost:{ might:26 },
            ok:`지게차 뒤에 어깨를 댔다. 바퀴가 굳어 있다. 무력을 끝까지 끌어올렸다.<br><br>한 뼘, 또 한 뼘. 지게차가 미끄러져 벽 환기구 앞에 섰다. 집게가 덮개를 정확히 누른다.<br>밑에 있던 것들이 그늘을 따라 같이 움직였다. 그늘은 이제 환기구 앞에 있다.<br><br>덮개 안쪽에서 무언가 두 번 밀었다. 지게차는 안 밀렸다.`,
            ng:`어깨를 대고 미는데 지게차가 안 움직인다. 바퀴에 막이 감겨 있다.<br><br>무력을 더 쓰는 순간 바퀴가 풀리면서 지게차가 반대로 굴렀다. 다리가 깔렸다 빠졌다.<br>밑에서 무언가 우르르 흩어졌다. 흩어진 것들이 어디로 갔는지 아무도 못 봤다.`,
            win:{ exp:18, dream:2 },
            lose:{ hp:-30, mind:-14 } }
        ] },

      { t:'반입구 — 엎어진 운반 수레',
        x:`복도 들머리에 운반 수레가 엎어져 있다. 바퀴 하나가 아직 돈다.<br><br>
          수레에서 떨어진 유리병이 깨졌다. 팔뚝만 한 병이다. 깨진 조각이 전부 바깥으로 휘었다. 안에서 밀어서 깨진 병이다.<br>
          바닥에 맑은 보존액이 넓게 퍼졌다. 표면이 가끔 실처럼 일어선다.<br><br>
          병에 붙은 라벨이 반쯤 남았다. 표본 1형. 그 밑에 손글씨. 체온 접근 시 활성.`,
        o:[
          { l:'① 보존액을 뛰어넘는다.', k:'evade', dc:24,
            doom:{ title:'퍼진 보존액', what:'실이 발목으로 파고듭니다', dc:18, sec:52,
              text:`도움닫기를 하고 뛰었다. 넓다. 생각보다 넓다.<br><br>뒤꿈치가 보존액 가장자리를 디뎠다. 찰박. 소리는 작다.<br>바지 안쪽으로 차가운 것이 올라온다. 발목 뼈를 돌아 정강이로. 한 가닥이 아니다.<br><br>살갗 밑이 간지럽다. 긁으면 안 된다는 걸 알면서 손이 간다.`,
              dieText:`실은 아프게 하지 않는다. 그래서 숙주는 걷는다.<br><br>그 사람은 나흘을 더 걸었다. 말수가 줄었고 몸이 따뜻했다.<br>닷새째 되는 날 높은 데로 올라갔다. 내려오지 않았다.` },
            ok:`도움닫기를 길게 하고 뛰었다. 뒤꿈치가 마른 바닥에 닿았다. 한 뼘 차이다.<br><br>돌아보니 보존액 표면이 이쪽으로 줄을 선다. 실 수십 가닥이 일어서서 체온이 지나간 자리를 가리킨다.<br>일행도 한 명씩 뛰었다. 다들 넘었다. 넘고 나서 한동안 아무도 발목을 안 긁었다.`,
            win:{ exp:17, dream:3 } },
          { l:'② 라벨을 끝까지 읽고 찬 배관을 따라 돈다.', k:'gaze', dc:23,
            ok:`라벨 뒷면까지 읽었다. 1형. 보존액 안에서 휴면. 체온 접근 시 활성. 섭씨 삼십 도 이상.<br><br>복도 벽을 따라 찬 배관이 지난다. 이슬이 맺혀 있다. 배관에 몸을 붙이고 둘레를 돌았다.<br>보존액 표면이 일어서다 만다. 차가운 쪽은 보이지 않는 모양이다.<br><br>라벨 맨 밑에 한 줄 더 있다. 2형으로 이행까지 닷새.`,
            ng:`라벨을 읽느라 고개를 숙였다. 숨이 보존액 위로 내려간다.<br><br>숨도 따뜻하다. 실 몇 가닥이 고개를 들고 튀었다. 하나가 입가에 붙었다.<br>뱉고, 닦고, 또 뱉었다. 입술이 쓰리다. 한참 동안 혀로 이를 하나씩 세었다.`,
            win:{ exp:16, dream:2, spirit:6 },
            lose:{ mind:-16, spirit:-17 } }
        ] },

      { t:'반입구 — 화물 승강기',
        x:`아래층으로 내려가는 화물 승강기가 있다. 문이 반쯤 열려 있다. 칸은 층 사이에 걸려 멈췄다.<br><br>
          문틈 아래로 칸 지붕이 보인다. 지붕에 점검 해치가 있다. 열려 있다.<br>
          해치로 내려가면 칸 안을 지나 아래층 문으로 나갈 수 있다. 제일 빠른 길이다.<br><br>
          승강기 통로 위쪽에서 소리가 난다. 똑, 똑, 똑. 세 번. 쉬었다가 다시 세 번.`,
        o:[
          { l:'① 칸 지붕으로 내려가 해치로 들어간다.', k:'evade', dc:24,
            doom:{ title:'승강기 통로', what:'승강기 통로 위로 끌려 올라갑니다', dc:18, sec:50,
              text:`문틈으로 몸을 내려 칸 지붕을 디뎠다. 칸이 조금 흔들린다.<br><br>해치에 발을 넣는데 위에서 두드리는 소리가 멎었다. 멎은 게 더 크게 들린다.<br>목덜미에 바람이 닿는다. 위에서 내려오는 바람이다. 숨이다.<br><br>어깨를 무언가 감싼다. 손이 아니다. 마디가 너무 많다. 몸이 해치에서 빠져 위로 끌려 올라간다. 쇠줄이 얼굴 옆을 지나간다.`,
              dieText:`승강기 통로는 위로 길다.<br><br>일행이 문틈으로 올려다봤을 때는 쇠줄만 흔들리고 있었다.<br>한참 뒤에 위에서 똑, 똑, 똑. 세 번. 이번엔 쉬지 않았다.` },
            ok:`칸 지붕에 내려서자마자 해치로 몸을 넣었다. 머뭇거리지 않았다.<br><br>해치 뚜껑을 머리 위로 닫았다. 닫히는 순간 뚜껑 위에 무언가 내려앉았다. 무겁다. 쇠가 휜다.<br>칸 안쪽 문을 손으로 벌려 아래층으로 굴러 나갔다. 일행이 뒤따랐다.<br><br>뒤에서 해치 뚜껑이 똑, 똑, 똑 울렸다. 묻는 소리다. 대답은 안 했다.`,
            win:{ exp:18, dream:3 } },
          { l:'② 비상계단 문을 찾는다.', k:'sense', dc:23,
            ok:`승강기 옆 벽을 짚어 갔다. 비상구 표시등이 꺼져 있다. 표시등 판에 손바닥 자국이 있다.<br><br>문을 열자 계단에서 찬 바람이 올라온다. 찬 것이 좋은 것이라는 걸 이제 다들 안다.<br>계단 손잡이는 성하다. 녹은 자국도 없다.<br><br>문을 닫으며 돌아봤다. 승강기 통로의 두드림이 멈춰 있었다. 듣고 있는 것이다.`,
            ng:`벽을 짚어 가다가 손이 미끄러졌다. 벽이 젖어 있다.<br><br>손바닥이 화끈하다. 식초 냄새가 난다. 벽을 타고 흘러내린 맑은 것이다.<br>손을 옷에 문질렀다. 옷에 구멍이 났다. 손바닥 살갗이 동전만 하게 벗겨졌다.`,
            win:{ exp:16, dream:2 },
            lose:{ hp:-27, mind:-14 } },
          { l:'③ 문 뒤에 붙어 두드림의 박자를 센다.', k:'hide', dc:23, only:'hide',
            ok:`문 옆 그늘에 붙었다. 숨을 얕게 쉬었다.<br><br>세 번, 쉼, 세 번. 쉬는 사이가 일정하다. 열둘을 셀 만큼.<br>쉬는 동안 두드림의 주인은 듣는다. 두드리는 동안은 듣지 않는다.<br><br>다음 두드림이 시작될 때 일행을 손짓해 계단으로 보냈다. 세 번 두드리는 동안 다 지났다. 아래층에서도 쓸 수 있는 셈이다.`,
            ng:`세는 동안 숨이 길어졌다. 숨이 길면 소리가 난다.<br><br>쉬는 사이에 숨소리가 났다. 두드림이 멎었다. 열둘이 지나도 다시 시작하지 않았다.<br>대신 문틈 위로 무언가 천천히 내려온다. 마디가 많다. 뒷걸음으로 물러나다 문틀 모서리에 어깨가 찢겼다.`,
            win:{ exp:18, dream:3, mind:6 },
            lose:{ hp:-25, mind:-15, spirit:-18 } }
        ] },

      { t:'반입구 — 경비 무기고',
        x:`경비 무기고 문이 열려 있다. 안에서 식초 냄새가 난다. 눈이 따갑다.<br><br>
          총기 거치대가 휘었다. 총 몇 자루가 바닥에 붙어 있다. 붙었다기보다 바닥에 녹아들었다.<br>
          바닥에 구멍이 셋 나 있다. 가장자리가 매끈하다. 구멍으로 아래층 불빛이 보인다.<br><br>
          안쪽 벽에 사물함이 있다. 한 칸만 잠겨 있다. 거기 가려면 구멍 사이를 지나야 한다.`,
        o:[
          { l:'① 구멍 사이를 디뎌 잠긴 사물함을 연다.', k:'luck', dc:24,
            doom:{ title:'녹은 바닥', what:'바닥이 꺼졌습니다', dc:18, sec:50,
              text:`구멍 사이 바닥을 디뎠다. 단단해 보였다. 겉은.<br><br>두 번째 걸음에 발밑이 물렁하다. 철판이 속에서부터 먹혀 있었다. 겉만 남았다.<br>바닥이 종이처럼 꺼진다. 한쪽 다리가 구멍으로 빠지고 허리에서 걸렸다.<br><br>구멍 가장자리에 맑은 것이 아직 남아 있다. 옷이 연기를 낸다. 그 밑의 살갗도.`,
              dieText:`맑은 피는 한 번 흐르면 오래 먹는다.<br><br>무기고 바닥에 구멍이 넷이 됐다. 넷째 구멍은 가장자리가 매끈하지 않다.<br>아래층 불빛이 그 구멍으로 한참 새어 나왔다.` },
            ok:`구멍 가장자리 말고 거치대 다리가 박힌 자리만 골라 디뎠다. 쇠가 박힌 데는 속이 꽉 찼다.<br><br>사물함 자물쇠를 비틀어 열었다. 안에 경비 하나가 쓴 수첩이 있다. 그리고 손전등 둘.<br>수첩 첫 장. 놈들 피는 맑다. 쇠를 먹는다. 베지 마라. 베면 그 밑에 서 있지 마라.<br><br>손전등은 둘 다 켜진다. 수첩의 나머지 장은 비어 있다.`,
            win:{ exp:18, dream:3, spirit:6 } },
          { l:'② 무기고는 두고 냄새를 기억해 둔다.', k:'steady', dc:23,
            ok:`안에 들어가지 않았다. 문턱에서 냄새만 깊이 맡았다.<br><br>식초 같고, 쇠 같고, 끝에 단내가 조금 난다. 이 냄새가 나면 아래를 봐야 한다. 위도.<br>일행 하나하나에게 맡게 했다. 다들 얼굴을 찡그린다. 찡그린 얼굴은 잊지 않는다.<br><br>나중에 이 냄새를 먼저 맡은 사람이 먼저 비켰다. 그건 아래층 일이다.`,
            ng:`문턱에서 숨을 들이쉬는데 목이 막힌다. 냄새가 너무 진하다.<br><br>기침이 터졌다. 멈추지 않는다. 눈물이 나고 코피가 났다.<br>기침 소리가 복도 끝까지 갔다. 끝에서 똑, 하고 한 번 대답이 왔다.`,
            win:{ exp:16, dream:2, mind:6 },
            lose:{ hp:-25, mind:-16 } }
        ] },

      { t:'반입구 — 처음 들리는 두드림',
        x:`계단으로 가는 복도는 길다. 방화문이 두 개 있다. 첫째는 열려 있고 둘째는 닫혀 있다.<br><br>
          첫째 문을 지나자 벽 안에서 소리가 난다. 똑, 똑, 똑.<br>
          벽 속에 배관이 지나간다. 소리는 배관을 따라 이쪽으로 온다. 일행 걸음과 같은 빠르기로.<br><br>
          일행이 서자 소리도 섰다. 그리고 한 번. 똑.<br>
          묻는 것이다. 거기 있느냐고.`,
        o:[
          { l:'① 같은 박자로 벽을 두드려 답한다.', k:'bond', dc:24,
            doom:{ title:'벽 속의 대답', what:'방화문 너머로 끌려갑니다', dc:18, sec:50,
              text:`손가락 마디로 벽을 쳤다. 똑, 똑, 똑. 이쪽도 셋.<br><br>벽 속이 조용해진다. 한참. 그러다 둘째 방화문 손잡이가 천천히 내려간다.<br>문이 열린다. 문 너머가 어둡다. 어둠에서 접혀 있던 것이 펴진다. 천장까지.<br><br>답을 한 쪽은 이쪽이다. 그것은 답한 쪽으로 온다. 손목이 잡혔다. 마디가 손목을 두 번 감는다. 문 너머로 끌려간다.`,
              dieText:`두드림에 답하면 그것은 답한 손을 기억한다.<br><br>둘째 방화문은 다시 닫혔다. 손잡이가 천천히 올라갔다.<br>벽 속에서 똑, 똑, 똑. 이번엔 박자가 이쪽 것이었다.` },
            ok:`쳤다. 다만 다른 자리를 쳤다. 손을 뒤로 뻗어 첫째 방화문 문짝을.<br><br>쇳소리가 복도 뒤쪽으로 울린다. 벽 속 소리가 그쪽으로 간다. 빠르게.<br>그사이 둘째 문을 열고 계단으로 빠졌다. 문을 닫는 손이 떨렸다.<br><br>소리는 첫째 문 앞에서 한참 머물렀다. 묻는 쪽도 틀릴 때가 있다. 다음에는 안 틀릴 것이다.`,
            win:{ exp:18, dream:3 } },
          { l:'② 그 자리에 엎드려 숨을 죽인다.', k:'hide', dc:24,
            doom:{ title:'따뜻한 바닥', what:'천장으로 끌려 올라갑니다', dc:18, sec:50,
              text:`바닥에 엎드렸다. 숨을 죽였다. 소리는 내지 않았다.<br><br>벽 속 두드림이 멎는다. 대신 천장 타일이 한 장 들린다. 아주 천천히.<br>그것은 지금 듣지 않는다. 다른 걸 한다. 따뜻한 데를 찾는다.<br><br>엎드린 등 위로 바람이 내려온다. 숨이다. 등에 무언가 닿는다. 몸이 들린다. 천장으로 끌려 올라간다. 바닥이 멀어진다.`,
              dieText:`숨을 죽이면 소리는 안 난다. 체온은 남는다.<br><br>천장 타일은 제자리로 내려왔다. 틈이 딱 맞았다.<br>복도 바닥에 사람 모양으로 따뜻한 자리가 한동안 남아 있었다.` },
            ok:`엎드렸다. 다만 찬 배관 밑으로 기어 들어가 배관에 몸을 붙였다.<br><br>천장 타일이 한 장 들린다. 무언가 내려다본다. 한참.<br>배관이 차다. 이쪽도 차다. 그것이 고개를 돌렸다. 타일이 내려왔다.<br><br>일어났을 때 배관에 닿았던 뺨이 얼어 있었다. 언 데가 오래 아팠다. 아픈 건 살아 있는 쪽 일이다.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 내공으로 숨과 체온을 가라앉힌다.', k:'steady', dc:23, cost:{ qi:26 },
            ok:`단전으로 숨을 내렸다. 피가 느려진다. 손끝부터 식는다.<br><br>일행에게도 손바닥을 대어 숨을 맞춰 주었다. 하나씩 숨이 느려졌다.<br>천장에서 타일 하나가 들렸다가 내려앉았다. 찾는 것이 없다는 듯이.<br><br>둘째 방화문을 열고 지났다. 계단에서 다들 손을 비볐다. 손이 다시 따뜻해지는 게 무서웠다.`,
            ng:`숨을 내리는데 심장이 말을 안 듣는다. 무서우면 심장은 빨리 뛴다. 내공도 그건 못 막았다.<br><br>천장 타일이 들린다. 이쪽으로 기운다. 일행이 팔을 잡아끌어 둘째 문으로 뛰었다.<br>문틀에 이마를 찧었다. 피가 눈으로 들어갔다. 따뜻하다. 그게 무서웠다.`,
            win:{ exp:18, dream:2, spirit:6 },
            lose:{ hp:-26, mind:-15, spirit:-18 } }
        ] }
    ] },

    // ───────── 2층 ─────────
    { name:'2층 — 표본 보관실', scenes:[

      { t:'보관실 — 병의 열',
        x:`계단 끝 쇠문에 표본 보관실이라고 적혀 있다. 문은 두껍다. 열려 있다.<br><br>
          안에 선반이 끝없이 줄 서 있다. 선반마다 병이고 병마다 라벨이다. 대부분 돌이다. 이름 붙은 돌이 얌전히 앉아 있다.<br>
          통로 가운데쯤부터 새 라벨이 나온다. 0호 — 착륙체 시료. 1형 — 실. 2형 — 고치. 3형 — 접이. 4형 — 일꾼.<br><br>
          새 라벨 병은 거의 다 깨져 있다. 깨진 병이 한 줄로 이어진다. 선반 맨 위 칸만.`,
        o:[
          { l:'① 라벨 밑 손글씨까지 읽으며 천천히 지난다.', k:'gaze', dc:23,
            ok:`라벨마다 밑에 연구원 손글씨가 붙어 있다.<br><br>3형 — 접이. 자처럼 마디마디 접힌다고 붙인 이름이다. 펴면 문틀보다 크고 접으면 여행 가방만 하다. 눈은 없다. 두드려서 듣는다.<br>4형 — 일꾼. 다리 열둘. 막을 나른다. 사람이 흘린 것을 모은다.<br><br>통로 끝에 빈 병이 하나 있다. 깨끗하다. 깨지지 않았다. 라벨이 붙어 있다. 5형. 그 뒤는 비어 있다.`,
            ng:`읽느라 걸음이 느려졌다. 3형 병 앞에서 멈췄다. 병이 비었다. 뚜껑이 열려 있다. 위로.<br><br>병 안쪽 유리에 긁힌 자국이 있다. 자국이 위로 갈수록 깊다.<br>고개를 들었다. 위 칸에는 아무것도 없었다. 그 위 칸에도.<br><br>목덜미가 오래 시렸다. 그날 밤 아무도 위를 안 봤다.`,
            win:{ exp:17, dream:2, spirit:6 },
            lose:{ mind:-15, spirit:-17 } },
          { l:'② 깨진 병 줄 밑을 빠르게 지난다.', k:'evade', dc:24,
            doom:{ title:'위 칸의 길', what:'선반 위로 끌려 올라갑니다', dc:18, sec:52,
              text:`깨진 병이 이어진 줄 밑을 빠르게 걸었다. 유리 조각이 발밑에서 바스락거린다.<br><br>깨진 줄이 왜 위 칸에만 있는지 그때 알았다. 위 칸이 길이다. 무언가 다니는 길.<br>머리 위에서 유리가 한 번 울린다. 마디가 펴지는 소리. 선반 사이로 긴 것이 내려와 어깨를 감는다.<br><br>발이 바닥에서 떨어진다. 선반 위로 끌려 올라간다. 위 칸 병들이 줄줄이 넘어진다.`,
              dieText:`보관실 선반은 끝이 없다. 위 칸은 더 길다.<br><br>일행은 병 깨지는 소리를 따라 한참 뛰었다. 소리가 멀어지다 멎었다.<br>통로 끝 빈 병 라벨의 빈칸은 여전히 비어 있었다.` },
            ok:`깨진 줄 밑으로 가지 않았다. 한 줄 옆 통로로 비켜 같은 방향으로 갔다.<br><br>위 칸에서 무언가 같이 간다. 깨진 줄을 따라서. 선반 하나 사이를 두고.<br>통로 끝에서 그것이 멈췄다. 위 칸이 거기서 끝난다. 이쪽은 계속 갔다.<br><br>선반 사이로 마디 하나가 늘어져 있었다. 문득 접혀 올라갔다.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 맨 아래 칸에서 멀쩡한 병을 고른다.', k:'luck', dc:23, only:'luck',
            ok:`괜히 맨 아래 칸이 눈에 걸렸다. 쭈그려 앉아 손을 넣었다.<br><br>대조 시료라고 적힌 병들이다. 증류수만 든 병. 비교하려고 같이 둔다. 아무것도 안 넣은 물이다.<br>뚜껑이 밀랍으로 봉해져 있다. 셋을 챙겼다.<br><br>물에서 아무 맛도 안 난다. 여기서는 그게 제일 좋은 맛이다.`,
            ng:`맨 아래 칸에 손을 넣었는데 병이 아니라 손이 잡힌다. 차다.<br><br>뺐다. 연구복 소매가 따라 나온다. 소매 안은 비었다. 하얀 막이 말라붙어 소매 모양만 남았다.<br>손바닥에 하얀 가루가 묻었다. 털어도 오래 가렵다. 가려운 데가 조금씩 퍼진다.`,
            win:{ exp:17, dream:3, item:'맑은 물' },
            lose:{ hp:-26, spirit:-15 } }
        ] },

      { t:'보관실 — 냉장 표본고',
        x:`보관실 안쪽에 냉장 표본고가 있다. 문을 열자 하얀 김이 쏟아진다. 안은 영하다.<br><br>
          추우면 느리다. 그 말이 맞다면 여기가 이 층에서 제일 안전한 방이다.<br>
          선반 사이에 연구원 하나가 앉아 있다. 무릎을 끌어안고. 서리가 하얗게 앉았다. 숨은 없다.<br><br>
          목덜미에 혹이 있다. 달걀만 하다. 서리가 그 위에만 안 앉았다.`,
        o:[
          { l:'① 냉장고 안에서 잠깐 쉬며 숨을 고른다.', k:'steady', dc:23,
            ok:`문을 반쯤 닫고 선반 사이에 앉았다. 입김이 하얗다. 손이 곱는다.<br><br>그래도 아무것도 안 온다. 문밖에서 들리던 바스락 소리도 여기까지는 안 들어온다.<br>다들 눈을 감았다. 오래는 아니다. 열을 셀 만큼.<br><br>일어날 때 무릎이 삐걱거렸다. 앉아 있던 연구원 쪽은 아무도 안 봤다. 그쪽도 이쪽을 안 봤다.`,
            ng:`쉬는 사이에 졸았다. 추운 데서 조는 건 위험하다. 알면서 졸았다.<br><br>깨어 보니 손가락 끝이 하얗다. 감각이 없다. 비벼도 안 돌아온다.<br>문밖으로 나오니 손끝이 타는 것처럼 아프다. 피가 돌아오는 값이다.`,
            win:{ exp:16, dream:2, hp:10 },
            lose:{ hp:-28, mind:-15 } },
          { l:'② 연구원 목덜미의 혹을 살핀다.', k:'heal', dc:24,
            doom:{ title:'얼어 가는 숙주', what:'실이 손등으로 옮겨 왔습니다', dc:18, sec:50,
              text:`장갑을 벗고 혹을 짚었다. 맨손이어야 안다. 단단한지, 무른지.<br><br>혹이 따뜻하다. 서리 속에서 혼자. 짚은 손가락 밑에서 무언가 한 번 돈다.<br>손을 떼려는데 손등이 간지럽다. 혹 가장자리에서 가는 것이 나와 손등에 올라와 있다. 이쪽 손이 더 따뜻하다.<br><br>털었다. 안 털린다. 이미 살갗 밑이다. 손목 쪽으로 붉은 줄이 하나 그어진다.`,
              dieText:`실은 더 따뜻한 쪽으로 옮겨 탄다. 얼어 가는 숙주를 버리고.<br><br>그 사람은 다음 층까지 같이 걸었다. 손등을 자꾸 문질렀다.<br>그다음 층부터는 일행 맨 뒤에서 걸었다. 그리고 어느 계단참에서 보이지 않았다.` },
            ok:`장갑을 낀 채로 혹 둘레만 짚었다. 서리가 안 앉은 경계를 따라.<br><br>혹이 따뜻하다. 안에서 무언가 천천히 돈다. 몸이 얼어 가는데 혹만 버틴다.<br>목덜미 살갗 밑으로 실이 지나간 자국이 위로 나 있다. 머리 쪽으로. 그리고 다시 아래로. 길을 찾다가 얼었다.<br><br>손을 뗐다. 연구원 무릎 위에 덮인 연구복을 다시 여며 주었다.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 연구원이 왜 여기 앉았는지 본다.', k:'gaze', dc:23, only:'gaze',
            ok:`연구원 둘레를 천천히 봤다. 문 안쪽 손잡이에 연구복 허리끈이 감겨 있다. 안에서 묶었다.<br><br>스스로 들어왔다. 혹이 생긴 걸 알고. 추우면 느리다는 걸 알고. 문을 안에서 묶고 앉았다.<br>무릎 앞 바닥에 손톱으로 긁은 글씨가 있다. 열지 마시오. 서리가 그 위에도 앉았다.<br><br>나올 때 허리끈을 다시 묶어 두었다. 바깥쪽에서.`,
            ng:`오래 보는 사이 혹이 이쪽으로 기운다. 얼어붙은 목이 아주 조금 돌아간다.<br><br>서리가 갈라지는 소리가 났다. 다들 문으로 뛰었다. 문을 닫았다.<br>문 안쪽에서 한참 아무 소리도 안 났다. 그게 더 오래 귀에 남았다.`,
            win:{ exp:18, dream:3, spirit:8 },
            lose:{ mind:-16, spirit:-18 } }
        ] },

      { t:'보관실 — 대조군 수조',
        x:`벽 한 면이 수조다. 칸마다 민물고기가 산다. 비교하려고 기르던 대조군이다.<br><br>
          먹이 주는 기계가 아직 돈다. 하루 두 번, 딸깍. 물고기들은 석 달 내내 밥을 먹었다.<br>
          칸 몇 개는 물이 뿌옇다. 뿌연 칸에는 물고기가 없다. 실이 수면 가까이 떠 있다.<br><br>
          맑은 칸 물고기들은 사람을 보고 모여든다. 밥 주는 사람인 줄 안다.`,
        o:[
          { l:'① 맑은 칸을 골라 물고기를 건진다.', k:'sense', dc:23,
            ok:`칸마다 거르개 관을 따라가 봤다. 뿌연 칸끼리는 관이 하나로 이어져 있다.<br><br>관이 따로 도는 칸이 하나 있다. 물이 제일 맑다. 손을 넣었다. 물고기가 손바닥으로 모여든다.<br>두 마리를 떠냈다. 비늘이 성하고 눈이 맑다. 아마 괜찮다.<br><br>여기서 아마는 꽤 좋은 말이다.`,
            ng:`맑아 보이는 칸에 손을 넣었다. 물고기가 모여든다. 그리고 흩어진다. 한꺼번에.<br><br>손목에 가는 것이 감긴다. 바닥 자갈 사이에 숨어 있었다. 맑은 칸에도.<br>손을 빼고 수조 모서리에 손목을 쳐서 떼어 냈다. 손목에 붉은 줄이 남았다. 줄이 한참 따뜻했다.`,
            win:{ exp:17, dream:2, item:'민물고기' },
            lose:{ hp:-27, spirit:-16 } },
          { l:'② 뿌연 칸 밑 배수관을 열어 원인을 찾는다.', k:'fix', dc:24,
            doom:{ title:'수조 밑 배수관', what:'배수관 속으로 끌려 들어갑니다', dc:18, sec:50,
              text:`수조 밑 점검판을 열었다. 굵은 배수관이 바닥으로 들어간다. 이음매가 풀려 있다.<br><br>풀린 틈에 손전등을 비췄다. 관 안이 하얗다. 막이 관을 따라 끝없이 이어진다. 막 위로 다리 많은 것들이 줄지어 흐른다.<br>한 마리가 손전등 쥔 손을 문다. 둘째가 소매를 문다. 다 같이 당긴다. 물살처럼.<br><br>팔이 관 틈으로 끌려 들어간다. 어깨가 걸렸다. 관이 어깨보다 좁다. 그래도 계속 당긴다.`,
              dieText:`배수관은 사람보다 좁다. 일꾼들은 그걸 문제 삼지 않는다.<br><br>점검판은 다음 날 닫혀 있었다. 아무도 닫지 않았다.<br>대조군 수조 먹이 기계가 딸깍 했다. 물고기들이 모여들었다.` },
            ok:`점검판을 열고 손은 넣지 않았다. 관 이음매에 귀만 댔다.<br><br>관 속이 시끄럽다. 무언가 줄지어 흐른다. 물이 아니다. 다리가 많다.<br>배수관이 이 층 저 층을 다 잇는다. 놈들이 다니는 길이다. 뿌연 칸은 그 길에 붙은 칸이다.<br><br>점검판을 닫고 그 위에 소화기를 올려 두었다. 무게가 있으면 낫다. 조금은.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 내공으로 칸마다 물의 온기를 가늠한다.', k:'steady', dc:23, cost:{ qi:27 },
            ok:`손바닥을 유리에 대고 기를 흘렸다. 칸마다 온기가 다르다.<br><br>뿌연 칸은 미지근하다. 실이 사는 물은 따뜻해진다. 실이 덥히는 것이다.<br>맑은 칸 중에 하나가 조금 미지근하다. 아직 맑지만 곧 뿌예질 칸이다. 거기 물고기는 다른 칸으로 옮겨 주었다.<br><br>물고기가 사람을 고마워할 리 없다. 그래도 한 바퀴 돌고 갔다.`,
            ng:`유리에 손을 대고 기를 흘리는데 유리 너머에서 무언가 손바닥을 마주 댄다.<br><br>실 수십 가닥이 유리 안쪽에 손바닥 모양으로 모였다. 이쪽 온기를 따라.<br>손을 떼도 한참 그 모양 그대로 있었다. 기가 손끝에서 빠져나간 것처럼 팔이 저렸다.`,
            win:{ exp:17, dream:3, spirit:7 },
            lose:{ mind:-15, spirit:-17 } }
        ] },

      { t:'보관실 — 0호 관찰 일지',
        x:`관찰 책상 위에 일지가 쌓여 있다. 맨 위 것이 펼쳐져 있다. 옆에 단말이 있다. 화면은 꺼졌다.<br><br>
          펼친 장에 사진이 붙어 있다. 검은 돌이다. 냉장고만 하다. 겉에 모공 같은 구멍이 촘촘하다.<br>
          사진 밑에 날짜별로 한 줄씩 적었다. 글씨가 뒤로 갈수록 작아진다.<br><br>
          단말 전원 버튼에 먼지가 없다. 버튼 둘레만 깨끗하다. 최근에 누가 눌렀다.`,
        o:[
          { l:'① 일지를 끝까지 읽는다.', k:'gaze', dc:23,
            ok:`일지를 넘겼다. 한 줄씩.<br><br>1일. 표면 온도 삼십칠 도. 9일. 겉에 금. 금이 곧다. 14일. 금이 아니라 접힌 선. 15일. 0호 내부 비었음. 내용물 행방 모름.<br>21일. 보존액에서 1형 발견. 40일. 3형 첫 확인. 41일. 3형이 단말 버튼을 누름. 불빛이 켜지면 사람이 온다는 것을 앎.<br><br>마지막 줄. 불 켜지 말 것. 버튼 누르지 말 것. 둘째 줄은 다른 사람 글씨다.`,
            ng:`읽는 데 너무 오래 걸렸다. 스탠드 불빛에 얼굴이 따뜻해졌다.<br><br>책상 밑에서 똑, 소리가 났다. 한 번. 일지를 덮고 일어섰다.<br>일어서는 순간 의자가 넘어졌다. 소리가 보관실 끝까지 갔다. 끝에서 유리병이 차례로 울렸다. 이쪽으로.`,
            win:{ exp:18, dream:3, mind:6 },
            lose:{ mind:-16, spirit:-17 } },
          { l:'② 단말을 켜서 층 지도를 띄운다.', k:'fix', dc:24,
            doom:{ title:'파란 화면', what:'천장 위로 끌려 올라갑니다', dc:18, sec:48,
              text:`버튼을 눌렀다. 화면이 켜진다. 파란 빛이 얼굴을 비춘다. 보관실에서 제일 밝은 것이 됐다.<br><br>층 지도가 뜬다. 그걸 읽는 동안 머리 위 타일이 밀린다. 소리 없이.<br>불빛이 켜지면 사람이 온다. 그것도 안다. 그것도 온다.<br><br>정수리에 무언가 닿는다. 마디 끝이 머리카락을 쓸고 턱 밑으로 들어온다. 의자째 들린다. 천장 위로 끌려 올라간다.`,
              dieText:`단말 화면은 한참 켜져 있었다. 층 지도 위로.<br><br>빈 의자가 천천히 반 바퀴 돌았다.<br>관찰 일지 마지막 장에 아무도 한 줄을 더 적지 않았다.` },
            ok:`외투를 머리 위로 덮어쓰고 화면을 그 안에 넣었다. 빛이 밖으로 새지 않게.<br><br>층 지도가 뜬다. 여덟 층. 맨 아래 0호 격납고 옆에 지상 승강기 표시. 다른 출구는 전부 붉게 칠해져 있다. 봉쇄.<br>다 외우고 화면을 껐다. 외투를 걷었다.<br><br>머리 위 타일 하나가 한 뼘 밀려나 있었다. 아까는 안 그랬다.`,
            win:{ exp:19, dream:3 } }
        ] },

      { t:'보관실 — 깨진 배양 원통',
        x:`보관실 끝에 커다란 유리 원통이 서 있다. 사람 키보다 높다. 1형을 길러 보던 통이다.<br><br>
          원통 아래쪽이 깨져 보존액이 무릎 깊이로 고였다. 보관실 끝 문까지 다 잠겼다.<br>
          보존액 속에 실이 떠 있다. 가만히. 셀 수 없다.<br><br>
          선반들이 보존액 위로 다리처럼 서 있다. 선반 칸을 디디면 건널 수는 있다. 선반이 버틴다면.`,
        o:[
          { l:'① 선반 칸을 디뎌 건넌다.', k:'evade', dc:24,
            doom:{ title:'무릎 깊이의 보존액', what:'보존액 속으로 끌려 가라앉습니다', dc:18, sec:48,
              text:`첫 선반은 버텼다. 둘째도. 셋째 선반 다리가 보존액에 오래 잠겨 있었다.<br><br>디디는 순간 선반이 기운다. 몸이 보존액으로 떨어진다. 무릎 깊이인데 넘어지면 얼굴까지 온다.<br>실이 깬다. 한꺼번에. 수천 가닥이 그물처럼 엉겨 다리를 감는다. 따뜻한 쪽, 더 깊은 쪽으로 당긴다.<br><br>일어서려는데 바닥이 미끄럽다. 그물이 무겁다. 몸이 보존액 속으로 끌려 가라앉는다.`,
              dieText:`실은 한 가닥으로는 아무것도 못 한다.<br><br>보존액 표면이 한참 잔잔하지 않았다. 그러다 잔잔해졌다.<br>원통 바닥 쪽이 조금 따뜻해졌다. 보관실 온도계가 그만큼 올라갔다.` },
            ok:`선반 다리마다 발로 먼저 밀어 봤다. 셋째 선반이 흔들린다. 건너뛰었다.<br><br>넷째, 다섯째. 마지막 선반에서 문턱까지 한 걸음이 길다. 뛰었다. 문턱에 손이 걸렸다.<br>돌아보니 보존액이 일어서 있다. 실들이 이쪽으로 몸을 뻗고 굳어 있다. 셋째 선반 다리를 감고.<br><br>그 선반이 천천히 기울어 보존액에 잠겼다.`,
            win:{ exp:18, dream:3 } },
          { l:'② 언 연구복을 뒤집어쓰고 벽 가장자리 얕은 데로 돈다.', k:'hide', dc:23,
            ok:`냉장 표본고에서 언 연구복을 몇 벌 가져왔다. 서리가 앉은 채로 뒤집어썼다.<br><br>벽을 따라 바닥이 조금 높다. 보존액이 발목에서 찰랑인다. 천천히 걸었다. 숨은 연구복 안에 뱉었다.<br>실들이 일어서다 만다. 지나가는 것이 따뜻한지 모르겠다는 듯이.<br><br>문턱에 닿아서 연구복을 벗었다. 서리가 다 녹아 있었다. 그만큼 이쪽이 따뜻했다는 뜻이다.`,
            ng:`연구복이 생각보다 빨리 녹았다. 반쯤 갔을 때 옷이 체온만큼 따뜻해졌다.<br><br>실들이 일어선다. 발목으로 몰려온다. 뛰었다. 첨벙거렸다.<br>문턱에 닿아서 장화를 뒤집어 털었다. 장화 속에서 세 가닥이 나왔다. 정강이에 붉은 줄이 둘 그어져 있었다.`,
            win:{ exp:17, dream:2 },
            lose:{ hp:-29, mind:-15, spirit:-16 } },
          { l:'③ 마력으로 보존액을 식혀 실을 재운다.', k:'fix', dc:23, cost:{ mana:27 },
            ok:`원통 깨진 데에 손을 대고 찬 기운을 흘렸다. 보존액이 걸쭉해진다. 서리가 표면을 덮는다.<br><br>실들이 하나씩 구부러져 바닥으로 내려앉는다. 잠드는 것처럼.<br>얼어붙은 표면 위로 일행이 지났다. 발밑에서 얼음이 운다. 그 밑에서 실은 움직이지 않는다.<br><br>문턱을 넘고 손을 뗐다. 손바닥이 원통에 붙어 살갗이 조금 남았다. 그 정도는 괜찮다.`,
            ng:`보존액이 너무 많다. 마력이 다 퍼지기 전에 가장자리부터 다시 녹는다.<br><br>반쯤 언 표면 위에 올라선 사람 발밑이 꺼졌다. 얼음 조각과 함께 무릎까지 빠졌다.<br>끌어냈다. 정강이에 실이 셋 붙어 있었다. 둘은 떼었다. 하나는 칼끝으로 파냈다.`,
            win:{ exp:18, dream:3 },
            lose:{ hp:-30, mind:-16 } }
        ] },

      { t:'보관실 — 일꾼의 행렬',
        x:`선반 사이 통로로 무언가 줄지어 지나간다. 고양이만 한 것들이다. 다리가 열둘. 라벨에 적혀 있던 4형, 일꾼이다.<br><br>
          등에 하얀 막을 한 장씩 지고 간다. 막은 접혀 있다. 빨래처럼.<br>
          줄은 이쪽 벽 환기구에서 나와 저쪽 벽 환기구로 들어간다. 끊이지 않는다.<br><br>
          가야 할 문은 줄 건너편이다. 일꾼들은 이쪽을 안 본다. 아직은.`,
        o:[
          { l:'① 줄이 끊길 때까지 선반 뒤에서 기다린다.', k:'steady', dc:23,
            ok:`선반 뒤에 붙어 기다렸다. 일꾼들이 지나간다. 서른, 마흔.<br><br>쉰을 넘기자 줄에 틈이 생긴다. 막을 다 나른 모양이다. 다음 줄이 나오기까지 숨 다섯 번.<br>숨 다섯 번 안에 다 건넜다. 마지막 사람이 건널 때 환기구에서 다음 일꾼이 머리를 내밀었다.<br><br>그것이 고개를 갸웃했다. 그리고 막을 지고 지나갔다.`,
            ng:`기다리는 동안 한 마리가 줄에서 빠져 이쪽으로 온다. 떨어진 장갑을 주우러.<br><br>장갑은 이쪽 발 옆에 있었다. 일꾼이 장갑을 물고 발목도 같이 문다. 둘 다 사람이 흘린 것인 줄 안다.<br>발로 차서 떼어 냈다. 발목에 이빨 자국이 둥글게 났다. 일꾼은 장갑만 가지고 줄로 돌아갔다.`,
            win:{ exp:17, dream:2 },
            lose:{ hp:-29, spirit:-16 } },
          { l:'② 줄 사이 틈으로 뛰어 건넌다.', k:'evade', dc:24,
            doom:{ title:'떨어진 것', what:'일꾼 떼에 실려 갑니다', dc:18, sec:48,
              text:`줄 사이가 벌어진 순간 뛰었다. 한 걸음, 두 걸음.<br><br>세 걸음째에 발이 막을 밟았다. 일꾼 하나가 떨어뜨린 막이다. 끈적하다. 발이 붙는다. 넘어졌다.<br>줄이 멈춘다. 일꾼들이 한꺼번에 이쪽을 본다. 바닥에 떨어진 것, 사람이 흘린 것.<br><br>밑으로 다리 많은 것들이 파고든다. 몸이 들린다. 등과 다리 밑에 일꾼이 빼곡하다. 줄이 다시 움직인다. 이쪽을 싣고.`,
              dieText:`일꾼은 떨어진 것을 줍는다. 크기를 가리지 않는다.<br><br>줄은 저쪽 벽 환기구로 들어갔다. 늘 그랬듯이 끊이지 않고.<br>바닥에 신발 한 짝만 남았다. 다음 줄의 일꾼이 그것도 실어 갔다.` },
            ok:`줄 사이가 벌어진 순간 뛰었다. 바닥의 떨어진 막을 건너뛰었다. 세 걸음에 건넜다.<br><br>일꾼들이 잠깐 멈췄다. 고개를 돌린다. 다시 걷는다. 지나간 것은 줍지 않는다.<br>그것들이 신경 쓰는 건 떨어진 것이다. 서 있는 것이 아니라.<br><br>그 말을 일행에게 했다. 다들 다리에 힘을 줬다.`,
            win:{ exp:18, dream:3 } },
          { l:'③ 무력으로 맨 끝 일꾼을 잡아 꺾는다.', k:'break', dc:23, cost:{ might:27 },
            ok:`줄 맨 끝 놈을 노렸다. 등을 잡고 들어 올려 선반 모서리에 내리쳤다. 무력을 실어서. 한 번에.<br><br>다리가 한참 오므렸다 펴졌다. 피가 맑다. 장갑에 닿은 데가 연기를 낸다. 연하다. 큰 놈들 것보다는.<br>다리 밑동 살을 잘라 젖은 천에 쌌다. 단단하고 하얗다. 게살 같다. 아마 먹을 수 있다.<br><br>줄은 멈추지 않았다. 하나가 빠진 걸 아무도 세지 않는다.`,
            ng:`등을 잡았는데 미끄러졌다. 일꾼이 몸을 비틀어 손목을 물었다.<br><br>떼어 내려고 쥐어짜는 사이 맑은 피가 손등으로 튀었다. 장갑이 녹는다. 살갗도.<br>놓쳤다. 일꾼은 다리 하나를 절며 줄로 돌아갔다. 손등에 동전만 한 구멍이 났다.`,
            win:{ exp:18, dream:3, item:'짐승 고기' },
            lose:{ hp:-31, mind:-14 } }
        ] },

      { t:'보관실 — 구멍 난 계단',
        x:`보관실 끝 문 너머가 계단이다. 디딤판 군데군데 구멍이 나 있다. 가장자리가 매끈하다.<br><br>
          구멍 밑으로 다음 층 계단이 보인다. 그 밑의 계단도.<br>
          계단참 그늘에 무언가 접혀 있다. 여행 가방만 하다. 마디가 차곡차곡 겹쳤다.<br><br>
          자는지 기다리는지 모른다. 접이는 펴지기 전에는 구분이 안 된다.`,
        o:[
          { l:'① 난간을 타고 미끄러져 단숨에 내려간다.', k:'evade', dc:24,
            doom:{ title:'계단참의 가방', what:'계단 밑으로 끌려 내려갑니다', dc:18, sec:48,
              text:`난간에 걸터앉아 미끄러졌다. 빠르다. 계단참이 금방이다.<br><br>계단참을 지나는 순간 그늘의 가방이 열린다. 접혀 있던 마디가 한꺼번에 펴진다. 철컥, 철컥, 철컥.<br>펴진 끝이 발목을 낚았다. 난간에서 몸이 떨어진다. 디딤판 구멍 위로.<br><br>구멍 아래로 몸이 반쯤 빠졌다. 아래에서도 당긴다. 계단 밑으로 끌려 내려간다.`,
              dieText:`접이는 펴지기 전에는 자는지 기다리는지 모른다.<br><br>펴지고 나면 안다. 기다리고 있었다.<br>계단참 그늘에 다시 무언가 접혀 있었다. 이번엔 조금 더 컸다.` },
            ok:`난간에 걸터앉아 미끄러졌다. 계단참 직전에 손을 놓고 뛰어내렸다. 그늘 반대편으로.<br><br>그늘의 가방이 마디 하나를 펴 허공을 쓸었다. 방금 이쪽 발이 있던 자리를.<br>다음 난간으로 넘어가 또 미끄러졌다. 뒤에서 철컥, 철컥. 따라오지는 않는다. 아직.<br><br>일행도 하나씩 같은 데서 뛰었다. 마지막 사람 때는 그늘이 비어 있었다.`,
            win:{ exp:19, dream:3 } },
          { l:'② 서로 손목을 잡고 벽에 붙어 한 단씩 내려간다.', k:'bond', dc:23,
            ok:`일행이 손목을 엮어 한 줄이 됐다. 벽에 등을 붙이고 구멍 없는 칸만 디뎠다.<br><br>계단참을 지날 때 그늘의 가방과 팔 하나 거리였다. 아무도 숨을 안 쉬었다.<br>사람이 하나 지날 때마다 마디가 아주 조금씩 펴졌다. 한 칸씩.<br><br>다 내려가서 돌아보니 마디가 지나간 사람 수만큼 펴져 있다. 세고 있었다.`,
            ng:`가운데 사람 발이 구멍 가장자리를 디뎠다. 디딤판이 우그러진다. 쇳소리.<br><br>그늘이 펴진다. 일행이 손목을 놓지 않고 한꺼번에 뛰었다. 다 같이 엉켜 계단을 굴렀다.<br>아래층 문에 부딪혀 멈췄다. 위에서 철컥 소리가 한 번 나고 조용해졌다. 갈비가 결린다. 다들 결린다.`,
            win:{ exp:18, dream:3, mind:6 },
            lose:{ hp:-32, mind:-15 } }
        ] }
    ] },

    // ───────── 3층 ─────────
    { name:'3층 — 연구동', scenes:[

      { t:'연구동 — 해부실',
        x:`해부실 가운데 철제 해부대가 있다. 해부대 위에 3형이 누워 있다. 반만.<br><br>
          허리 아래가 없다. 잘린 자리에서 흐른 맑은 피가 해부대를 뚫고 바닥까지 구멍을 냈다. 구멍 가장자리가 아직 김을 낸다.<br>
          얼굴이 없다. 얼굴 자리에 매끈한 판이 있고, 판 한가운데를 세로로 솔기가 지난다.<br><br>
          펴면 사람 키 두 배는 될 팔이 해부대 밖으로 늘어졌다. 손가락이 한 번 오므라들었다. 일행이 들어설 때.`,
        o:[
          { l:'① 얼굴판의 솔기를 멀리서 들여다본다.', k:'gaze', dc:24,
            ok:`가까이 가지 않았다. 해부대 둘레를 돌며 손전등으로 판만 비췄다.<br><br>솔기는 닫혀 있다. 가장자리에 아주 가는 털이 줄지어 났다. 바람에도 떨린다. 귀다. 판 전체가 귀다.<br>솔기 바로 밑, 판이 목과 이어지는 데만 얇다. 손가락 한 마디 두께. 나머지는 쇠처럼 두껍다.<br><br>해부대 옆 기록지에도 같은 자리에 동그라미가 쳐져 있다. 그 옆에 적혀 있다. 여기. 다만 피.`,
            ng:`더 잘 보려고 몸을 숙였다. 숨이 판에 닿았다.<br><br>솔기가 벌어진다. 반만 남은 것이. 안에서 김이 훅 나온다. 식초 냄새.<br>얼굴이 화끈하다. 눈을 감고 물러섰다. 눈꺼풀이 붓는다. 한참 한쪽 눈으로만 봤다.`,
            win:{ exp:18, dream:3, spirit:6 },
            lose:{ hp:-28, mind:-16 } },
          { l:'② 해부대의 메스로 솔기 밑을 찌른다.', k:'break', dc:24,
            doom:{ title:'반만 남은 것', what:'맑은 피를 뒤집어썼습니다', dc:18, sec:50,
              text:`메스를 쥐고 솔기 밑 얇은 데를 찔렀다. 들어간다. 생각보다 쉽게.<br><br>반만 남은 몸이 활처럼 휜다. 늘어졌던 팔이 해부대를 친다. 해부대가 뒤집힌다.<br>찌른 자리에서 맑은 것이 뿜어 나온다. 메스 쥔 손등으로, 소매로, 가슴으로.<br><br>처음엔 물 같다. 차갑다. 그다음에 뜨겁다. 옷이 녹는 소리가 들린다. 단내가 난다.`,
              dieText:`베면 그 밑에 서 있지 마라. 누가 그렇게 적어 두었다.<br><br>해부실 바닥에 구멍이 하나 더 났다. 가장자리가 매끈하지 않다.<br>반만 남은 것은 그 뒤로 다시는 손가락을 오므리지 않았다.` },
            ok:`메스를 대걸레 자루 끝에 테이프로 감았다. 팔 길이 두 배 떨어져서 솔기 밑을 찔렀다.<br><br>반만 남은 몸이 활처럼 휜다. 찌른 자리에서 맑은 것이 뿜어 나와 바닥에 쏟아진다. 이쪽 발끝 한 뼘 앞까지.<br>자루를 놓고 물러섰다. 자루 끝이 녹아 짧아진다.<br><br>그것은 다시 손가락을 오므리지 않았다. 어디를 찌르면 되는지 이제 손이 안다.`,
            win:{ exp:20, dream:3 } },
          { l:'③ 약품장에서 산에 데인 데 바를 것을 찾는다.', k:'heal', dc:24, only:'heal',
            ok:`약품장 문에 중화용이라고 적힌 칸이 따로 있다. 하얀 가루 봉지와 연고 통.<br><br>치유하는 손은 순서를 안다. 가루를 먼저 뿌려 남은 것을 죽이고, 씻고, 연고는 그다음이다.<br>일행 손등과 발목에 난 자국에 차례로 발랐다. 다들 이를 악물었다가 풀었다.<br><br>가루 봉지를 남은 만큼 다 챙겼다. 아래층에도 맑은 것은 있을 것이다.`,
            ng:`칸마다 이름이 약자로만 적혀 있다. 연고라고 생각한 통을 열었다.<br><br>바르자마자 상처가 더 탄다. 소독용 알코올 젤이다. 산 자국에는 불을 붓는 셈이다.<br>한참 물로 씻었다. 물이 귀한데 반 통을 썼다.`,
            win:{ exp:18, dream:3, hp:12 },
            lose:{ hp:-29, mind:-16 } }
        ] },

      { t:'연구동 — 식물 시험실',
        x:`식물 시험실은 유리방이다. 안이 덥고 축축하다. 조명이 아직 켜져 있다. 하루 열여섯 시간.<br><br>
          화분과 화단이 빽빽하다. 약초와 나물이 웃자랐다. 석 달 동안 아무도 따지 않았다.<br>
          화단 흙 군데군데에 주먹만 한 구멍이 있다. 구멍 둘레 흙이 바깥으로 밀려 나왔다.<br><br>
          더운 데를 좋아하는 것은 사람만이 아니다.`,
        o:[
          { l:'① 약초 화분 줄을 살펴 쓸 만한 것을 딴다.', k:'sense', dc:24,
            ok:`화분마다 꽂힌 이름표를 따라갔다. 지혈, 해열, 진통. 실험용이라 이름표가 친절하다.<br><br>흙 표면을 손끝으로 눌러 보고 구멍이 없는 화분만 골랐다. 잎이 두껍고 향이 세다.<br>한 줌씩 끊어 묶었다. 화분 밑에서 아무것도 안 나왔다.<br><br>이름표 뒷면에 누가 적어 두었다. 다 자라면 줄 것. 받을 사람 이름은 지워져 있다.`,
            ng:`화분 하나를 들자 밑에서 무언가 튀어나온다. 다리가 많다. 작다. 손등을 타고 팔꿈치까지 뛴다.<br><br>털어냈다. 털린 자리에 이빨 자국이 줄지어 났다. 화분이 떨어져 깨졌다.<br>깨진 흙 속에 굴이 나 있다. 굴이 화단까지 이어진다. 화단 흙이 움찔한다.`,
            win:{ exp:18, dream:3, item:'약초 뭉치' },
            lose:{ hp:-30, spirit:-17 } },
          { l:'② 화단 가운데 웃자란 나물을 뜯는다.', k:'luck', dc:24,
            doom:{ title:'푹신한 화단', what:'화단 흙 밑으로 끌려 들어갑니다', dc:18, sec:48,
              text:`화단에 발을 들였다. 흙이 푹신하다. 너무 푹신하다.<br><br>나물을 한 움큼 쥐고 뽑았다. 뿌리째 딸려 나온다. 뿌리 끝에 다리가 붙어 있다. 흙 속에 있던 일꾼이 뿌리를 물고 있었다.<br>발밑 흙이 꺼진다. 화단 밑은 흙이 아니라 굴이다. 굴마다 일꾼이다.<br><br>정강이를 문다. 무릎을 문다. 흙과 함께 몸이 아래로 끌려 들어간다. 손에 쥔 나물은 놓지 않았다. 놓을 생각을 못 했다.`,
              dieText:`식물 시험실 조명은 하루 열여섯 시간 켜진다.<br><br>화단 가운데에 흙이 조금 솟았다. 그 위로 나물이 웃자랐다. 다른 데보다 조금 더 빨리.<br>일꾼들은 화단을 가꾼다. 그렇게 보였다.` },
            ok:`화단 가장자리에 무릎을 꿇고 팔만 뻗었다. 흙은 안 밟았다.<br><br>나물을 줄기째 끊었다. 뿌리는 남겼다. 뿌리 쪽 흙이 움찔했다. 누가 밑에서 기다리고 있었다.<br>끊은 나물을 품에 넣고 물러섰다. 화단 흙이 한 번 솟았다가 가라앉았다.<br><br>여린 순이다. 쓴맛이 적다. 이 방에서 석 달 동안 자란 것 중에 사람이 먹을 수 있는 몇 안 되는 것이다.`,
            win:{ exp:19, dream:3, item:'산나물' } },
          { l:'③ 마력으로 시험실 온도를 떨어뜨린다.', k:'fix', dc:24, cost:{ mana:28 },
            ok:`천장의 온열등 쪽으로 찬 기운을 밀어 올렸다. 유리방에 서리가 핀다.<br><br>화단 구멍마다 일꾼이 하나씩 기어 나온다. 느리다. 다리가 굳었다. 줄을 지어 환기구로 기어간다. 따뜻한 데를 찾아서.<br>빈 화단에서 나물을 넉넉히 뜯었다. 흙이 차다. 아무것도 안 움직인다.<br><br>나갈 때 돌아보니 서리 낀 유리에 다리 많은 발자국이 한 줄로 찍혀 있었다.`,
            ng:`온도를 떨어뜨리는데 온열등이 더 세게 켜진다. 온도 조절기가 버틴다. 마력과 기계가 씨름한다.<br><br>그사이 화단 구멍에서 일꾼들이 기어 나온다. 느리지 않다. 화가 났다.<br>뛰었다. 종아리를 여러 군데 물렸다. 유리문을 닫았다. 문 너머가 하얗게 김이 서렸다.`,
            win:{ exp:19, dream:3, item:'산나물' },
            lose:{ hp:-31, mind:-16, spirit:-17 } }
        ] },

      { t:'연구동 — 버섯 재배실',
        x:`재배실 선반마다 톱밥 자루가 놓여 있다. 자루 구멍마다 버섯이 피었다. 하얗고 통통하다.<br><br>
          습도계 바늘이 끝까지 가 있다. 벽에 물이 흐른다. 바닥 배수구가 막혔다.<br>
          버섯 갓 위에 가는 실이 한 가닥씩 걸쳐 있는 것도 있다. 버섯 실일 수도 있다. 아닐 수도 있다.<br><br>
          재배실 저편 문까지 선반이 빽빽하다. 사이 길이 좁다.`,
        o:[
          { l:'① 갓 밑을 하나씩 들춰 가려 딴다.', k:'gaze', dc:24,
            ok:`갓을 손가락으로 살짝 들어 밑을 봤다. 주름이 곧은 것, 주름 사이에 아무것도 없는 것.<br><br>열에 셋은 주름 사이에 가는 것이 끼어 있다. 버섯 실이 아니다. 끝이 움직인다. 그런 건 두었다.<br>나머지만 땄다. 하얗고 단단하다. 톱밥 냄새가 난다. 여기서 맡은 냄새 중에 제일 멀쩡하다.<br><br>다 따고 보니 남겨 둔 갓들이 이쪽으로 기울어 있다. 따는 동안 손이 따뜻했던 모양이다.`,
            ng:`갓을 들추는 순간 주름 사이에서 가는 것이 튀어나와 손가락 사이에 감긴다.<br><br>뿌리쳤다. 손가락 사이 살갗이 쓰리다. 실이 지나간 자리가 붉게 부푼다.<br>칼끝으로 자리를 째고 짜냈다. 한참 피가 났다. 피가 멎을 때까지 다들 그 손만 봤다.`,
            win:{ exp:18, dream:3, item:'야생 버섯' },
            lose:{ hp:-30, mind:-17 } },
          { l:'② 선반을 밀어 넘어뜨려 길을 낸다.', k:'break', dc:24,
            doom:{ title:'엎어진 둥지', what:'선반 밑으로 끌려 들어갑니다', dc:18, sec:48,
              text:`선반을 어깨로 밀었다. 넘어간다. 옆 선반을 치고, 그 옆 선반을 치고. 길이 열린다.<br><br>넘어진 선반 밑에서 일꾼 떼가 쏟아져 나온다. 톱밥 자루 사이가 둥지였다. 축축하고 따뜻한.<br>둥지를 엎은 쪽은 이쪽이다. 일꾼들이 이쪽 다리로 몰린다. 넘어졌다.<br><br>넘어진 선반 밑 틈으로 다리가 끌려 들어간다. 무릎, 허리. 톱밥 자루가 얼굴을 덮는다. 축축하다.`,
              dieText:`일꾼은 엎어진 둥지를 다시 짓는다. 재료를 가리지 않는다.<br><br>재배실 선반은 넘어진 채로 그 밑이 조금 높아졌다.<br>버섯이 그 위에 먼저 피었다.` },
            ok:`선반을 밀기 전에 밑을 발로 두드렸다. 톱밥 자루 사이에서 바스락 소리가 난다. 둥지다.<br><br>둥지 없는 쪽 선반만 골라 밀었다. 하나, 둘. 쓰러지며 길이 열린다. 소리가 컸다.<br>둥지 쪽 선반 밑에서 일꾼들이 고개를 내민다. 넘어진 데에 아무도 없는 걸 보고 다시 들어간다.<br><br>열린 길로 빠져나왔다. 문을 닫고 문틈을 젖은 자루로 막았다.`,
            win:{ exp:19, dream:3 } }
        ] },

      { t:'연구동 — 격리 병실',
        x:`복도 끝에 격리 병실이 있다. 문에 유리창이 달려 있다. 안에 사람이 있다. 살아 있다.<br><br>
          연구복을 입었다. 침대에 걸터앉아 이쪽을 본다. 얼굴이 발갛다. 열이 있다. 목덜미가 불룩하다.<br>
          창을 똑똑 두드린다. 입 모양을 천천히 만든다. 물.<br><br>
          병실 문은 밖에서 잠겨 있다. 잠금 장치 옆에 배식구 버튼이 있다. 버튼 둘레가 반질반질하다. 많이 눌린 버튼이다.`,
        o:[
          { l:'① 배식구로 물을 넣어 준다.', k:'bond', dc:24,
            ok:`배식구 버튼을 눌렀다. 작은 칸이 열린다. 물병을 넣고 다시 눌렀다.<br><br>안쪽에서 연구원이 물병을 꺼내 마신다. 오래 마신다. 다 마시고 이쪽을 본다. 그리고 이쪽 머리 위를 본다.<br>입 모양이 바뀐다. 뒤.<br><br>돌아보지 않고 옆으로 물러섰다. 복도 천장 타일 하나가 소리 없이 제자리로 닫혔다. 연구원이 손바닥을 유리에 댔다. 다시는 물을 달라고 하지 않았다.`,
            ng:`배식구에 물병을 넣는 동안 정수리에 무언가 떨어진다. 한 방울. 차다.<br><br>그다음에 뜨겁다. 머리카락이 타는 냄새. 천장 타일 틈에서 맑은 것이 새고 있다.<br>물러섰다. 정수리에서 목덜미로 흘러내린 자리가 한 줄로 탔다. 병실 안의 사람이 고개를 숙였다. 미안하다는 듯이.`,
            win:{ exp:19, dream:3, spirit:6 },
            lose:{ hp:-32, spirit:-18 } },
          { l:'② 병실 문을 열어 데리고 나간다.', k:'fix', dc:24,
            doom:{ title:'미끼', what:'병실 안으로 끌려 들어갑니다', dc:19, sec:48,
              text:`잠금 장치를 풀었다. 문이 열린다. 안이 덥다.<br><br>연구원은 일어서지 않는다. 침대에 앉은 채 고개만 젓는다. 천천히. 그리고 눈이 위로 간다. 병실 천장으로.<br>병실 천장 환기구에 덮개가 없다. 거기서 마디 많은 것이 펴져 내려온다. 문 바로 위다.<br><br>목덜미를 잡혔다. 문턱에 발이 걸린다. 몸이 병실 안으로 끌려 들어간다. 연구원이 눈을 감는다.`,
              dieText:`격리 병실 배식구 버튼은 많이 눌린 버튼이다.<br><br>병실 문은 다시 잠겼다. 잠그는 법은 그것도 안다.<br>창 안쪽의 사람은 다음 사람이 올 때까지 기다렸다. 물을 달라고 하지 않고.` },
            ok:`잠금을 풀되 문을 활짝 열지 않았다. 발로 문 밑을 받치고 한 뼘만 열었다.<br><br>연구원이 일어서지 않는다. 고개를 젓는다. 손가락으로 위를 가리킨다. 병실 천장 환기구에 덮개가 없다.<br>문을 도로 닫았다. 닫히는 틈으로 위에서 무언가 펴지는 소리가 났다. 철컥.<br><br>잠금을 다시 걸었다. 연구원이 창을 똑똑 두드렸다. 세 번. 이번엔 부르는 소리가 아니었다. 고맙다는 것이다. 그렇게 믿기로 했다.`,
            win:{ exp:20, dream:3 } },
          { l:'③ 혹과 눈을 함께 본다.', k:'gaze', dc:24, only:'gaze',
            ok:`연구원의 눈을 봤다. 이쪽을 보다가 자꾸 이쪽 머리 위로 간다. 한 번, 또 한 번. 일부러.<br><br>목덜미 혹은 복도 벽 속의 두드림과 같은 박자로 뛴다. 똑, 똑, 똑. 혹이 무엇을 기다리는지 안다.<br>이 사람은 미끼다. 스스로 알고 있다. 그래서 눈으로 위를 가리킨다.<br><br>창에 손바닥을 댔다. 안에서도 댔다. 그리고 천장 타일 밑을 피해 벽에 붙어 지나갔다.`,
            ng:`너무 오래 봤다. 혹이 이쪽으로 돈다. 살갗 밑에서 방향을 바꾸는 게 보인다.<br><br>연구원 얼굴이 일그러진다. 혹이 이쪽을 향하면 숙주가 아프다.<br>눈을 돌렸다. 연구원은 한참 웅크리고 있었다. 이쪽이 아프게 한 것 같아서 한참 등이 무거웠다.`,
            win:{ exp:19, dream:3, mind:7 },
            lose:{ mind:-17, spirit:-19 } }
        ] },

      { t:'연구동 — 실장실',
        x:`실장실 문패가 비뚤게 걸렸다. 안은 정돈되어 있다. 이 층에서 유일하게.<br><br>
          책상 위에 봉쇄 절차서가 펼쳐져 있다. 볼펜 밑줄이 뒤로 갈수록 세진다. 마지막 밑줄은 종이를 찢었다. 서랍 하나가 반쯤 열려 있다.<br>
          책상 밑 바닥 환기구에 덮개가 없다. 덮개는 방 구석에 얌전히 세워져 있다. 나사 넷과 함께.<br><br>
          환기구 바로 옆에 열쇠 꾸러미가 떨어져 있다. 꼬리표에 비상계단이라고 적혀 있다.`,
        o:[
          { l:'① 책상 밑으로 기어 들어가 열쇠를 줍는다.', k:'sense', dc:24,
            doom:{ title:'책상 밑 열쇠', what:'바닥 환기구 속으로 끌려갑니다', dc:19, sec:48,
              text:`책상 밑으로 기어 들어갔다. 열쇠가 환기구 바로 옆이다. 손을 뻗었다.<br><br>열쇠를 쥐는 순간 꾸러미가 당겨진다. 열쇠 고리에 가는 막이 한 줄 붙어 있다. 환기구 안으로 이어진다. 낚싯줄처럼.<br>놓아야 하는데 손가락이 고리에 걸렸다. 환기구 안에서 무언가 줄을 감는다.<br><br>팔이 환기구로 끌려 들어간다. 어깨가 바닥에 붙는다. 책상 다리를 잡았다. 책상이 같이 끌려간다.`,
              dieText:`미끼를 놓는 것은 사람만이 아니다.<br><br>실장실 책상은 다음 날 한 뼘 옮겨져 있었다. 환기구 쪽으로.<br>열쇠 꾸러미는 다시 그 자리에 떨어져 있었다. 꼬리표가 위를 보게.` },
            ok:`책상 밑으로 들어가지 않았다. 의자 다리를 뽑아 끝으로 열쇠를 끌어당겼다.<br><br>열쇠가 따라오다 멈춘다. 고리에 가는 막이 한 줄 붙어 환기구로 이어져 있다. 낚싯줄처럼.<br>의자 다리로 막을 눌러 끊었다. 환기구 안에서 무언가 줄을 감다가 멈췄다.<br><br>열쇠를 주웠다. 비상계단. 미끼였다. 그래도 진짜 열쇠다.`,
            win:{ exp:20, dream:3 } },
          { l:'② 반쯤 열린 서랍을 뒤진다.', k:'luck', dc:24,
            ok:`서랍 안에 찻잔과 작은 단지가 있다. 단지 뚜껑에 실장이라고 적혀 있다.<br><br>꿀이다. 굳어서 하얗다. 실장이 차에 타 먹던 것이다.<br>찻잔에 남은 차는 말라 고리 모양 얼룩만 남았다. 마지막 잔을 다 마시지 못했다.<br><br>단지를 챙겼다. 꿀은 안 썩는다. 실장도 그걸 알았을 것이다.`,
            ng:`서랍을 끝까지 당기자 안쪽에서 무언가 굴러 나온다. 유리병이다. 작다. 1형이라고 적혀 있다. 뚜껑이 없다.<br><br>병은 비었다. 서랍 바닥이 젖어 있다. 젖은 자리가 이쪽 손가락 끝까지 와 있다.<br>손을 뺐다. 손톱 사이가 간지럽다. 한참 손톱 밑을 바늘로 쑤셨다. 아무것도 안 나왔다. 그래도 계속 쑤셨다.`,
            win:{ exp:18, dream:3, item:'꿀 한 줌' },
            lose:{ mind:-17, spirit:-19 } },
          { l:'③ 절차서의 밑줄 친 데만 이어 읽는다.', k:'fix', dc:24, only:'fix',
            ok:`밑줄 친 말만 이어 읽었다. 세지는 순서대로.<br><br>문은 손으로 잠글 것. 불은 끄고 다닐 것. 기밀실 배기 밸브는 반드시 먼저 잠글 것. 3형은 버튼을 배운다.<br>마지막 찢어진 밑줄. 승강기 앞에 그것이 앉아 있다.<br><br>순서를 일행에게 그대로 말했다. 다들 외웠다. 외울 것이 있다는 게 조금 위로가 됐다.`,
            ng:`밑줄을 따라 읽는데 어느 순간부터 밑줄이 글자를 벗어난다. 종이 밖으로, 책상으로, 책상 모서리로.<br><br>밑줄이 아니라 긁힌 자국이었다. 책상 모서리에서 환기구 쪽으로 이어진다. 손톱이다. 사람 손톱.<br>절차서를 덮었다. 덮은 손이 오래 떨렸다.`,
            win:{ exp:19, dream:3, mind:8 },
            lose:{ mind:-18, spirit:-18 } }
        ] },

      { t:'연구동 — 전기실',
        x:`이 층 끝이 전기실이다. 불이 꺼졌다. 손전등을 비추자 배전반이 열려 있다.<br><br>
          굵은 전선이 다발로 끊겨 있다. 끊긴 자리가 매끈하지 않다. 녹인 게 아니다. 눌러 끊었다. 하나씩 골라서.<br>
          끊기지 않은 선이 딱 하나 남았다. 피복이 벗겨졌다.<br><br>
          골라서 끊고 골라서 남긴 것이다. 그런 걸 고르는 것은 짐승이 아니다.`,
        o:[
          { l:'① 배전반을 손봐 불을 살린다.', k:'fix', dc:24,
            doom:{ title:'골라 남긴 선', what:'전선이 손을 놓지 않습니다', dc:19, sec:46,
              text:`배전반 안으로 손을 넣었다. 끊긴 다발을 하나씩 짚었다. 다 죽었다.<br><br>손이 자연스럽게 가는 자리가 있다. 차단기 손잡이 바로 밑. 거기 남은 선 하나가 피복이 벗겨진 채 걸쳐 있다.<br>손등이 닿았다. 팔이 굳는다. 손가락이 저절로 오므라든다. 선을 쥔다. 놓을 수가 없다.<br><br>골라서 남긴 선이다. 사람 손이 갈 자리에.`,
              dieText:`짐승은 덫을 놓지 않는다. 짐승이 아니면 놓는다.<br><br>배전반 앞에 연기가 한참 피었다. 그러다 차단기가 내려갔다. 저절로.<br>복도 끝 천장에서 똑, 똑, 똑. 다 됐다는 듯이.` },
            ok:`손을 넣기 전에 손전등으로 배전반 안을 한 칸씩 비췄다.<br><br>차단기 손잡이 바로 밑에 피복 벗겨진 선 하나가 걸쳐 있다. 손이 가장 자연스럽게 갈 자리다. 일부러 거기 두었다.<br>고무장갑을 두 겹 끼고 그 선부터 걷어 냈다. 나머지 끊긴 다발을 이었다. 불이 반쯤 들어온다.<br><br>불이 들어오자 복도가 보인다. 천장 전체에 긁힌 자국이 있다. 길처럼. 수십 줄.`,
            win:{ exp:20, dream:3 } },
          { l:'② 불 없이 벽을 짚어 문턱을 넘는다.', k:'steady', dc:24,
            ok:`손전등을 끄고 벽을 짚었다. 문턱까지 열두 걸음.<br><br>문턱 앞에서 발끝으로 바닥을 쓸었다. 선이 있다. 피복이 벗겨졌다. 발끝으로 위치를 쟀다. 크게 넘었다.<br>뒤에 오는 사람마다 발목을 잡아 넘을 자리를 알려 주었다.<br><br>문을 나와서 손전등을 켰다. 선 끝이 문턱 쇠에 감겨 있었다. 문턱 전체가 덫이었다.`,
            ng:`벽을 짚어 가다가 문턱에서 발이 선을 밟았다.<br><br>몸이 한 번 튄다. 이가 딱 부딪친다. 뒤로 넘어졌다. 넘어지면서 선에서 떨어졌다. 그게 살았다.<br>한참 일어나지 못했다. 다리가 남의 것 같다. 심장이 두 번에 한 번 건너뛴다.`,
            win:{ exp:18, dream:3 },
            lose:{ hp:-33, mind:-17 } },
          { l:'③ 내공으로 전류가 흐르는 길을 읽는다.', k:'sense', dc:24, cost:{ qi:28 },
            ok:`손바닥을 바닥 가까이 대고 기를 펼쳤다. 흐르는 것은 기척이 있다. 벌레가 우는 것처럼 아주 작게.<br><br>남은 선을 따라 기척이 간다. 문턱 쇠로, 그리고 문 손잡이로. 손잡이까지 이어 놓았다.<br>손잡이는 건드리지 않고 신발 밑창으로 문짝을 밀어 열었다.<br><br>손잡이에 손바닥 자국이 그을려 있었다. 먼저 잡은 사람이 있었다.`,
            ng:`기를 펼쳤는데 전류가 기를 타고 들어온다. 손바닥이 데었다.<br><br>기가 흩어지고 손이 저려 한동안 주먹이 안 쥐어진다.<br>일행이 대신 문을 열었다. 신발 밑창으로. 이쪽은 손을 겨드랑이에 끼고 따라갔다.`,
            win:{ exp:19, dream:3, spirit:7 },
            lose:{ hp:-31, mind:-16, spirit:-17 } }
        ] },

      { t:'연구동 — 관찰 복도',
        x:`계단으로 가는 복도 한쪽이 통유리다. 유리 너머는 관찰실이다. 불이 꺼져 있다.<br><br>
          걷는데 유리 너머 어둠에서 무언가 같이 걷는다. 이쪽 걸음에 맞춰서. 멈추면 멈춘다.<br>
          펴진 3형이다. 천장에 닿을 만큼 크다. 얼굴판이 이쪽을 향해 있다. 솔기가 조금 벌어졌다.<br><br>
          유리 끝에 관찰실 문이 있다. 복도와 이어진 문이다. 그 문 앞을 지나야 계단이다.`,
        o:[
          { l:'① 몸을 낮추고 관찰실 문 앞을 재빨리 지난다.', k:'hide', dc:24,
            doom:{ title:'유리 너머', what:'관찰실 안으로 끌려 들어갑니다', dc:19, sec:46,
              text:`허리를 숙이고 유리 밑으로 걸었다. 유리 너머의 것도 허리를 숙인다. 같은 높이로.<br><br>문 앞에 왔다. 뛰었다. 유리 너머의 것은 뛰지 않았다. 이미 문에 와 있었다.<br>문이 안에서 열린다. 손잡이를 쓸 줄 안다. 긴 팔이 나와 허리를 감는다.<br><br>몸이 관찰실 안으로 끌려 들어간다. 문이 닫힌다. 유리 이쪽에서 일행이 두드린다. 안에서는 그 소리가 아주 작다.`,
              dieText:`관찰실 유리는 안에서 밖을 보도록 만든 것이다.<br><br>복도에서는 안이 안 보인다. 아무것도.<br>유리 너머에서 무언가 다시 일행 걸음에 맞춰 걷기 시작했다.` },
            ok:`허리를 숙이고 걷다가 문 앞 세 걸음 전에 멈췄다. 유리 너머의 것도 멈춘다.<br><br>그대로 뒤로 다섯 걸음 물러났다. 그것도 물러났다. 문에서 멀어졌다.<br>그 순간 앞으로 뛰었다. 그것이 따라 뛴다. 다섯 걸음만큼 늦다. 문 앞을 지날 때 문이 안에서 열렸다. 등 뒤로 바람만 지나갔다.<br><br>흉내 내는 것은 늦는다. 아주 조금.`,
            win:{ exp:20, dream:3 } },
          { l:'② 걸음을 일부러 흩뜨려 박자를 깬다.', k:'evade', dc:24,
            ok:`느리게, 빠르게, 멈췄다, 두 번 빠르게. 아무 박자 없이 걸었다.<br><br>유리 너머의 것이 따라오다 멈춘다. 솔기가 벌어진다. 듣는 것이다. 박자를 찾는다.<br>찾는 동안 문 앞을 지났다. 문 손잡이가 늦게 내려왔다. 이미 지났다.<br><br>계단 문을 닫으며 돌아봤다. 유리에 판이 붙어 있다. 솔기가 이쪽을 향해 벌어져 있다. 다음에는 박자 없는 박자도 배울 것이다.`,
            ng:`흩뜨린 박자에도 박자가 있었다. 사람은 아무렇게나 걷지 못한다.<br><br>문 앞에서 문이 열렸다. 정확히. 팔이 나와 어깨를 친다. 마디 끝이 쇠처럼 단단하다.<br>복도 벽에 부딪혀 굴렀다. 일행이 끌고 계단으로 들어갔다. 어깨가 빠졌다. 맞춰 넣는 동안 문 너머에서 철컥, 철컥.`,
            win:{ exp:19, dream:3 },
            lose:{ hp:-34, spirit:-18 } }
        ] }
    ] },

    // ───────── 4층 ─────────
    { name:'4층 — 숙소동', scenes:[

      { t:'숙소동 — 식당',
        x:`숙소동 식당은 넓다. 의자가 다 밀려 나 있다. 다들 한꺼번에 일어난 자리다.<br><br>
          식판이 그대로다. 국은 말라붙었고 수저는 바닥에 떨어졌다. 석 달 전 저녁이다.<br>
          주방 안쪽에 대형 냉동고가 있다. 문이 한 뼘 열려 있다. 안에서 찬 김이 바닥을 기어 나온다.<br><br>
          찬 데는 안전하다. 그 말을 그것들도 안다면 이야기가 다르다.`,
        o:[
          { l:'① 찬장을 뒤져 밀봉 식량을 찾는다.', k:'luck', dc:24,
            ok:`찬장 문을 하나씩 열었다. 대부분 비었다. 일꾼들이 봉지째 가져갔다. 사람이 흘린 것은 무엇이든.<br><br>맨 위 칸 안쪽, 손이 겨우 닿는 데에 깡통 상자가 하나 밀려 있다. 비상식량. 말린 고기와 건빵.<br>일꾼들 키로는 안 닿는 높이다. 아니면 깡통은 줍지 않는다.<br><br>상자 뚜껑에 조리장 글씨. 마지막에 나가는 사람 몫.`,
            ng:`찬장 맨 아래 칸을 열자 안이 하얗다. 막으로 꽉 찼다.<br><br>막 속에서 일꾼 셋이 잠에서 깬다. 문을 닫으려는데 하나가 문틈에 다리를 끼웠다. 손등을 문다.<br>발로 문을 차서 닫았다. 다리 하나가 문틈에 남아 꿈틀거렸다. 손등이 퉁퉁 부었다.`,
            win:{ exp:18, dream:3, item:'말린 고기' },
            lose:{ hp:-31, spirit:-18 } },
          { l:'② 한 뼘 열린 냉동고 안을 살핀다.', k:'sense', dc:25,
            doom:{ title:'주방 냉동고', what:'냉동고 안으로 끌려 들어갑니다', dc:19, sec:48,
              text:`냉동고 문을 조금 더 열었다. 찬 김이 무릎까지 차오른다. 안이 어둡다.<br><br>고기 갈고리 밑에 실험동물 상자들이 쌓여 있다. 차곡차곡. 사람 솜씨가 아니다. 너무 가지런하다.<br>찬 데에 먹을 것을 둔다. 그것도 그걸 안다. 저장하는 것이다.<br><br>문 안쪽 위에서 마디가 펴진다. 추워서 느리다. 느린데 손목을 잡는 힘은 느리지 않다. 몸이 냉동고 안으로 끌려 들어간다. 문이 닫힌다.`,
              dieText:`추우면 느리다. 느려도 문은 닫는다.<br><br>냉동고 문틈으로 찬 김이 한참 새어 나왔다. 그러다 멎었다. 문이 꼭 닫혔다.<br>안에서 상자를 다시 쌓는 소리가 났다. 가지런하게.` },
            ok:`문을 더 열지 않았다. 거울 조각을 문틈에 대고 안을 비춰 봤다.<br><br>상자들이 너무 가지런하게 쌓여 있다. 그리고 문 바로 위 천장에 접힌 것 하나. 추워서 움직이지 않는다.<br>문 앞 바닥에 떨어진 고기 상자 하나만 발로 끌어냈다. 얼어서 돌처럼 단단하다. 실험동물 먹이로 들인 고기다. 포장째 멀쩡하다.<br><br>문을 닫고 손잡이에 국자를 꽂았다. 안에서 문을 한 번 밀었다. 느리게.`,
            win:{ exp:20, dream:3, item:'짐승 고기' } },
          { l:'③ 조리대 양념장을 뒤진다.', k:'heal', dc:24, only:'heal',
            ok:`치유하는 손은 주방을 안다. 다친 사람에게 먼저 필요한 것. 따뜻한 물, 소금, 깨끗한 천.<br><br>양념장 맨 안쪽에 굵은 소금 단지가 있다. 습기를 먹어 덩이졌다. 상처 씻을 소금물로도 쓰고 먹을 것에도 쓴다.<br>깨끗한 행주 몇 장도 같이 챙겼다. 석 달 전에 삶아 개켜 둔 그대로다.<br><br>개켜 둔 사람은 마지막 저녁 설거지까지 했다.`,
            ng:`양념장 단지들을 하나씩 열다 하나에서 손을 뺐다. 단지 안에 꿀처럼 걸쭉한 것이 있다. 꿀이 아니다. 따뜻하다.<br><br>손끝이 하얗게 탔다. 맑은 것이 반쯤 굳어 있었다. 누가 담아 둔 것이다. 일부러.<br>손을 찬물에 담그고 한참 이를 악물었다.`,
            win:{ exp:18, dream:3, item:'소금 덩이' },
            lose:{ hp:-30, mind:-17 } }
        ] },

      { t:'숙소동 — 2인실 침상',
        x:`복도 양쪽으로 2인실이 이어진다. 문이 다 열려 있다.<br><br>
          세 번째 방 아래 침상에 누가 누워 있다. 이불을 머리끝까지 덮었다. 이불이 오르내린다. 숨을 쉰다.<br>
          네 번째 방에도. 다섯 번째 방에도. 숨이 다 같은 박자다.<br><br>
          복도 끝에서 똑, 똑, 똑. 소리가 가까워진다. 숨을 곳이 필요하다.`,
        o:[
          { l:'① 빈 위층 침상에 올라가 이불을 덮고 숨는다.', k:'hide', dc:25,
            doom:{ title:'아래 침상의 손', what:'아래 침상으로 끌려 내려갑니다', dc:19, sec:47,
              text:`빈 위층 침상에 올라가 이불을 덮었다. 숨을 죽였다. 아래 침상의 숨소리가 들린다. 고르다.<br><br>복도 두드림이 방 앞에서 멎었다. 아래 침상의 숨도 같이 멎는다.<br>아래에서 손이 올라온다. 침상 난간 사이로. 따뜻한 손이다. 이불 속 발목을 잡는다. 꼭.<br><br>잡은 채 놓지 않는다. 그 사람 뜻이 아니다. 목덜미의 것이 시킨 일이다. 당긴다. 아래 침상으로 끌려 내려간다. 문 쪽에서 마디 펴지는 소리가 난다.`,
              dieText:`숙주는 따뜻한 것을 붙잡는다. 오는 것이 올 때까지.<br><br>2인실 아래 침상은 다음 날 아침 비어 있었다. 위 침상도.<br>이불만 개켜져 있었다. 너무 가지런하게.` },
            ok:`빈 위층 침상에 올라가 이불을 덮되 발을 침상 안쪽 벽에 붙였다. 난간 쪽으로는 아무것도 내놓지 않았다.<br><br>두드림이 방 앞에서 멎었다. 아래 침상에서 손이 올라와 난간 사이를 더듬는다. 아무것도 안 잡힌다.<br>문 앞의 것이 한참 서 있다가 지나갔다. 아래 손이 내려갔다.<br><br>침상에서 내려올 때 아래 사람 얼굴을 봤다. 자고 있다. 웃는 얼굴이다. 다시는 아래를 안 봤다.`,
            win:{ exp:20, dream:3 } },
          { l:'② 자는 이들의 숨을 세어 본다.', k:'gaze', dc:24,
            ok:`문틈에 서서 이불이 오르내리는 걸 셌다. 들이쉬고, 내쉬고.<br><br>방마다 같은 박자다. 복도 두드림과 같은 박자. 두드림이 멎으면 숨도 멎는다. 같이 듣는 것이다.<br>그렇다면 숨을 쉬는 동안은 안 듣는다. 내쉴 때마다 한 걸음씩 갔다.<br><br>복도 끝에서 돌아봤다. 이불들이 일제히 들숨을 쉬었다. 그 사이 복도 끝이 조용했다.`,
            ng:`세는데 숨이 멎는다. 방마다 한꺼번에. 두드림도 멎었다.<br><br>이불 속에서 고개들이 돈다. 이쪽 쪽으로. 이불을 쓴 채로.<br>뛰었다. 복도 끝까지. 다리가 꼬여 문틀에 무릎을 찧었다. 등 뒤에서 다시 숨소리가 났다. 같은 박자로.`,
            win:{ exp:19, dream:3 },
            lose:{ mind:-18, spirit:-20 } },
          { l:'③ 내공으로 방 안의 온기를 거둬 숙주들을 깊이 재운다.', k:'steady', dc:24, cost:{ qi:29 },
            ok:`문턱에서 기를 방 안으로 밀어 넣었다. 따뜻한 것을 걷어 오듯이. 방이 서늘해진다.<br><br>이불 속 숨이 느려진다. 길어진다. 복도 두드림과 박자가 어긋난다.<br>숙주들이 박자를 놓치자 두드림이 망설인다. 멎었다가, 다시 시작했다가, 다른 쪽으로 간다.<br><br>그사이 지났다. 손끝이 얼음장이다. 거둬 온 온기는 이쪽에도 남지 않았다.`,
            ng:`기를 밀어 넣는데 숙주들이 깬다. 서늘해지는 걸 몸이 먼저 안다.<br><br>이불이 하나씩 젖혀진다. 다들 앉는다. 다들 문 쪽을 본다. 아무도 일어서지는 않는다.<br>그 눈길 밑을 지나갔다. 기가 바닥나 다리가 휘청였다. 복도 끝까지 아무도 말을 안 했다.`,
            win:{ exp:20, dream:3 },
            lose:{ hp:-30, mind:-18, spirit:-19 } }
        ] },

      { t:'숙소동 — 의무실',
        x:`의무실 들것 위에 사람이 묶여 있다. 손목과 발목을 끈으로. 스스로 묶은 것 같다. 매듭이 손 닿는 데 있다.<br><br>
          잠들어 있다. 숨이 고르다. 목덜미 혹이 주먹만 하다. 혹이 숨과 다른 박자로 오르내린다.<br>
          들것 옆 쟁반에 메스와 집게가 가지런하다. 혼자서 꺼내려다 그만둔 모양이다.<br><br>
          약장 유리문은 성하다. 안에 약초 꾸러미가 보인다.`,
        o:[
          { l:'① 메스로 혹을 갈라 실을 꺼낸다.', k:'heal', dc:25,
            doom:{ title:'꺼내는 손', what:'실이 손목으로 옮겨 탔습니다', dc:19, sec:46,
              text:`혹 가장자리에 메스를 댔다. 살갗을 가르자 혹이 움츠린다. 안에서 하얀 것이 몸을 접는다.<br><br>집게로 잡았다. 당긴다. 길다. 팔 하나 길이. 아직 끝이 안 나온다.<br>당기는 사이 끝이 살갗 밖으로 빠져나왔다. 집게를 타고 올라온다. 장갑 손목 틈으로. 이쪽이 더 따뜻하다.<br><br>손목 안쪽이 서늘하다. 그다음 따뜻하다. 줄이 팔꿈치 쪽으로 그어진다.`,
              dieText:`실은 꺼내는 손으로 옮겨 탄다. 그게 제일 가까우니까.<br><br>들것 위의 사람은 그날 처음으로 숨을 제 박자로 쉬었다.<br>꺼내 준 손은 그날 밤부터 복도 두드림에 맞춰 숨을 쉬었다.` },
            ok:`혹 가장자리에 메스를 대기 전에 장갑 손목을 테이프로 감았다. 두 겹.<br><br>살갗을 가르자 하얀 것이 몸을 접는다. 집게로 잡아 한 번에 당겼다. 길다. 팔 하나 길이. 다 나왔다.<br>알코올 병에 넣고 뚜껑을 닫았다. 병 안에서 한참 몸을 말았다 폈다.<br><br>들것 위의 사람 숨이 바뀐다. 제 박자로. 다만 등 쪽에도 불룩한 데가 하나 더 있었다. 메스를 내려놓았다. 거기까지는 못 한다.`,
            win:{ exp:21, dream:4 } },
          { l:'② 약장 경첩을 풀어 약초 꾸러미를 챙긴다.', k:'fix', dc:24,
            ok:`약장 경첩 나사를 칼끝으로 풀었다. 유리를 깨면 소리가 난다. 풀면 안 난다.<br><br>안에 말린 약초 꾸러미가 있다. 지혈, 소염. 습포용으로 묶어 놓았다. 붕대와 소독약도 반 상자.<br>들것의 사람 손목 끈은 풀지 않았다. 매듭이 그 사람 손 닿는 데 있었다. 그 사람이 정한 것이다.<br><br>약장 문을 다시 달고 나왔다.`,
            ng:`경첩 나사가 녹슬었다. 힘을 주다 칼이 미끄러져 유리를 쳤다. 금이 가는 소리.<br><br>들것 위의 사람이 눈을 뜬다. 혹이 먼저 깼다. 끈이 팽팽해진다. 들것이 덜컹거린다.<br>약장을 포기하고 물러섰다. 칼끝에 손바닥이 베였다. 피 냄새가 났다. 들것이 더 세게 덜컹거렸다.`,
            win:{ exp:19, dream:3, item:'약초 뭉치' },
            lose:{ hp:-32, spirit:-19 } },
          { l:'③ 묶인 사람의 손을 잡는다.', k:'bond', dc:24, only:'bond',
            ok:`들것 옆에 앉아 묶인 손을 잡았다. 뜨겁다.<br><br>눈이 뜨인다. 혹이 아니라 사람이 먼저 깼다. 손가락이 이쪽 손바닥을 두드린다. 똑, 똑, 똑. 그리고 손가락을 펴서 천장 환기구를 가리킨다. 고개를 젓는다.<br>손가락이 다시 움직인다. 바닥. 세탁실 쪽. 그리고 또 고개를 젓는다. 그쪽도 아니라는 뜻이다.<br><br>그 사람이 손을 놓았다. 먼저. 혹이 깨기 전에. 자기 손을 끈 쪽으로 도로 넣었다.`,
            ng:`손을 잡자 그 손이 이쪽을 꽉 쥔다. 놓지 않는다. 뜨겁다.<br><br>눈은 감겨 있다. 쥐는 것은 그 사람이 아니다. 목덜미의 것이다.<br>손가락을 하나씩 떼어 냈다. 손등에 손톱자국이 넷 남았다. 들것 위의 사람 얼굴이 젖어 있었다.`,
            win:{ exp:20, dream:3, spirit:8 },
            lose:{ mind:-18, spirit:-21 } }
        ] },

      { t:'숙소동 — 공용 샤워실',
        x:`계단으로 가려면 공용 샤워실을 지나야 한다. 김이 자욱하다. 물이 아직 나온다. 뜨거운 물이.<br><br>
          김 때문에 한 걸음 앞이 안 보인다. 타일 바닥이 미끄럽다. 배수구에서 물 내려가는 소리가 난다. 꿀렁, 꿀렁.<br>
          물 내려가는 소리가 가끔 멈춘다. 멈췄다가 크게 한 번 꿀렁 한다. 무언가 들어갔다 나온 소리다.<br><br>
          샤워실 반대편 문이 김 너머 어딘가에 있다.`,
        o:[
          { l:'① 벽을 짚으며 김 속을 그대로 지난다.', k:'steady', dc:25,
            doom:{ title:'김 속의 배수구', what:'배수구 쪽으로 끌려 내려갑니다', dc:19, sec:46,
              text:`벽 타일을 짚고 걸었다. 김이 얼굴을 덮는다. 숨을 쉴 때마다 뜨겁다.<br><br>배수구 소리가 멎었다. 발밑에서. 바로 발밑이다. 바닥 배수구가 생각보다 크다. 쇠창살 사이가 발 하나 너비다.<br>창살 사이로 무언가 올라와 발목을 잡는다. 마디가 많다. 창살 밑 어둠 속에서 펴진다. 길다.<br><br>당긴다. 발이 창살 사이로 들어간다. 무릎이 창살에 걸린다. 창살이 휜다. 배수구 쪽으로 끌려 내려간다.`,
              dieText:`꿀렁, 꿀렁. 배수구가 다시 물을 넘긴다.<br><br>샤워실 물은 다음 날에도 뜨거웠다. 김이 자욱했다.<br>배수구 창살 하나가 휘어 있었다. 사람 다리 너비로.` },
            ok:`벽을 짚고 걸었다. 배수구 소리가 멎는 걸 들었다. 멈춰 섰다.<br><br>꿀렁. 바로 앞이다. 김 사이로 바닥 배수구가 보인다. 크다. 창살 사이에서 마디 끝이 올라와 더듬는다. 방금 발을 디디려던 자리를.<br>한 걸음 옆 타일로 비켜 디뎠다. 마디가 한참 더듬다가 내려갔다. 꿀렁.<br><br>반대편 문에 닿았다. 문을 닫자 문 너머에서 다시 꿀렁, 꿀렁. 박자가 좀 빨랐다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 찬물 꼭지를 하나씩 돌려 김을 걷는다.', k:'sense', dc:24,
            ok:`가까운 꼭지부터 찬물로 돌렸다. 하나, 둘, 다섯. 김이 걷힌다.<br><br>바닥이 보인다. 배수구가 줄지어 있다. 사람 허리만 한 것이 넷. 창살마다 마디 끝이 걸쳐 있다. 김이 걷히자 천천히 창살 밑으로 들어간다. 찬물이 싫은 것이다.<br>배수구 사이 타일 줄만 디뎌 건넜다. 발이 시리다.<br><br>반대편 문에서 돌아보니 김이 다시 차오른다. 뜨거운 물 밸브가 저절로 돌아간다. 누가 돌린다.`,
            ng:`세 번째 꼭지를 돌렸는데 뜨거운 물이 쏟아진다. 표시가 반대로 붙어 있었다. 아니면 누가 바꿔 달았다.<br><br>팔과 어깨를 데었다. 김이 더 짙어진다. 뒤로 물러서다 배수구 창살을 밟았다. 창살 밑에서 무언가 움찔한다.<br>뛰었다. 반대편 문에 닿았을 때 팔 살갗이 벌겋게 부풀어 있었다.`,
            win:{ exp:19, dream:3, mind:7 },
            lose:{ hp:-33, mind:-17 } }
        ] },

      { t:'숙소동 — 세탁실',
        x:`세탁실 건조기가 돌아간다. 한 대만. 덜컹, 덜컹. 안에서 무거운 것이 구른다.<br><br>
          나머지 건조기 문은 다 열려 있다. 빨래가 없다. 침대 시트도 수건도. 일꾼들이 막 재료로 다 가져갔다.<br>
          돌아가는 건조기 유리문이 뿌옇다. 안이 따뜻할 것이다. 아주.<br><br>
          벽에 세탁물 투입구가 있다. 아래층 수거실로 떨어지는 구멍이다. 사람 하나 들어갈 만하다.`,
        o:[
          { l:'① 세탁물 투입구로 미끄러져 내려간다.', k:'evade', dc:25,
            doom:{ title:'세탁물 투입구', what:'투입구 아래로 끌려 내려갑니다', dc:19, sec:46,
              text:`투입구 뚜껑을 열고 발부터 넣었다. 미끄럽다. 빠르다.<br><br>통로가 중간에 꺾인다. 꺾인 데서 멈췄다. 아래가 막으로 막혀 있다. 그물처럼.<br>그물 아래에서 마디가 올라온다. 기다리던 것이다. 투입구로 떨어지는 것은 다 여기 걸린다. 빨래도, 사람도.<br><br>발목을 잡혔다. 막이 찢어지며 몸이 아래로 끌려 내려간다. 위에서 일행 손이 닿을 듯 말 듯하다.`,
              dieText:`세탁물 투입구는 아래층 수거실로 떨어진다.<br><br>수거실에 떨어진 것은 일꾼들이 나른다. 막으로 쓸 것과 다른 것을 나눠서.<br>투입구 뚜껑이 다시 닫혔다. 위에서 보면 그냥 뚜껑이다.` },
            ok:`투입구에 먼저 막 조각을 뭉쳐 던졌다. 한참 뒤에 아래에서 철컥 소리가 났다. 무언가 잡았다.<br><br>그 소리를 듣고 뚜껑을 닫았다. 아래에 기다리는 것이 있다. 투입구는 길이 아니다. 덫이다.<br>대신 건조기 뒤 점검 통로로 돌아갔다. 좁고 덥다. 하지만 아래에서 기다리는 것은 없었다.<br><br>통로 끝에서 돌아보니 투입구 뚜껑이 들썩였다. 안에서 무언가 올라오다가 말았다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 건조기가 멈출 때까지 숨어서 기다린다.', k:'steady', dc:24,
            ok:`세탁기 뒤에 붙어 기다렸다. 덜컹, 덜컹. 한참.<br><br>건조기가 멈췄다. 유리문이 안에서 밀려 열린다. 마디가 하나씩 나온다. 펴진다. 3형이다. 데워진 몸에서 김이 난다. 느리다. 졸린 것처럼.<br>그것이 세탁실을 한 바퀴 돌고 다른 문으로 나갔다. 열린 건조기 문을 하나씩 닫고 갔다. 정리하는 것처럼.<br><br>나갈 때 그 건조기 안을 봤다. 막이 둥글게 깔려 있다. 잠자리다.`,
            ng:`건조기가 멈췄다. 유리문이 열린다. 마디가 펴진다. 그것이 이쪽으로 온다. 졸리지 않았다.<br><br>세탁기 뒤에서 굴러 나와 뛰었다. 마디 끝이 등을 긁었다. 옷이 찢어지고 등에 줄이 셋.<br>문을 닫았다. 문 너머에서 건조기 문 닫는 소리가 차례로 들렸다.`,
            win:{ exp:20, dream:3 },
            lose:{ hp:-34, spirit:-20 } },
          { l:'③ 무력으로 세탁기를 밀어 건조기 문을 막는다.', k:'break', dc:24, cost:{ might:30 },
            ok:`세탁기 하나를 끌어안고 들었다. 무력을 끝까지. 건조기 앞까지 옮겨 문에 딱 붙였다.<br><br>건조기가 멈췄다. 안에서 문을 민다. 세탁기가 한 뼘 밀린다. 그 위에 하나를 더 얹었다.<br>안에서 두드린다. 똑, 똑, 똑. 대답하지 않았다.<br><br>세탁실을 지나는 동안 두드림이 점점 느려졌다. 덥다. 거기서 잠들기로 한 모양이다.`,
            ng:`세탁기를 드는데 바닥에 막으로 붙어 있었다. 무력을 더 썼다. 막이 뜯기며 세탁기가 기울었다.<br><br>모서리가 발등을 찍었다. 건조기 문이 열린다. 안에서 마디가 나온다.<br>세탁기를 그대로 밀어 문에 부딪쳤다. 마디가 끼었다. 그 틈에 뛰었다. 발이 부어 신발이 안 맞았다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-35, mind:-17 } }
        ] },

      { t:'숙소동 — 휴게실 호출반',
        x:`휴게실 벽에 호출반이 있다. 방 번호마다 작은 등이 있다. 방에서 버튼을 누르면 여기 등이 켜지고 딩동 소리가 난다.<br><br>
          딩동. 214호 등이 켜진다. 조금 뒤에 딩동. 216호. 그리고 218호.<br>
          한 칸씩 건너뛰며 이쪽으로 온다. 휴게실은 220호 옆이다.<br><br>
          누르는 쪽은 사람이 아니다. 사람이 오게 만드는 소리를 배운 것이다.`,
        o:[
          { l:'① 불이 켜진 방으로 가 누가 부르는지 본다.', k:'bond', dc:25,
            doom:{ title:'218호', what:'방 안으로 끌려 들어갑니다', dc:19, sec:45,
              text:`218호 문 앞에 섰다. 문이 반쯤 열려 있다. 벽의 호출 버튼에 불이 켜져 있다.<br><br>안에는 아무도 없다. 침상 둘. 이불 둘. 버튼 둘레 벽에 긁힌 자국이 있다. 높다. 천장 가까이.<br>사람이 누르는 높이가 아니다. 그걸 알았을 때 문 뒤에서 마디가 펴진다.<br><br>목을 감긴다. 몸이 방 안으로 끌려 들어간다. 휴게실 호출반에서 딩동. 218호. 다시 한 번.`,
              dieText:`호출반은 사람이 오게 만든다. 그렇게 만든 기계다.<br><br>그날 밤 휴게실 호출반은 한 번도 울리지 않았다.<br>다음 날 아침 딩동. 220호. 휴게실 옆방이다.` },
            ok:`문 앞까지 가지 않았다. 복도 모퉁이에서 손거울로 218호를 비췄다.<br><br>버튼 둘레 벽에 긁힌 자국이 있다. 높다. 사람이 누르는 높이가 아니다. 문 뒤 그늘에 마디가 접혀 있다.<br>거울을 거뒀다. 조용히 뒷걸음질 쳤다. 딩동. 218호. 한 번 더. 아무도 오지 않자 불이 꺼졌다.<br><br>220호 등이 켜졌다. 이쪽은 이미 계단 쪽이다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 호출반 스피커 선을 뽑아 소리를 죽인다.', k:'fix', dc:24,
            ok:`호출반 뒤판을 열었다. 선이 몇 가닥 없다. 스피커 선을 찾아 뽑았다.<br><br>딩동이 멎는다. 등은 계속 켜진다. 218, 220. 소리 없이 한 칸씩.<br>소리가 안 나니 오는 사람이 없다. 그것도 곧 알 것이다. 등이 220호에서 멈췄다. 한참.<br><br>휴게실을 나올 때 호출반 등이 전부 한꺼번에 켜졌다. 화가 난 것처럼. 소리는 없었다.`,
            ng:`선을 뽑는 순간 마지막 딩동이 길게 울린다. 뽑힌 선 끝에서 소리가 늘어진다. 딩—.<br><br>복도 끝 방마다 문이 열린다. 2인실의 숙주들이 문간에 선다. 다 이쪽을 본다.<br>휴게실 뒷문으로 뛰었다. 문틀에 걸려 넘어졌다. 손목을 접질렸다. 아무도 쫓아오지 않았다. 그게 더 나빴다.`,
            win:{ exp:19, dream:3 },
            lose:{ hp:-32, mind:-18, spirit:-19 } },
          { l:'③ 딩동 사이의 간격을 듣고 동선을 읽는다.', k:'sense', dc:24, only:'sense',
            ok:`눈을 감고 딩동 사이를 셌다. 열넷, 열여섯, 열넷.<br><br>방 하나를 건너뛸 때마다 걸음이 같다. 문을 열고, 누르고, 기다리고, 다음 방. 기다리는 동안이 열이다.<br>220호 다음은 휴게실이다. 휴게실 다음은 계단이다. 기다리는 열 동안 계단으로 빠지면 된다.<br><br>220호 등이 켜졌다. 하나를 세고 일어섰다. 계단 문을 닫을 때 휴게실에서 딩동, 이 울렸다. 아무도 없는 방에.`,
            ng:`세다가 박자가 어긋났다. 열넷 다음이 열넷이 아니라 둘이다. 건너뛰었다.<br><br>휴게실 문이 열린다. 220호가 아니다. 셈을 그것도 바꿨다. 사람이 세는 걸 안다.<br>책상을 엎고 그 뒤로 굴렀다. 마디 끝이 책상을 뚫고 어깨를 스쳤다. 피가 셔츠를 적신다.`,
            win:{ exp:20, dream:3, mind:8 },
            lose:{ hp:-33, spirit:-20 } }
        ] },

      { t:'숙소동 — 계단 방화문',
        x:`계단으로 나가는 방화문이 닫혀 있다. 이쪽에서 밀어서 여는 문이다.<br><br>
          문 너머 계단 쪽 손잡이가 움직인다. 천천히 내려갔다가 천천히 올라간다. 문은 안 열린다. 저쪽에서는 당겨야 열린다.<br>
          손잡이가 내려갔다 올라올 때마다 조금씩 더 오래 내려가 있다. 배우는 중이다.<br><br>
          다른 길은 없다. 이 문을 지나야 아래로 간다.`,
        o:[
          { l:'① 문에 등을 대고 버티며 기회를 본다.', k:'steady', dc:25,
            doom:{ title:'배우는 손잡이', what:'방화문 너머로 끌려갑니다', dc:19, sec:45,
              text:`문에 등을 붙이고 손잡이를 위에서 눌러 잡았다. 저쪽 손잡이가 내려갔다 올라간다. 문은 꿈쩍 안 한다. 그것은 아직 밀기만 한다.<br><br>다섯 번째에 손잡이가 내려간 채 멈췄다. 한참.<br>그리고 문이 당겨진다. 배웠다. 등을 대고 있던 문이 한꺼번에 저쪽으로 사라진다.<br><br>뒤로 넘어간다. 계단참으로. 마디가 넘어지는 몸을 받는다. 받아서 감는다. 방화문 너머로 끌려간다. 문이 다시 닫힌다.`,
              dieText:`밀어서 여는 문은 저쪽에서 당기면 열린다. 손잡이를 쓸 줄 알면.<br><br>방화문 손잡이는 한참 가만히 있었다. 그러다 다시 천천히 내려갔다.<br>이제 그것은 미는 법도 당기는 법도 안다.` },
            ok:`문에 등을 붙이고 저쪽 손잡이를 셌다. 내려갔다 올라간다. 문은 안 열린다.<br><br>다섯 번째에 손잡이가 내려간 채 멈췄다. 배우는 중이다. 등을 뗐다. 문 앞에서 비켜섰다.<br>문이 당겨져 열린다. 비켜선 자리 옆으로 마디가 허공을 감는다. 아무것도 없다. 그것이 판을 갸웃한다.<br><br>그 틈에 마디 밑으로 굴러 계단으로 빠졌다. 뒤에서 문이 닫혔다. 이제 그것은 당기는 법을 안다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 손잡이가 올라가는 순간 문을 박차고 나간다.', k:'evade', dc:24,
            ok:`손잡이가 올라가는 걸 보고 문을 어깨로 박찼다. 문이 저쪽으로 열리며 무언가를 친다.<br><br>계단참에 접이가 서 있다가 문에 맞아 반사적으로 접혔다. 마디가 차곡차곡.<br>그 옆을 뛰어 내려갔다. 일행이 줄줄이 따랐다. 마지막 사람이 지날 때 마디 하나가 펴져 난간을 쳤다. 난간이 휘었다.<br><br>아래층 문을 닫고 등을 댔다. 위에서 철컥, 철컥. 다 펴지는 소리. 내려오지는 않았다.`,
            ng:`문을 박찼는데 저쪽에서 먼저 당겼다. 문이 확 열리며 몸이 앞으로 쏠린다.<br><br>계단참에 펴진 것과 부딪쳤다. 단단하다. 마디 끝이 옆구리를 판다.<br>굴러서 아래 계단으로 떨어졌다. 일행이 뒤에서 문을 쳐 그것을 밀어냈다. 옆구리를 누른 손이 젖었다.`,
            win:{ exp:20, dream:3 },
            lose:{ hp:-36, spirit:-21 } }
        ] }
    ] },

    // ───────── 5층 ─────────
    { name:'5층 — 환기 설비층', scenes:[

      { t:'설비층 — 주 환풍기',
        x:`설비층은 시끄럽다. 주 환풍기가 돈다. 날개 하나가 사람 키만 하다.<br><br>
          환풍기 너머가 주 덕트다. 이 층을 지나는 길은 덕트뿐이다. 계단 쪽 문은 막으로 메워졌다.<br>
          날개 사이가 한 번 열릴 때 반 걸음쯤 틈이 난다.<br><br>
          환풍기는 공기를 빨아들인다. 날개 앞 철망에 무언가 잔뜩 붙어 있다. 하얀 막 조각, 머리카락, 명찰 하나.`,
        o:[
          { l:'① 날개 사이가 열리는 순간 뛰어든다.', k:'evade', dc:25,
            doom:{ title:'빨아들이는 바람', what:'환풍기 쪽으로 빨려 들어갑니다', dc:19, sec:45,
              text:`날개를 셌다. 하나, 둘, 셋. 틈이 열린다. 뛰었다.<br><br>철망 문을 지나는 순간 바람이 몸을 잡는다. 빨아들이는 바람이다. 생각보다 세다. 발이 바닥에서 미끄러진다.<br>몸이 날개 쪽으로 쏠린다. 반 걸음이 한 걸음이 된다. 다음 날개가 온다.<br><br>옷자락이 날개 축에 감긴다. 철망에 손가락을 걸었다. 손가락 끝이 하얗다. 바람이 계속 당긴다. 환풍기 쪽으로 빨려 들어간다.`,
              dieText:`주 환풍기는 공기를 빨아들인다. 공기에 섞인 것도.<br><br>날개 앞 철망에 붙은 것이 하나 늘었다. 명찰은 아니다. 신발 끈이다.<br>환풍기는 조금도 느려지지 않았다.` },
            ok:`날개를 열 번 세었다. 틈이 열릴 때마다 바람이 어느 쪽으로 쏠리는지 봤다. 날개 축 반대쪽이 바람이 약하다.<br><br>틈이 열리는 순간 낮게, 축 반대쪽으로 뛰었다. 바람이 등을 떠민다. 그 힘을 받아 덕트로 굴러 들어갔다.<br>일행 손목을 하나씩 잡아 끌어들였다. 날개가 등 뒤를 지날 때마다 머리카락이 날린다.<br><br>덕트 안은 고요하다. 환풍기 소리가 벽 너머 일이 됐다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 제어함을 찾아 환풍기를 끈다.', k:'fix', dc:24,
            ok:`벽을 따라 전선을 쫓아 제어함을 찾았다. 비상 정지 버튼을 눌렀다.<br><br>날개가 느려진다. 멈춘다. 설비층이 조용해진다. 처음으로.<br>조용해지자 들린다. 똑, 똑, 똑. 덕트마다. 위에서, 옆에서, 바닥 밑에서. 수십. 시끄러운 환풍기가 이걸 덮고 있었다.<br><br>두드림이 하나씩 멎는다. 듣는 것이다. 조용해진 까닭을. 서둘러 날개 사이를 지났다.`,
            ng:`정지 버튼을 눌렀다. 날개가 멈췄다가 다시 돈다. 재가동. 누가 다시 켰다. 이 층 어딘가에서.<br><br>날개 사이를 지나던 사람 어깨를 날개가 쳤다. 철망 쪽으로 튕겨 나갔다.<br>끌어당겨 겨우 덕트에 넣었다. 어깨뼈가 빠졌다 들어가는 소리가 났다.`,
            win:{ exp:20, dream:3 },
            lose:{ hp:-34, mind:-18 } },
          { l:'③ 무력으로 날개를 붙잡아 세운다.', k:'steady', dc:25, cost:{ might:31 },
            doom:{ title:'멈춘 날개', what:'날개에 휘말렸습니다', dc:19, sec:44,
              text:`날개가 지나가는 순간 붙잡았다. 무력을 팔과 허리에 다 실었다.<br><br>날개가 멈춘다. 한 박자. 두 박자. 일행이 틈으로 들어간다.<br>세 박자째에 모터가 운다. 멈춘 만큼 힘이 쌓인다. 쌓인 것이 한꺼번에 돈다.<br><br>손을 놓으려는데 장갑이 날개 가장자리에 걸렸다. 몸이 날개를 따라 들린다. 철망이 얼굴 앞으로 온다.`,
              dieText:`무력은 쓰면 준다. 모터는 멈추면 쌓인다.<br><br>일행은 덕트 안에서 날개 소리가 한 번 둔해지는 것을 들었다.<br>그다음부터는 늘 같은 소리였다.` },
            ok:`날개를 붙잡았다. 무력을 팔과 허리에 다 실었다. 날개가 멈춘다.<br><br>한 박자, 두 박자. 일행이 틈으로 들어간다. 세 박자째에 모터가 운다. 손을 놓고 몸을 날개 축 반대쪽으로 던졌다.<br>날개가 쌓인 힘으로 한꺼번에 돈다. 등 뒤로 바람이 지나갔다.<br><br>덕트 안에서 손바닥을 펴 봤다. 장갑이 날개 모양으로 패어 있다.`,
            win:{ exp:22, dream:3 } }
        ] },

      { t:'설비층 — 주 덕트',
        x:`덕트 안은 네모나다. 엎드려 기어야 한다. 손바닥 밑 쇠가 따뜻하다. 앞쪽이 더 따뜻하다.<br><br>
          한 줄로 기었다. 쇳소리가 덕트 전체로 울린다. 울림이 앞에서 돌아오고 뒤에서도 돌아온다.<br>
          뒤에서 돌아오는 울림이 조금 늦다. 그리고 조금 무겁다.<br><br>
          맨 뒷사람이 낮게 말한다. 뒤에 하나 더 있다.`,
        o:[
          { l:'① 멈추지 않고 앞으로 계속 기어간다.', k:'steady', dc:25,
            doom:{ title:'뒤에서 오는 울림', what:'덕트 뒤로 끌려갑니다', dc:19, sec:44,
              text:`멈추지 않았다. 멈추면 뒤에 있는 것도 멈출 것이다. 그러면 거리를 모른다.<br><br>맨 뒤는 이쪽이다. 뒤에서 오는 울림이 점점 가까워진다. 덕트가 좁아서 돌아볼 수 없다.<br>발목에 무언가 닿는다. 한 번 톡. 확인하는 것이다. 그리고 감긴다. 두 번.<br><br>당긴다. 엎드린 몸이 쇠 바닥을 미끄러져 뒤로 간다. 손톱이 바닥을 긁는다. 덕트 뒤로 끌려간다. 앞사람 발이 멀어진다.`,
              dieText:`덕트는 앞과 뒤밖에 없다. 뒤로 간 것은 돌아오지 않는다.<br><br>쇠 바닥에 손톱자국이 열 줄. 길게.<br>앞서 간 일행이 덕트 끝에 닿았을 때 뒤에서 오던 울림은 멎어 있었다.` },
            ok:`멈추지 않았다. 대신 빨라졌다. 앞사람 발뒤꿈치를 밀며.<br><br>뒤의 울림도 빨라진다. 덕트가 꺾이는 데에서 맨 앞이 옆 갈래로 몸을 틀었다. 다들 따라 틀었다.<br>뒤의 것은 꺾인 데를 지나쳤다. 무거워서 꺾이는 데서 느리다. 울림이 곧장 가서 멀어진다.<br><br>옆 갈래 끝에서 다들 숨을 몰아쉬었다. 무릎과 손바닥이 쇠에 쓸려 벌겋다.`,
            win:{ exp:21, dream:3 } },
          { l:'② 허리를 줄로 엮고 다 같이 버틴다.', k:'bond', dc:25,
            doom:{ title:'풀리는 매듭', what:'줄이 풀려 뒤로 끌려갑니다', dc:19, sec:44,
              text:`허리에 줄을 감아 한 줄로 이었다. 이쪽이 맨 뒤다.<br><br>뒤의 것이 발목을 잡는다. 당긴다. 줄이 팽팽해진다. 앞에서 다들 버틴다.<br>그것이 한 번 놓았다가 다시 잡는다. 이번엔 무릎을. 더 세게. 줄이 끊어지는 소리는 안 난다. 매듭이 풀리는 소리가 난다.<br><br>허리가 줄에서 빠진다. 몸만 쇠 바닥을 미끄러져 뒤로 끌려간다. 줄 끝을 쥔 손이 펴진다.`,
              dieText:`좋은 매듭은 오래 걸려 풀린다.<br><br>그 매듭은 금방 풀렸다. 감기는 쪽이 너무 셌다.<br>앞사람 손에 남은 줄 끝이 한참 따뜻했다.` },
            ok:`허리에 줄을 감아 한 줄로 이었다. 뒤의 것이 맨 뒷사람 발목을 잡았다. 당긴다.<br><br>줄이 팽팽해진다. 앞에서 다 같이 덕트 이음매에 손을 걸고 버텼다. 하나가 끌려가면 다 끌려간다. 그것도 셈을 한다.<br>오래 당기다가 그것이 놓았다. 무게를 재 보고 손해라고 본 것이다.<br><br>줄을 풀지 않고 그대로 기었다. 다음 갈림길까지. 매듭이 단단해서 다행이었다.`,
            win:{ exp:21, dream:3, spirit:8 } },
          { l:'③ 몸을 뒤집어 반듯이 누운 채 옆 갈래로 빠진다.', k:'evade', dc:24, only:'evade',
            ok:`좁은 데서는 엎드린 몸이 제일 느리다. 반듯이 누워 등으로 밀고, 발로 밀었다. 천장 이음매를 손으로 잡아당기며.<br><br>옆 갈래 입구에서 몸을 접어 넣었다. 뒤에서 오던 것이 그 앞을 지나간다. 마디 하나가 입구를 더듬는다. 입구는 그것이 접어도 들어오기엔 좁다.<br>일행을 하나씩 같은 식으로 끌어들였다.<br><br>마디가 한참 입구에 걸쳐 있다가 거둬졌다. 철컥. 다른 길을 찾으러 간다. 다른 길이 있다는 뜻이다.`,
            ng:`몸을 뒤집다가 어깨가 덕트 벽에 걸렸다. 쇳소리가 덕트 전체로 울린다.<br><br>뒤의 것이 빨라진다. 옆 갈래 입구로 몸을 밀어 넣는데 마디 끝이 정강이를 찍었다.<br>빼냈다. 정강이에 구멍이 났다. 덕트 바닥에 피가 길게 묻었다. 그 냄새가 한참 따라올 것이다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-35, spirit:-21 } }
        ] },

      { t:'설비층 — 필터실',
        x:`덕트가 필터실로 이어진다. 커다란 필터가 벽처럼 서 있다. 원래는 회색이다. 지금은 하얗다.<br><br>
          필터마다 막이 겹겹이 덮였다. 일꾼들이 막을 펴서 말리는 자리다. 빨래 널듯이.<br>
          필터실 구석은 축축하다. 벽 아래에 버섯이 무더기로 피었다. 재배실에서 날아온 포자가 여기서 자랐다.<br><br>
          필터 뒤에서 바스락 소리가 난다. 막 펴는 소리다.`,
        o:[
          { l:'① 막의 결을 보고 지날 길을 고른다.', k:'gaze', dc:24,
            ok:`막에도 결이 있다. 새로 건 것은 희고 말랑하고, 오래된 것은 누렇고 바삭하다.<br><br>새 막은 일꾼이 자주 오가는 자리다. 오래된 막은 아무도 손대지 않는 자리다.<br>누런 막 사이로만 걸었다. 바스락 소리가 나도 거기는 아무도 안 온다.<br><br>필터실 끝에서 돌아보니 흰 막 쪽에서 일꾼들이 고개를 들고 있다. 소리가 난 쪽을 본다. 이미 다 지났다.`,
            ng:`흰 막과 누런 막을 반대로 읽었다. 새 막 사이로 들어갔다.<br><br>막 뒤에서 일꾼 떼가 쏟아져 나온다. 막을 펴던 참이었다. 펴던 막째로 덮쳤다.<br>막을 찢고 빠져나왔다. 얼굴과 팔에 막이 엉겨 붙어 떨어지지 않는다. 떼어 낸 자리마다 살갗이 따라 일어났다.`,
            win:{ exp:20, dream:3 },
            lose:{ hp:-33, mind:-18, spirit:-20 } },
          { l:'② 축축한 구석의 버섯 무더기를 딴다.', k:'luck', dc:25,
            doom:{ title:'따뜻한 무더기', what:'필터 뒤로 끌려 들어갑니다', dc:19, sec:44,
              text:`구석에 쭈그려 앉아 버섯을 땄다. 통통하다. 재배실 것보다 크다.<br><br>무더기 밑이 따뜻하다. 버섯이 왜 여기서 잘 자라는지 알 것 같다. 밑에 무언가 있다. 숨 쉬는 것이.<br>필터 틀 뒤에서 다리 많은 것들이 줄지어 나온다. 버섯 따는 손을 문다. 무는 데가 하나둘이 아니다.<br><br>필터 틀 사이 좁은 틈으로 팔이 끌려 들어간다. 어깨가 틀에 걸린다. 틀 뒤에서 더 많은 다리가 기다린다.`,
              dieText:`버섯은 따뜻하고 축축한 데서 잘 자란다.<br><br>필터실 구석 버섯 무더기는 다음 날 조금 더 컸다.<br>필터 틀 하나가 한 뼘 벌어진 채 그대로 있었다.` },
            ok:`무더기 밑이 따뜻한 걸 손등으로 먼저 알았다. 밑은 건드리지 않고 위쪽 갓만 칼로 잘랐다.<br><br>자르는 동안 필터 틀 뒤에서 바스락 소리가 다가왔다가 멈췄다. 이쪽 손이 무더기 밑을 건드리지 않자 멈췄다.<br>한 줌 가득 잘라 물러섰다. 단단하고 냄새가 좋다. 여기서 좋은 냄새는 드물다.<br><br>무더기 밑에서 무언가 다시 잠드는 소리가 났다.`,
            win:{ exp:21, dream:3, item:'야생 버섯' } },
          { l:'③ 내공으로 숨을 죽이고 막 사이를 지난다.', k:'hide', dc:24, cost:{ qi:31 },
            ok:`숨을 단전 아래로 내리고 거의 쉬지 않았다. 몸의 소리가 줄어든다. 심장도 느려진다.<br><br>막 사이를 지날 때 일꾼들이 바로 옆에서 막을 편다. 다리 열둘이 바쁘다. 이쪽은 막 한 장 너머에 서 있다.<br>일꾼 하나가 이쪽 소매를 더듬었다. 떨어진 것인지 확인하듯. 가만히 있었다. 그것이 다시 막을 폈다.<br><br>필터실을 다 지나고 숨을 터뜨렸다. 머리가 핑 돈다. 핑 도는 것은 괜찮다.`,
            ng:`숨을 내렸는데 막 냄새가 코를 찌른다. 기침이 올라온다. 내공으로 눌렀다. 눌린 기침이 가슴에서 터졌다.<br><br>일꾼들이 한꺼번에 돌아본다. 막을 내려놓고 온다.<br>뛰었다. 막에 발이 걸려 넘어졌다. 손바닥과 무릎을 물렸다. 기가 흩어져 한동안 숨이 제멋대로였다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-33, mind:-18, spirit:-21 } }
        ] },

      { t:'설비층 — 응축수 받이',
        x:`냉각 코일 밑에 응축수 받이가 있다. 넓은 쇠쟁반이다. 물이 찰랑찰랑 고였다.<br><br>
          코일에서 떨어지는 물방울은 맑다. 차다. 이 층에서 처음 보는 찬 것이다.<br>
          다들 목이 탄다. 마지막으로 물을 마신 게 언제인지 아무도 모른다.<br><br>
          쟁반 가장자리 쇠가 군데군데 얇다. 위에서 무언가 떨어진 자국이다. 물방울 말고.`,
        o:[
          { l:'① 물방울을 손으로 받아 천에 거른다.', k:'heal', dc:24,
            ok:`코일 바로 밑에 천을 대고 떨어지는 물방울을 받았다. 받이에 고인 물은 안 썼다.<br><br>물방울은 차고 맑다. 천에 걸러 수통에 담았다. 다 차는 데 오래 걸렸다. 오래 걸리는 물이 좋은 물이다.<br>일행에게 한 모금씩 돌렸다. 다친 사람 먼저. 입술이 터진 사람은 천에 적셔 입술에 대 주었다.<br><br>마지막에 마셨다. 남은 게 별로 없었다. 그래도 차다.`,
            ng:`물방울을 받는데 그중 하나가 손등에 떨어져 연기를 낸다. 물이 아니다.<br><br>코일 위에서 맑은 것이 물방울에 섞여 떨어지고 있었다. 찬물 냄새가 식초 냄새를 가렸다.<br>손등이 패었다. 천에 거른 물을 다 버렸다. 버리는 손이 떨렸다.`,
            win:{ exp:20, dream:3, item:'맑은 물' },
            lose:{ hp:-34, spirit:-20 } },
          { l:'② 코일 위를 살피며 받이로 다가가 물을 뜬다.', k:'sense', dc:25,
            doom:{ title:'코일 위의 것', what:'맑은 피를 맞았습니다', dc:19, sec:43,
              text:`코일 위를 올려다봤다. 어둡다. 아무것도 안 보인다. 받이로 다가가 컵을 넣었다.<br><br>물 위로 물방울이 떨어진다. 똑. 똑. 그 사이로 하나가 다르게 떨어진다. 무겁게. 물에 닿자 김이 오른다.<br>위를 다시 봤다. 코일 사이에 무언가 접혀 걸려 있다. 다친 것이다. 누가 예전에 베었다. 아직 피가 흐른다.<br><br>그것이 몸을 뒤척인다. 상처가 벌어진다. 맑은 것이 줄기로 쏟아진다. 올려다본 얼굴로.`,
              dieText:`베면 그 밑에 서 있지 마라.<br><br>물을 마시려고 서 있던 자리다. 그것이 거기 있는 줄 몰랐다.<br>응축수 받이 바닥에 구멍이 하나 더 났다. 물이 다 샜다.` },
            ok:`받이로 다가가기 전에 물이 떨어지는 소리를 셌다. 똑, 똑. 그 사이에 한 번 둔한 소리. 무겁게 떨어지는 것이 있다.<br><br>손전등을 코일 사이로 비췄다. 접힌 것 하나가 걸려 있다. 다친 데에서 맑은 것이 한 방울씩. 그것이 떨어지는 자리만 받이 쇠가 얇다.<br>그 자리를 피해 반대쪽 끝에서 컵으로 물을 떴다. 차다. 다들 조용히 마셨다.<br><br>마시는 동안 위의 것은 한 번도 움직이지 않았다. 다친 것은 쉰다.`,
            win:{ exp:22, dream:3, mind:8 } }
        ] },

      { t:'설비층 — 덕트 갈림길',
        x:`덕트가 세 갈래로 나뉜다. 갈림길 쇠벽에 매직으로 화살표가 그려져 있다. 세 갈래 모두에.<br><br>
          왼쪽 화살표 밑에 한 글자. 둥. 가운데 밑에는 아무것도 없다. 오른쪽 밑에는 적다 만 획 하나.<br>
          세 갈래 다 안에서 소리가 난다. 왼쪽은 바스락. 오른쪽은 똑, 똑. 가운데는 조용하다.<br><br>
          조용한 쪽이 좋은 쪽이라고 누군가 말했다. 다들 그 말을 오래 생각했다.`,
        o:[
          { l:'① 조용한 가운데 갈래로 간다.', k:'sense', dc:25,
            doom:{ title:'조용한 갈래', what:'둥지 쪽으로 끌려갑니다', dc:19, sec:43,
              text:`가운데로 들어갔다. 조용하다. 덕트 쇠가 점점 따뜻해진다.<br><br>조용한 이유를 그때 알았다. 소리를 내는 것이 없는 게 아니다. 다 듣고 있어서 조용하다.<br>앞에 접힌 것들이 줄지어 있다. 덕트를 따라. 다 솔기가 열려 있다. 이쪽 숨소리를 듣고 있다.<br><br>맨 앞의 것이 펴진다. 마디가 덕트를 꽉 채우며 다가와 어깨를 감는다. 몸이 앞으로 끌려간다. 더 따뜻한 쪽으로. 둥지 쪽으로.`,
              dieText:`조용한 쪽은 듣는 쪽이다.<br><br>왼쪽 화살표 밑에 둥이라고 적은 사람은 가운데에 아무것도 적지 않았다. 적을 틈이 없었다.<br>가운데 갈래는 그 뒤로도 늘 조용했다.` },
            ok:`가운데로 몇 걸음 들어갔다. 조용하다. 너무. 숨소리가 덕트에 울리지 않는다. 무언가가 소리를 먹는다.<br><br>손전등을 켜지 않았다. 손을 앞으로 뻗었다. 손끝에 무언가 닿는다. 매끈한 판. 솔기가 손가락 밑에서 벌어진다.<br>손을 거두고 숨을 멈춘 채 뒷걸음으로 나왔다. 판은 따라오지 않았다. 손끝 한 번은 아직 확인이 아니다.<br><br>갈림길로 돌아와 앉았다. 손끝이 오래 떨렸다. 조용한 쪽은 듣는 쪽이다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 바람이 부는 쪽을 따라 오른쪽으로 간다.', k:'fix', dc:24,
            ok:`갈림길에 젖은 손가락을 세웠다. 오른쪽에서 찬바람이 분다. 바깥으로 나가는 배기 쪽이다.<br><br>오른쪽의 두드림은 멀다. 덕트 벽을 타고 울려 오는 소리다. 가까이 있는 게 아니다.<br>바람을 거슬러 기었다. 찬바람이 얼굴을 친다. 그쪽으로 가는 동안 두드림이 점점 뒤로 갔다.<br><br>오른쪽 화살표 밑 적다 만 획을 지나칠 때 봤다. 아래로 그은 획이다. 아래. 그 끝에 점검구가 있었다.`,
            ng:`바람을 따라갔는데 바람이 갑자기 반대로 분다. 어딘가에서 환풍기가 돌았다. 아니면 누가 돌렸다.<br><br>찬바람이 더운 바람이 된다. 막 냄새가 섞인다. 앞에서 두드림이 가까워진다.<br>뒤로 기어 갈림길까지 왔다. 무릎이 다 벗겨졌다. 똑같은 길을 두 번 기었다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-35, mind:-19 } },
          { l:'③ 마음 가는 갈래로 들어가 떨어진 배낭을 줍는다.', k:'luck', dc:24, only:'luck',
            ok:`생각하지 않고 오른쪽을 골랐다. 그냥 그쪽이 마음에 걸렸다.<br><br>오른쪽 갈래 들머리에 배낭 하나가 걸려 있다. 덕트가 좁아 일꾼들이 아직 못 끌어간 것이다.<br>안에 은박 봉지가 셋. 말린 고기. 그리고 손으로 그린 덕트 지도 한 장. 오른쪽 끝에 동그라미. 점검구.<br><br>배낭 주인은 지도를 다 그렸다. 지도대로 가지는 못했다.`,
            ng:`골랐다. 왼쪽. 그냥 그쪽이 마음에 걸렸다. 마음에 걸린 게 틀렸다.<br><br>왼쪽 갈래에 막이 걸려 있다. 바스락 소리가 일꾼들이었다. 머리를 들이밀자 다리 많은 것들이 얼굴로 뛰어올랐다.<br>뒤로 빠졌다. 귀와 뺨을 물렸다. 물린 자리가 한참 화끈거렸다.`,
            win:{ exp:20, dream:3, item:'말린 고기' },
            lose:{ hp:-33, spirit:-22 } }
        ] },

      { t:'설비층 — 매달린 고치',
        x:`덕트가 넓어지는 자리에 고치가 매달려 있다. 사람만 하다. 천장 철망에 막으로 붙었다.<br><br>
          고치가 덕트를 반쯤 막았다. 지나가려면 고치 밑을 기어야 한다. 바로 밑을.<br>
          고치 겉으로 명찰이 비친다. 막 안쪽에 아직 달려 있다. 사진 속 얼굴이 웃고 있다.<br><br>
          고치에서 째깍째깍 소리가 난다. 식는 엔진 같은 소리. 소리가 점점 빨라진다.`,
        o:[
          { l:'① 고치를 끊어 떨어뜨리고 지난다.', k:'break', dc:25,
            doom:{ title:'떨어진 고치', what:'고치가 터졌습니다', dc:19, sec:43,
              text:`고치를 천장에 붙인 막을 칼로 끊었다. 하나, 둘. 고치가 기운다.<br><br>마지막 줄을 끊자 고치가 덕트 바닥에 떨어진다. 털썩. 째깍 소리가 멎는다.<br>그리고 고치가 갈라진다. 위에서 아래로. 솔기처럼. 안에서 젖은 것이 펴진다. 마디 하나, 둘, 셋. 갓 나온 것이다. 작다. 그래도 사람보다 크다.<br><br>판이 이쪽을 향한다. 솔기가 벌어진다. 갓 나온 것은 온몸이 젖어 있다. 젖은 것이 다 맑은 것이다.`,
              dieText:`고치는 때가 되면 열린다. 떨어뜨리면 때가 앞당겨진다.<br><br>덕트 바닥에 빈 고치 껍질이 남았다. 명찰은 막 안쪽에 아직 붙어 있었다.<br>사진 속 얼굴은 여전히 웃고 있었다.` },
            ok:`끊기 전에 귀를 대 봤다. 째깍 소리가 빠르다. 때가 가깝다.<br><br>그래서 끊지 않았다. 위쪽 막만 조금 갈라 고치를 천장 쪽으로 밀어 올렸다. 밑에 기어갈 틈이 한 뼘 더 났다.<br>한 명씩 그 밑을 기었다. 째깍 소리가 등 위를 지나간다. 다 지나고 나서 돌아봤다.<br><br>고치 아래쪽이 갈라지기 시작했다. 솔기처럼. 서둘러 다음 모퉁이를 돌았다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 숨을 죽이고 고치 밑을 기어 지난다.', k:'hide', dc:24,
            ok:`고치 밑에 엎드려 기었다. 고치 바닥이 등에 닿을 듯하다. 따뜻하다. 째깍, 째깍.<br><br>숨을 쉬지 않았다. 째깍 소리 사이사이에 한 번씩 무릎을 옮겼다.<br>막 너머 명찰 사진이 눈높이에 왔다. 웃고 있다. 그 밑에서 무언가 마디를 접었다 폈다 한다. 연습하듯이.<br><br>다 지났다. 다음 사람을 기다리는 동안 째깍 소리를 셌다. 조금 빨라졌다.`,
            ng:`기다가 등이 고치 바닥에 닿았다. 째깍 소리가 멎는다.<br><br>고치 안에서 무언가 등 쪽으로 몸을 민다. 막 너머로 마디가 불룩 솟아 등을 누른다. 뜨겁다.<br>배를 바닥에 붙이고 빠르게 빠져나왔다. 등에 막이 붙어 따라왔다. 떼어 낸 자리가 화상처럼 부풀었다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-36, mind:-19, spirit:-21 } },
          { l:'③ 마력의 불로 고치를 태운다.', k:'break', dc:24, cost:{ mana:32 },
            ok:`손바닥에 불을 모아 고치 밑동에 댔다. 막이 오그라든다. 불이 번진다. 천천히.<br><br>째깍 소리가 빨라진다. 그러다 멎는다. 고치가 쪼그라들며 한쪽으로 처진다. 안에서 아무것도 나오지 않았다.<br>타는 냄새가 덕트를 채운다. 막 냄새만은 아니었다. 다들 소매로 코를 막았다.<br><br>명찰은 녹지 않았다. 재 속에 떨어져 있다. 주워서 주머니에 넣었다. 누군가는 이름을 가지고 나가야 한다.`,
            ng:`불을 대는데 막이 잘 안 탄다. 젖어 있다. 연기만 난다. 연기가 덕트를 따라 퍼진다.<br><br>연기를 따라 덕트마다 두드림이 일어난다. 불 냄새를 안다. 사람이 왔다는 냄새다.<br>불을 거두고 고치 밑을 서둘러 기었다. 연기에 눈이 짓물렀다. 뒤에서 두드림이 몰려왔다.`,
            win:{ exp:22, dream:3, spirit:8 },
            lose:{ hp:-35, mind:-19, spirit:-22 } }
        ] },

      { t:'설비층 — 점검구 사다리',
        x:`덕트 끝에 점검구가 있다. 뚜껑을 들면 아래로 수직 통로다. 사다리가 박혀 있다.<br><br>
          통로 벽에 긁힌 자국이 길게 나 있다. 위에서 아래로가 아니라 아래에서 위로.<br>
          아래층 이름이 통로 벽에 페인트로 적혀 있다. 격리 구역. 글자 위에 막이 한 겹 덮였다.<br><br>
          사다리 칸 사이가 넓다. 발을 헛디디면 아래까지 한 번에 간다.`,
        o:[
          { l:'① 사다리를 빠르게 타고 내려간다.', k:'evade', dc:25,
            doom:{ title:'수직 통로', what:'수직 통로 위로 끌려 올라갑니다', dc:19, sec:42,
              text:`사다리를 손으로 미끄러지듯 내려갔다. 칸을 두 개씩 건너뛰며.<br><br>중간쯤에서 위가 어두워진다. 점검구 불빛이 가려졌다. 점검구 바로 밑 벽에 접혀 붙어 있던 것이 펴진 것이다. 일행과 이쪽 사이에서.<br>통로 벽의 긁힌 자국이 왜 아래에서 위로 났는지 알았다. 여기서는 끌고 올라간다.<br><br>어깨를 잡혔다. 마디가 겨드랑이 밑으로 감긴다. 사다리를 놓친 손이 허공을 긁는다. 수직 통로 위로 끌려 올라간다. 점검구 쪽이 아니라 옆 덕트 쪽으로.`,
              dieText:`수직 통로는 아래로도 위로도 길다.<br><br>일행이 다시 내려다봤을 때 사다리에는 아무도 없었다.<br>통로 벽에 아래에서 위로 긁힌 자국이 하나 더 생겼다.` },
            ok:`사다리를 빠르게 내려가다가 중간에서 멈췄다. 위의 불빛이 가려지는 게 이상했다.<br><br>올려다봤다. 점검구 바로 밑 벽에 접힌 것이 붙어 있다. 일행이 지나간 바로 옆이다. 지금 막 펴지려 한다.<br>소리쳤다. 위의 일행이 한꺼번에 뛰어내리듯 내려왔다. 다 같이 손을 놓고 마지막 두 칸을 떨어졌다.<br><br>바닥에 닿아 올려다보니 마디가 사다리를 쓸어내리고 있었다. 한 칸씩. 다 내려온 뒤였다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 손발 셋을 늘 붙이고 한 칸씩 내려간다.', k:'steady', dc:24,
            ok:`손 둘, 발 하나. 늘 셋이 사다리에 붙어 있게 했다. 느리다. 느려도 떨어지지는 않는다.<br><br>중간쯤에서 벽 쪽 그늘이 움직였다. 접힌 것이 벽에 붙어 있다. 사다리와 팔 하나 거리.<br>그것이 펴지지 않는다. 사다리 쇳소리가 일정하면 그것은 그걸 벽 소리로 듣는다. 일정하게 내려갔다. 한 칸에 숨 한 번.<br><br>바닥에 닿았다. 마지막 사람이 닿을 때까지 아무도 숨을 크게 쉬지 않았다.`,
            ng:`한 칸씩 내려가는데 칸 하나가 녹슬어 부러졌다. 발이 허공에 뜬다. 손 둘로만 매달렸다.<br><br>사다리가 운다. 벽의 그늘이 펴진다. 마디 끝이 등을 스친다.<br>손을 놓고 떨어졌다. 아래까지 세 칸. 발목이 꺾였다. 위에서 철컥 소리가 오래 울렸다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-38, mind:-18 } }
        ] }
    ] },

    // ───────── 6층 ─────────
    { name:'6층 — 격리 구역', scenes:[

      { t:'격리 구역 — 기밀실',
        x:`격리 구역에 들어가려면 기밀실을 지나야 한다. 안쪽 문과 바깥 문이 있다. 한 번에 한쪽만 열린다.<br><br>
          들어서면 등 뒤 문이 닫히고, 공기를 바꾸고, 앞문이 열린다. 한 주기에 일 분.<br>
          벽에 주기 기록판이 있다. 어젯밤에만 마흔 번 돌았다. 들어간 사람 칸은 비었다.<br><br>
          기밀실 천장에 비상 배기구가 있다. 지상 배기통으로 곧장 이어진다. 배기 밸브가 열리면 방 안 공기가 다 그리로 빠진다. 방 안에 있는 것도.`,
        o:[
          { l:'① 주기 버튼을 누르고 기밀실로 들어간다.', k:'fix', dc:25,
            doom:{ title:'마흔한 번째 주기', what:'배기구 밖으로 빨려 나갑니다', dc:19, sec:43,
              text:`버튼을 눌렀다. 문이 열린다. 들어섰다. 등 뒤 문이 닫힌다. 쿵.<br><br>앞문이 열리기를 기다린다. 일 분. 일 분이 지나도 안 열린다. 대신 천장에서 딸깍 소리가 난다. 배기 밸브다.<br>유리창 너머 제어판 앞에 무언가 서 있다. 긴 손가락 하나가 붉은 버튼 위에 있다. 사람이 하던 대로. 마흔 번 연습한 대로.<br><br>귀가 먹먹하다. 바람이 위로 분다. 몸이 들린다. 발이 바닥에서 떨어진다. 배기구 밖으로 빨려 나간다.`,
              dieText:`기밀실은 한 번에 한쪽만 열린다. 배기 밸브는 예외다.<br><br>주기 기록판에 한 줄이 더해졌다. 마흔한 번째. 들어간 사람 칸에 처음으로 숫자가 찍혔다.<br>나온 사람 칸은 비었다.` },
            ok:`버튼을 누르기 전에 유리창으로 기밀실 안을 들여다봤다. 천장 배기 밸브 손잡이가 열림 쪽으로 반쯤 돌아가 있다.<br><br>들어가서 제일 먼저 밸브 손잡이를 잠금 쪽으로 끝까지 돌렸다. 손으로. 그리고 손잡이에 허리띠를 감아 묶었다.<br>주기가 돈다. 일 분. 천장에서 딸깍 소리가 났다. 밸브가 열리려다 허리띠에 걸려 멈췄다.<br><br>앞문이 열렸다. 나가며 돌아봤다. 유리창 너머 제어판 앞에서 긴 손가락이 붉은 버튼을 몇 번 더 눌렀다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 주기 기록을 읽어 그것이 배운 순서를 안다.', k:'gaze', dc:25,
            ok:`기록판을 처음부터 읽었다. 마흔 번이 다 같지 않다.<br><br>처음 열 번은 엉망이다. 문이 반쯤 열리다 말고, 공기 교체가 끊기고. 스무 번째부터 순서가 맞는다. 서른 번째부터는 배기 밸브를 섞는다. 주기 한가운데에.<br>배기는 매번 같은 때다. 등 뒤 문이 닫히고 마흔을 셀 때.<br><br>마흔을 세기 전에 앞문 비상 손잡이를 당기면 된다. 서른을 세고 당겼다. 문이 열렸다. 경보가 울렸다. 그건 감수했다.`,
            ng:`기록을 읽는 동안 기밀실이 혼자 돌았다. 마흔한 번째. 안에는 아무도 없다.<br><br>배기 밸브가 열리는 소리가 났다. 빈 기밀실의 공기가 빠지는 소리. 그 소리에 문틈 쪽으로 몸이 쏠렸다. 문틈이 숨을 들이켜는 것 같다.<br>귀에서 피가 났다. 문에서 떨어져 한참 고개를 흔들었다. 연습이었다. 이쪽을 보고 하는 연습.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-35, mind:-19, spirit:-22 } },
          { l:'③ 수동 레버로 배기 밸브를 밖에서 먼저 잠근다.', k:'fix', dc:24, only:'fix',
            ok:`기밀실 옆 점검함에 수동 레버가 있다. 배기 밸브 차단. 수동으로 잠그라는 말이 절차서마다 적혀 있었다.<br><br>레버를 내리고 쇠핀을 꽂았다. 쇠핀은 버튼으로 못 뺀다. 손으로만 뺀다.<br>주기를 돌렸다. 마흔을 셀 때 천장에서 딸깍 소리가 났다. 아무 일도 없었다.<br><br>앞문이 열렸다. 지나며 보니 제어판 앞의 것이 붉은 버튼을 누르고 있다. 몇 번이고. 그러다 이쪽 점검함 쪽을 봤다. 쇠핀을 본 것이다.`,
            ng:`레버를 내렸는데 끝까지 안 내려간다. 막이 끼어 있다. 억지로 눌렀다. 레버 축이 부러졌다.<br><br>부러진 소리가 기밀실을 울린다. 제어판 앞의 것이 고개를 든다. 붉은 버튼 위로 손가락이 간다.<br>문에서 물러섰다. 빈 기밀실에서 공기가 빠지는 소리가 났다. 부러진 레버에 손이 베였다. 깊다.`,
            win:{ exp:22, dream:3, mind:8 },
            lose:{ hp:-36, mind:-20 } }
        ] },

      { t:'격리 구역 — 압력 복도',
        x:`기밀실 뒤 복도에 압력계가 줄지어 있다. 바늘이 다 같이 떨린다.<br><br>
          복도 칸마다 격벽이 있다. 압력이 떨어지면 저절로 내려온다. 내려오는 데 두 박자. 다시 올라가는 데 열 박자.<br>
          격벽 아래 바닥에 홈이 깊다. 홈 안에 신발 한 짝이 끼어 있다. 반으로 잘렸다.<br><br>
          바늘이 또 떨린다. 어딘가에서 기밀실이 또 돈다.`,
        o:[
          { l:'① 격벽이 올라간 틈에 다음 칸으로 뛴다.', k:'evade', dc:25,
            doom:{ title:'두 박자', what:'격벽에 끼었습니다', dc:19, sec:42,
              text:`격벽이 올라갔다. 뛰었다. 넷, 다섯.<br><br>여섯에서 바늘이 떨린다. 어딘가에서 기밀실이 또 돈다. 압력이 떨어진다. 격벽이 내려온다. 두 박자.<br>두 박자는 생각보다 짧다. 상체는 넘어갔다. 다리가 아직 홈 위다.<br><br>쇳덩이가 내려온다. 일행이 팔을 잡는다. 격벽은 사람 사정을 모른다.`,
              dieText:`격벽은 압력을 지키는 문이다. 그것 말고는 아무것도 안 지킨다.<br><br>홈 안에 끼인 신발이 두 짝이 됐다.<br>압력계 바늘은 곧 다시 잔잔해졌다.` },
            ok:`격벽이 올라가자마자 뛰지 않았다. 바늘을 봤다. 잔잔하다. 그때 뛰었다.<br><br>다음 칸 홈을 넘을 때 바늘이 떨렸다. 등 뒤에서 격벽이 내려온다. 쿵. 발뒤꿈치 바로 뒤.<br>칸마다 그렇게 했다. 바늘이 잔잔할 때 뛰고 떨리면 섰다.<br><br>마지막 칸에서 돌아봤다. 홈 안의 반쪽 신발이 이쪽을 향해 놓여 있었다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 칸 한가운데 서서 바늘이 잔잔해질 때마다 건넌다.', k:'steady', dc:25,
            ok:`칸 한가운데 서서 바늘만 봤다. 격벽이 내려와도 칸 안은 안전하다. 홈만 피하면 된다.<br><br>바늘이 떨리면 격벽이 내려오고, 바늘이 잔잔해지면 열 박자 뒤에 올라간다. 올라가면 곧장 다음 칸으로.<br>칸 하나에 한참. 여덟 칸. 다리가 저렸다. 저린 건 견딘다.<br><br>마지막 격벽을 지나 돌아보니 바늘이 계속 떨리고 있다. 기밀실이 쉬지 않고 돈다. 누가 연습을 계속한다.`,
            ng:`칸 한가운데 서 있는데 바늘이 끝까지 떨어진다. 이쪽 칸 공기가 빠진다. 앞뒤 격벽이 다 내려와 있다.<br><br>숨이 안 들어간다. 귀가 터질 것 같다. 눈앞이 하얗다.<br>바늘이 돌아오고 격벽이 올라갈 때까지 바닥에 엎드려 버텼다. 코와 귀에서 피가 났다. 일어서니 다리가 남의 것이다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-37, mind:-20, spirit:-22 } },
          { l:'③ 내공으로 숨을 길게 늘여 압력을 견딘다.', k:'steady', dc:24, cost:{ qi:33 },
            ok:`숨을 단전에 가두고 몸 안을 단단히 채웠다. 밖의 공기가 빠져도 안의 숨은 안 빠진다.<br><br>바늘이 떨어질 때도 그냥 걸었다. 격벽이 내려오면 칸 안에서 섰다. 숨을 쉬지 않아도 된다.<br>일행 등에 손을 대고 숨을 나눠 줬다. 하나씩. 다 같이 칸을 건넜다.<br><br>마지막 격벽 앞에서 숨을 풀었다. 몸이 크게 흔들린다. 숨 하나를 오래 들고 있었다.`,
            ng:`숨을 가뒀는데 바늘이 너무 오래 떨어져 있다. 안의 숨이 밖으로 밀고 나간다.<br><br>기가 터지듯 흩어진다. 코피가 쏟아진다. 무릎이 꺾였다.<br>일행이 끌고 다음 칸으로 갔다. 한동안 숨이 반만 쉬어졌다.`,
            win:{ exp:22, dream:3, hp:8 },
            lose:{ hp:-36, mind:-21, spirit:-23 } }
        ] },

      { t:'격리 구역 — 감방 복도',
        x:`격리 감방이 양쪽으로 늘어섰다. 문마다 작은 창이 있다. 창마다 얼굴이 있다.<br><br>
          다 깨어 있다. 다 문 쪽을 보고 서 있다. 목덜미가 불룩하다. 얼굴이 발갛다. 아무도 창을 두드리지 않는다.<br>
          감방 문 몇 개가 열려 있다. 열린 감방 안은 비었다. 천장 환기구 덮개가 없다.<br><br>
          복도는 하나다. 끝까지 사십 걸음.`,
        o:[
          { l:'① 열린 감방 문 그늘을 골라 숨어 가며 지난다.', k:'hide', dc:25,
            doom:{ title:'빈 감방', what:'빈 감방 안으로 끌려 들어갑니다', dc:19, sec:42,
              text:`열린 감방 문 그늘에서 그늘로 옮겨 갔다. 창의 얼굴들이 그늘을 따라 고개를 돌린다.<br><br>세 번째 그늘에 들어섰을 때 등 뒤 감방 안이 따뜻하다. 비어 있다던 감방이다. 천장 환기구에 덮개가 없다.<br>숙주들이 문 쪽을 보고 서 있던 까닭을 안다. 문을 지키는 게 아니다. 문 앞에 무엇이 오는지 알려 주는 것이다.<br><br>머리 위에서 마디가 내려온다. 그늘째 덮는다. 몸이 빈 감방 안으로 끌려 들어간다. 감방 문이 천천히 닫힌다.`,
              dieText:`열린 감방은 비어 있었다. 닫힐 때까지.<br><br>복도의 얼굴들은 다시 문 쪽을 봤다. 다들 같은 쪽을.<br>창 하나에 얼굴이 하나 늘었다. 아직 얼굴이 발갛지는 않았다.` },
            ok:`그늘을 골라 가다가 세 번째 감방 앞에서 멈췄다. 그 안이 따뜻하다. 문틈으로 더운 바람이 나온다.<br><br>빈 감방이 따뜻할 리가 없다. 그늘을 버리고 복도 한가운데로 나섰다. 창의 얼굴들이 일제히 이쪽을 본다.<br>세 번째 감방 천장에서 마디가 내려와 그늘을 더듬었다. 방금 이쪽이 들어가려던 그늘을.<br><br>복도 끝까지 한가운데로 걸었다. 그늘이 숨을 데가 아니라는 걸 이제 안다.`,
            win:{ exp:22, dream:3 } },
          { l:'② 열린 감방 수를 세고 그 앞만 빨리 지난다.', k:'sense', dc:25,
            ok:`복도 들머리에서 셌다. 열린 감방 다섯. 왼쪽 둘, 오른쪽 셋. 열린 감방은 천장 덮개가 없다.<br><br>닫힌 감방 앞은 천천히, 열린 감방 앞은 빨리 지났다. 숨도 열린 데 앞에서는 참았다.<br>네 번째 열린 감방 앞을 지날 때 천장에서 무언가 움찔했다. 그때 이미 다섯 번째 앞이었다.<br><br>복도 끝에서 돌아보니 창의 얼굴들이 전부 이쪽을 보고 있다. 줄곧 그랬다.`,
            ng:`다섯이라고 셌는데 여섯이었다. 하나는 문이 닫힌 척 한 뼘 열려 있었다.<br><br>그 앞을 천천히 지났다. 문틈에서 마디 끝이 나와 허리띠를 걸었다. 당긴다.<br>허리띠를 풀어 버리고 굴렀다. 문틈이 허리띠를 먹었다. 옆구리에 줄이 그어졌다. 깊다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-37, spirit:-23 } },
          { l:'③ 복도 한가운데를 고개 들고 멈추지 않고 걷는다.', k:'steady', dc:24, only:'steady',
            ok:`복도 한가운데로 들어섰다. 고개를 들었다. 앞만 봤다. 걸음 수는 세지 않았다.<br><br>창마다 얼굴들이 따라 돈다. 열린 감방 천장에서 철컥 소리가 난다. 멈추지 않았다. 멈추면 그 자리가 정해진다.<br>사십 걸음. 끝에 닿았다. 뒤를 돌아보지 않고 문을 열었다.<br><br>문 너머에서 숨을 쉬었다. 뒤에서 얼굴들이 다시 문 쪽으로 도는 소리가 났다. 수십 개의 목이 한꺼번에.`,
            ng:`서른 걸음에서 발이 멈췄다. 이쪽 뜻이 아니다. 창 하나의 얼굴이 아는 얼굴처럼 보였다.<br><br>멈춘 사이 열린 감방에서 마디가 펴진다. 다시 걸었다. 늦었다. 마디 끝이 어깨를 갈랐다.<br>문을 넘어 쓰러졌다. 아는 얼굴이 아니었다. 그래도 그렇게 보였다.`,
            win:{ exp:22, dream:3, spirit:8 },
            lose:{ hp:-36, mind:-21, spirit:-24 } }
        ] },

      { t:'격리 구역 — 격리 의무실',
        x:`격리 구역 의무실은 작다. 침대 셋. 셋 다 비었다. 침대 시트는 없다.<br><br>
          약장이 열려 있다. 병은 다 깨졌다. 맨 아래 칸 종이 상자만 성하다. 겉에 마른 약초, 습포용이라고 적혀 있다.<br>
          침대 밑이 어둡다. 셋 다.<br><br>
          상자를 가지려면 침대 사이를 지나야 한다.`,
        o:[
          { l:'① 침대 밑을 비춰 가며 상자를 챙겨 상처를 싸맨다.', k:'heal', dc:25,
            ok:`침대 밑을 하나씩 비췄다. 첫째, 비었다. 둘째, 비었다. 셋째, 막이 깔려 있다. 그 위에 아무것도 없다. 아직은.<br><br>셋째 침대에서 먼 쪽으로 돌아 상자를 꺼냈다. 마른 약초가 습포용으로 묶여 있다. 물에 적시면 바로 쓴다.<br>그 자리에서 일행의 깊은 상처를 하나씩 싸맸다. 옆구리, 어깨, 손바닥. 약초 냄새가 식초 냄새를 덮는다.<br><br>남은 꾸러미는 챙겼다. 아래층에 갈 상처가 아직 많다.`,
            ng:`셋째 침대 밑을 비추는 순간 막 위에서 무언가 손전등을 쳤다. 손전등이 굴러간다.<br><br>어둠 속에서 손목에 무언가 닿았다. 작다. 일꾼이다. 여럿이다. 물었다.<br>상자를 끌어안고 뒷걸음질 쳤다. 손목에 이빨 자국이 둥글게 셋. 상자 안 약초 반이 쏟아졌다.`,
            win:{ exp:21, dream:3, item:'약초 뭉치', hp:10 },
            lose:{ hp:-38, spirit:-22 } },
          { l:'② 침대 사이를 곧장 지나 상자만 빨리 집어 온다.', k:'luck', dc:25,
            doom:{ title:'셋째 침대 밑', what:'침대 밑으로 끌려 들어갑니다', dc:20, sec:42,
              text:`침대 사이로 곧장 걸었다. 빠르게. 상자를 집었다. 가볍다.<br><br>돌아서는데 발목이 차갑다. 셋째 침대 밑에서 무언가 나와 있다. 마디 끝. 접힌 채 침대 밑에 들어가 있던 것이다. 침대 밑은 생각보다 넓다.<br>발목을 감는다. 넘어졌다. 상자가 날아간다. 약초가 쏟아진다.<br><br>바닥을 쓸며 몸이 침대 밑으로 끌려 들어간다. 침대 다리를 잡았다. 침대가 같이 끌린다.`,
              dieText:`침대 밑은 어둡고 따뜻하다. 아이들이 거기를 무서워하는 데에는 이유가 있다.<br><br>격리 의무실 셋째 침대 밑 막이 조금 두꺼워졌다.<br>바닥에 쏟아진 약초에서 한참 향이 났다.` },
            ok:`침대 사이로 곧장 걸었다. 빠르게. 상자를 집었다. 셋째 침대 옆을 지날 때 발목에 바람이 닿았다. 숨이다.<br><br>멈추지 않고 첫째 침대 위로 뛰어올라 건너편으로 넘었다. 바닥을 안 디뎠다.<br>뒤에서 셋째 침대 밑으로 마디가 나와 바닥을 쓸었다. 방금 디딜 뻔한 자리를.<br><br>상자 안에 마른 약초. 습포용. 문을 닫고 문 앞에 빈 침대를 밀어 놓았다.`,
            win:{ exp:22, dream:3, item:'약초 뭉치' } }
        ] },

      { t:'격리 구역 — 소각실',
        x:`소각실 문이 열려 있다. 소각로는 꺼져 있다. 안에 하얀 재가 수북하다.<br><br>
          재 위에 고치 껍질이 반쯤 탄 채 쌓였다. 누가 여기서 고치를 태우다 그만뒀다. 그만둔 이유는 남아 있지 않다.<br>
          소각로 연도가 위로 뻗었다. 연도 둘레에 긁힌 자국이 많다. 따뜻할 때 몰려든 자국이다.<br><br>
          소각실 반대편 문이 다음 칸으로 간다. 그 앞 복도에 3형 둘이 접혀 있다.`,
        o:[
          { l:'① 소각로를 켜서 열로 접이들을 끌어들인다.', k:'fix', dc:25,
            ok:`소각로 점화 손잡이를 돌렸다. 불이 붙는다. 하얀 재가 날린다. 금방 뜨거워진다.<br><br>복도의 둘이 판을 든다. 솔기가 벌어진다. 열을 듣는 것이다. 펴진다. 천천히 소각실로 온다.<br>연도 쪽으로 간다. 따뜻한 데로. 연도를 감고 마디를 접는다. 몸을 녹이는 것처럼.<br><br>그 등 뒤로 반대편 문을 빠져나갔다. 문을 닫으며 봤다. 연도에 감긴 것이 하나 더 늘어 있었다. 셋이다. 하나는 처음부터 위에 있었다.`,
            ng:`불을 붙였다. 복도의 둘이 온다. 생각보다 빠르다. 열이 아니라 불을 켠 손을 듣는다.<br><br>소각실 안에서 마주쳤다. 재 속으로 굴렀다. 뜨거운 재가 옷 속으로 들어온다.<br>재를 뒤집어쓴 채 반대편 문으로 기어 나왔다. 등과 팔이 데었다. 재가 상처에 붙어 안 떨어졌다.`,
            win:{ exp:22, dream:3 },
            lose:{ hp:-38, mind:-20, spirit:-23 } },
          { l:'② 소각로 옆 연도 틈으로 돌아 지난다.', k:'evade', dc:25,
            doom:{ title:'연도', what:'연도 위로 끌려 올라갑니다', dc:20, sec:41,
              text:`연도와 벽 사이 좁은 틈으로 몸을 넣었다. 연도 쇠가 아직 미지근하다.<br><br>틈 중간쯤에서 위가 어두워진다. 연도 위쪽에 무언가 감겨 있다. 긁힌 자국이 많은 이유다. 따뜻할 때 몰려든 것이 아직 하나 남아 있었다.<br>그것이 연도를 타고 내려온다. 마디가 틈으로 들어와 목을 감는다.<br><br>몸이 연도를 따라 들린다. 쇠 벽에 등이 긁힌다. 연도 위로 끌려 올라간다. 재가 눈으로 쏟아진다.`,
              dieText:`연도는 따뜻한 것이 올라가는 길이다.<br><br>소각로는 그날 켜지지 않았다. 그래도 연도 위쪽이 한동안 따뜻했다.<br>연도 둘레 긁힌 자국이 하나 늘었다.` },
            ok:`틈으로 몸을 넣기 전에 연도에 손바닥을 댔다. 미지근하다. 위쪽이 더 따뜻하다. 위에 무언가 있다.<br><br>틈으로 가지 않고 소각로 투입구 앞을 지났다. 재 위로. 발자국이 남는다. 상관없다.<br>연도 위에서 마디 하나가 내려와 틈을 더듬었다. 아무것도 안 걸렸다.<br><br>반대편 문 앞에서 돌아봤다. 재 위 발자국을 그것이 내려다보고 있었다. 하나씩. 세는 것처럼.`,
            win:{ exp:23, dream:3 } },
          { l:'③ 마력의 불을 복도 끝에 던져 둘을 떼어 놓는다.', k:'break', dc:24, cost:{ mana:33 },
            ok:`손바닥에 불을 모아 복도 반대쪽 끝으로 던졌다. 불이 굴러가 벽에 부딪쳐 번진다.<br><br>복도의 둘이 판을 돌린다. 하나가 펴져 그쪽으로 간다. 다른 하나는 남는다. 셈을 나눠서 한다.<br>남은 하나 쪽으로 불을 하나 더 던졌다. 이번엔 가까이. 그것이 물러나 접힌다. 불 앞에서는 접는다.<br><br>접힌 것 옆을 지났다. 판이 이쪽을 따라 돌았다. 불이 꺼질 때까지 펴지지 않았다.`,
            ng:`던진 불이 복도 끝에서 금방 꺼진다. 바닥에 막이 깔려 불을 먹었다.<br><br>둘 다 움직이지 않는다. 불 던진 쪽으로 판만 돌린다. 하나가 펴진다. 이쪽으로.<br>소각실로 도로 뛰어들었다. 문을 닫는데 마디 끝이 문틈에 끼어 손등을 찍었다. 문 너머에서 오래 문을 두드렸다.`,
            win:{ exp:22, dream:3 },
            lose:{ hp:-37, mind:-21, spirit:-23 } }
        ] },

      { t:'격리 구역 — 제어실',
        x:`격리 구역 제어실은 유리로 되어 있다. 불이 켜져 있다. 안에 3형이 있다.<br><br>
          반쯤 접힌 채 제어판 앞에 앉아 있다. 긴 손가락 하나로 버튼을 누른다. 하나씩. 순서대로.<br>
          버튼이 눌릴 때마다 어딘가에서 문이 열리고 닫힌다. 압력계 바늘이 떨린다.<br><br>
          사람이 하던 일을 보고 배웠다. 제법 잘한다. 아래층으로 가는 통로는 제어실 창 앞을 지난다.`,
        o:[
          { l:'① 제어실 창 밑으로 기어 지난다.', k:'hide', dc:25,
            doom:{ title:'딸깍', what:'제어실 안으로 끌려 들어갑니다', dc:20, sec:41,
              text:`창 밑에 엎드려 기었다. 머리 위로 버튼 누르는 소리가 난다. 딸깍. 딸깍.<br><br>창 가운데쯤에서 딸깍 소리가 멎었다. 버튼을 누르던 손가락이 멈춘 것이다. 대신 다른 소리. 제어실 문 손잡이가 내려가는 소리.<br>그것은 창으로 보는 게 아니다. 듣는다. 엎드린 몸이 바닥을 쓰는 소리를.<br><br>문이 열린다. 마디가 바닥을 쓸며 다가와 발목을 감는다. 몸이 제어실 안으로 끌려 들어간다. 문이 닫힌다. 딸깍. 다시 버튼 소리.`,
              dieText:`제어실 버튼은 누르는 순서가 있다. 그것은 순서를 배웠다.<br><br>그날 이후 제어실 버튼 소리가 하나 더 빨라졌다.<br>압력계 바늘이 조금 더 자주 떨렸다.` },
            ok:`창 밑으로 기다가 멈췄다. 버튼 소리가 딸깍, 할 때만 움직였다. 소리 사이에는 멈췄다.<br><br>버튼을 누를 때 그것은 버튼 소리를 듣는다. 제 손가락 소리를. 그 사이에만 다른 소리를 듣는다.<br>딸깍에 한 번, 딸깍에 한 번. 창 끝까지 갔다.<br><br>창 끝에서 일어서며 봤다. 그것의 손가락이 버튼 위에서 멈춰 있었다. 무언가 셈이 안 맞는 것처럼.`,
            win:{ exp:23, dream:3 } },
          { l:'② 누르는 순서를 지켜보고 다음에 열릴 문을 안다.', k:'gaze', dc:25,
            ok:`복도 모퉁이에서 제어실 안을 봤다. 손가락이 버튼을 누른다. 기밀실, 격벽, 셔터. 순서가 있다.<br><br>세 번 돌았다. 순서는 매번 같다. 셔터 버튼 다음에 한 번 쉰다. 쉬는 동안 아래층 통로 셔터가 올라가 있다.<br>사람이 하던 일을 그대로 배웠다. 사람이 쉬던 자리에서 쉰다.<br><br>쉬는 때를 기다려 통로로 갔다. 셔터 앞에 닿았을 때 제어실에서 다시 딸깍 소리가 났다.`,
            ng:`보는 동안 그것이 버튼을 누르다 말고 판을 이쪽으로 돌렸다. 유리 너머로. 모퉁이 쪽으로.<br><br>보는 것은 소리가 안 나는데. 그것은 보는 것을 안다. 시선이 아니라 이쪽 숨이 멈춘 것을.<br>도망쳤다. 뒤에서 격벽이 하나씩 닫힌다. 이쪽이 가는 쪽으로. 둘 사이에 끼일 뻔했다. 어깨가 쇠에 짓눌렸다.`,
            win:{ exp:22, dream:3, mind:9 },
            lose:{ hp:-39, mind:-21, spirit:-24 } },
          { l:'③ 무력으로 제어실 문을 쇠파이프로 막는다.', k:'steady', dc:24, cost:{ might:34 },
            ok:`쇠파이프를 제어실 문손잡이와 벽 배관 사이에 끼웠다. 무력을 실어 비틀어 박았다.<br><br>안의 것이 판을 돌린다. 문손잡이를 내린다. 안 열린다. 다시. 파이프가 휜다. 버틴다.<br>그것이 버튼 하나를 눌렀다. 이쪽 복도 불이 꺼졌다. 화가 났다는 뜻일 것이다.<br><br>어둠 속에서 벽을 짚어 지났다. 등 뒤에서 문손잡이가 오래 덜컹거렸다. 파이프는 버텼다.`,
            ng:`파이프를 끼우는 중에 문이 안에서 열렸다. 그것이 먼저 손잡이를 당겼다.<br><br>파이프를 휘둘렀다. 마디에 맞았다. 파이프가 휜다. 맞은 자리에서 맑은 것이 튄다. 팔뚝에.<br>뒤로 물러서며 파이프를 던졌다. 팔뚝 살갗이 녹아 붙었다. 문은 다시 닫혔다. 안에서 딸깍 소리가 이어졌다.`,
            win:{ exp:23, dream:3 },
            lose:{ hp:-40, mind:-20 } }
        ] },

      { t:'격리 구역 — 비상 셔터',
        x:`아래층으로 가는 통로에 비상 셔터가 있다. 경보가 울린다. 셔터가 내려온다. 빠르다.<br><br>
          일행 반이 셔터 밑을 지났다. 나머지가 아직 이쪽이다.<br>
          셔터 너머에서 누가 손을 내민다. 셔터 밑 틈이 무릎 높이다. 줄어든다.<br><br>
          이쪽 복도 뒤에서 똑, 똑, 똑.`,
        o:[
          { l:'① 셔터 밑으로 굴러 빠진다.', k:'evade', dc:25,
            doom:{ title:'내려오는 셔터', what:'셔터에 깔렸습니다', dc:20, sec:40,
              text:`몸을 던져 굴렀다. 무릎 높이. 정강이 높이. 셔터가 내려온다.<br><br>어깨까지 넘어갔다. 허리가 셔터 밑이다. 쇠 날이 허리에 닿는다. 멈추지 않는다.<br>셔터는 내려오는 것만 안다. 밑에 무엇이 있는지 모른다. 제어실에서 누르는 손가락도 모른다. 아니면 안다.<br><br>너머의 손들이 어깨를 잡아끈다. 쇠가 무겁다. 아주 무겁다.`,
              dieText:`비상 셔터는 불을 막는 문이다. 끝까지 내려오게 되어 있다.<br><br>셔터는 끝까지 내려오지 못했다. 한 뼘이 남았다.<br>그 한 뼘으로 이쪽 복도의 두드림이 오래 새어 나왔다.` },
            ok:`셔터 내려오는 빠르기를 한 번 보고 몸을 던졌다. 비스듬히. 어깨부터.<br><br>굴렀다. 셔터 날이 발뒤꿈치를 스쳤다. 쿵. 바닥에 닿는 소리가 등 뒤에서.<br>먼저 간 일행이 이쪽을 끌어 일으켰다. 셔터 너머에서 두드림이 셔터를 친다. 똑, 똑, 똑.<br><br>셔터 아래 틈으로 마디 하나가 나와 더듬다가 들어갔다. 쇠 밑 틈은 손가락 하나 너비다.`,
            win:{ exp:23, dream:3 } },
          { l:'② 내민 손을 잡고 끌어 달라고 한다.', k:'bond', dc:25,
            doom:{ title:'두 쪽에서 당기는 손', what:'복도 뒤쪽으로 끌려갑니다', dc:20, sec:40,
              text:`셔터 밑으로 손을 뻗었다. 너머의 손이 잡는다. 당긴다.<br><br>그때 뒤에서 발목이 잡힌다. 이쪽 복도의 두드림이 다 왔다. 마디가 발목을 두 번 감는다. 당긴다. 반대로.<br>앞에서 당기고 뒤에서 당긴다. 몸이 셔터 밑에서 팽팽하다. 셔터가 계속 내려온다.<br><br>너머의 손이 미끄러진다. 땀 때문이다. 몸이 복도 뒤쪽으로 끌려간다. 셔터 틈으로 너머의 얼굴이 보였다가 사라진다.`,
              dieText:`셔터는 양쪽을 나눈다. 이쪽과 저쪽.<br><br>셔터가 바닥에 닿았다. 쿵. 이쪽 복도의 두드림이 멎었다.<br>셔터 저쪽에서 한참 셔터를 두드렸다. 이쪽에서 대답하지 않았다.` },
            ok:`셔터 밑으로 손을 뻗었다. 너머의 손들이 잡는다. 한 번에 당긴다.<br><br>뒤에서 마디가 발목을 감는 순간 몸이 셔터 밑을 빠져나갔다. 마디가 같이 딸려 왔다. 셔터가 그 위로 떨어진다.<br>쿵. 셔터 밑에 마디가 끼었다. 끼인 데서 맑은 것이 흐른다. 셔터 쇠가 연기를 낸다.<br><br>다들 물러섰다. 셔터 밑동이 녹아 구멍이 난다. 구멍 너머에서 판 하나가 이쪽을 들여다봤다. 계단으로 뛰었다.`,
            win:{ exp:23, dream:3 } }
        ] }
    ] },

    // ───────── 7층 ─────────
    { name:'7층 — 둥지', scenes:[

      { t:'둥지 — 막의 문',
        x:`계단을 내려가자 공기가 달라진다. 덥고 축축하다. 숨을 쉴 때마다 입 안이 끈적하다.<br><br>
          복도가 막으로 덮였다. 벽도 천장도 바닥도. 하얀 막이 겹겹이 쌓여 원래 모양이 안 보인다. 복도가 둥글어졌다.<br>
          막 속으로 무언가 지나간다. 막이 불룩했다 가라앉는다. 여기저기서.<br><br>
          앞이 막으로 된 문처럼 막혔다. 문 가운데에 세로로 틈이 있다. 3형 얼굴판의 솔기처럼.`,
        o:[
          { l:'① 막 벽에 몸을 붙여 숨어 들어간다.', k:'hide', dc:26,
            doom:{ title:'막 속의 길', what:'막 속으로 끌려 들어갑니다', dc:20, sec:40,
              text:`불룩한 데가 지나간 자리를 골라 막 벽에 등을 붙였다. 막이 따뜻하다. 살갗 같다.<br><br>숨을 죽이고 옆으로 옮겨 갔다. 등 뒤 막이 한 번 불룩해진다. 바로 뒤다. 막 속에서 무언가 이쪽 등을 따라 움직인다.<br>막은 벽이 아니다. 막 속이 길이다. 그것들은 막 속으로 다닌다.<br><br>막이 갈라진다. 등 뒤에서. 마디가 나와 어깨와 허리를 감는다. 몸이 막 속으로 끌려 들어간다. 막이 다시 닫힌다. 매끈하게.`,
              dieText:`둥지 벽은 막이다. 막 속은 따뜻하다.<br><br>일행이 막을 찢어 봤을 때 거기는 또 막이었다. 그 너머도.<br>막 한 곳이 오래 불룩했다가 천천히 가라앉았다.` },
            ok:`막 벽에 등을 붙이려다 그만뒀다. 불룩한 데가 지나간 자리가 막 속에서 이어진다. 길처럼.<br><br>막은 벽이 아니다. 막 속이 길이다. 그러니 벽에 붙는 건 길 위에 눕는 것이다.<br>복도 한가운데로 걸었다. 막 속의 불룩한 것들이 양옆으로 따라왔다가 멈췄다. 막 밖으로는 안 나온다. 아직.<br><br>막의 문 앞에 섰다. 양옆 벽이 동시에 한 번 불룩해졌다. 숨을 쉬는 것처럼.`,
            win:{ exp:22, dream:3 } },
          { l:'② 막의 틈을 손으로 천천히 갈라 들어간다.', k:'steady', dc:25,
            ok:`세로 틈에 손을 넣었다. 따뜻하고 끈적하다. 천천히 벌렸다. 막이 찢어지지 않고 늘어난다.<br><br>몸이 들어갈 만큼 벌렸다. 한 사람씩 들어갔다. 막이 등 뒤에서 닫힌다. 문처럼.<br>안쪽은 더 덥다. 숨이 무겁다. 손에 묻은 것이 마르면서 하얗게 굳는다. 장갑 같다.<br><br>마지막 사람이 들어오고 틈이 닫혔다. 닫힌 틈이 안쪽에서 보니 입처럼 생겼다. 생각하지 않기로 했다.`,
            ng:`틈을 벌리는데 막이 손목을 조인다. 빠지지 않는다.<br><br>당기면 더 조인다. 손목이 하얗게 된다. 일행이 칼로 막을 갈랐다. 갈린 데서 따뜻한 것이 흘렀다.<br>빠진 손목에 막이 팔찌처럼 남았다. 떼어 내는 데 살갗이 같이 왔다.`,
            win:{ exp:21, dream:3 },
            lose:{ hp:-37, mind:-20, spirit:-24 } },
          { l:'③ 막의 결을 읽어 덜 다니는 귀퉁이를 찾는다.', k:'gaze', dc:25, only:'gaze',
            ok:`막에는 결이 있다. 희고 말랑한 곳, 누렇고 바삭한 곳.<br><br>문 왼쪽 아래 귀퉁이가 누렇다. 오래전에 쳐 놓고 아무도 안 다닌 자리다. 거기만 막이 얇다.<br>칼로 그 귀퉁이를 오려 기어 들어갔다. 바스락 소리가 났다. 아무도 안 왔다.<br><br>안쪽에서 돌아보니 막의 문 한가운데 세로 틈이 천천히 벌어졌다 닫혔다. 저 문은 그것들이 쓰는 문이다.`,
            ng:`결을 읽다가 손이 막에 닿았다. 막이 떨린다. 한 군데를 건드리면 전체가 떨린다. 거미줄처럼.<br><br>둥지 안쪽에서 대답하듯 떨림이 돌아온다. 여기저기서.<br>칼로 아무 데나 찢고 들어갔다. 찢은 가장자리에 팔이 쓸렸다. 막이 닿은 데마다 부어올랐다.`,
            win:{ exp:22, dream:3, mind:9 },
            lose:{ hp:-36, mind:-21, spirit:-24 } }
        ] },

      { t:'둥지 — 명찰의 방',
        x:`막을 지나자 넓은 방이 나온다. 원래 무엇이었는지 모르겠다. 천장이 높다.<br><br>
          천장에서 고치가 매달려 있다. 수십. 다 사람만 하다. 바람도 없는데 아주 조금씩 흔들린다. 숨 때문이다.<br>
          고치마다 막 너머로 명찰이 비친다. 경비. 연구원. 조리원. 재실 인원판의 서른넷이 거의 여기 있다.<br><br>
          고치 사이로 길이 하나 나 있다. 고치 밑을 지나는 길이다.`,
        o:[
          { l:'① 고치 수를 세며 빈 고리를 찾아 지난다.', k:'sense', dc:26,
            doom:{ title:'빈 고리', what:'고치 사이로 끌려 올라갑니다', dc:20, sec:40,
              text:`걸으며 셌다. 고치 서른하나. 그 사이에 빈 고리가 몇 개 있다. 막이 새것이다. 아직 아무것도 안 걸렸다.<br><br>빈 고리 밑을 지날 때 고개를 들었다. 빈 고리가 왜 비었는지 보려고.<br>빈 고리 위에 무언가 매달려 있다. 고치가 아니다. 접힌 것이다. 걸 것을 기다리는 것이다.<br><br>마디가 내려온다. 들린 얼굴부터 감는다. 발이 바닥에서 떨어진다. 고치 사이로 끌려 올라간다. 새 막이 몸에 감기기 시작한다. 따뜻하다.`,
              dieText:`빈 고리는 빈 채로 두지 않는다.<br><br>명찰의 방에 고치가 서른둘이 됐다. 하나는 명찰이 없다.<br>막 너머로 비치는 것은 일행이 아는 옷이었다.` },
            ok:`걸으며 셌다. 고치 서른하나. 그 사이에 빈 고리가 몇 개. 막이 새것이다.<br><br>빈 고리 밑은 지나지 않았다. 고치가 걸린 데 밑으로만 걸었다. 걸린 데는 이미 걸린 데다.<br>빈 고리 위 어둠에서 무언가 마디를 접었다 폈다 했다. 기다리는 소리다. 지나가는 것을 세는 소리다.<br><br>방을 다 지나서 셈을 맞춰 봤다. 서른하나. 재실 인원판의 서른넷에서 셋이 모자란다. 셋은 아직 어디선가 걷고 있다.`,
            win:{ exp:23, dream:3 } },
          { l:'② 고치 사이를 몸을 비틀어 닿지 않게 지난다.', k:'evade', dc:25,
            ok:`고치 사이 길은 고치 밑을 지난다. 거기로 안 갔다. 고치와 고치 사이 빈 데를 골라 몸을 비틀었다.<br><br>고치에 닿으면 고치가 흔들린다. 흔들리면 옆 고치가 흔들린다. 다 흔들리면 무언가 온다.<br>어깨를 접고 허리를 틀고. 숨도 고치에 안 닿게 옆으로 뱉었다.<br><br>마지막 고치를 지나 돌아봤다. 하나도 안 흔들렸다. 대신 명찰 하나가 이쪽을 향해 돌아가 있다. 아까는 반대쪽이었다.`,
            ng:`몸을 비틀다가 팔꿈치가 고치에 닿았다. 고치가 흔들린다. 옆 고치가, 그 옆 고치가.<br><br>방 전체가 천천히 흔들린다. 천장 어둠에서 철컥 소리가 연달아 난다.<br>뛰었다. 고치에 부딪히며. 막이 얼굴에 감긴다. 방 끝에서 막을 뜯어내자 얼굴 살갗이 따라 일어났다.`,
            win:{ exp:22, dream:3 },
            lose:{ hp:-38, mind:-21, spirit:-25 } },
          { l:'③ 고치 밑에 떨어진 앞치마 주머니를 줍는다.', k:'luck', dc:25, only:'luck',
            ok:`고치 밑 바닥에 작은 주머니 하나가 떨어져 있다. 앞치마 주머니다. 조리원 고치 바로 밑.<br><br>일꾼들이 아직 못 주워 간 것이다. 고치 바로 밑은 일꾼들도 안 간다.<br>주머니 안에 꿀 봉지 둘. 일할 때 입이 심심하면 먹던 것이다. 그리고 쪽지. 오늘 저녁 넉넉히.<br><br>꿀 봉지를 챙겼다. 쪽지는 주머니에 다시 넣어 고치 밑에 두었다.`,
            ng:`주머니를 줍는 순간 위에서 고치가 움찔한다. 주머니 끈이 고치 막에 이어져 있었다.<br><br>당겨진 고치에서 째깍 소리가 시작된다. 빨라진다.<br>주머니를 놓고 물러섰다. 소리가 한참 빨라지다 늦춰졌다. 그사이 숨을 하나도 못 쉬어 머리가 깨질 듯 아팠다.`,
            win:{ exp:22, dream:4, item:'꿀 한 줌' },
            lose:{ mind:-22, spirit:-26 } }
        ] },

      { t:'둥지 — 아직 숨 쉬는 사람',
        x:`고치 하나가 다른 것들보다 낮게 걸렸다. 막이 얇다. 얼굴이 비친다.<br><br>
          눈을 뜨고 있다. 이쪽을 본다. 입술이 움직인다. 소리가 안 나온다. 막이 입을 덮고 있다.<br>
          막 아래쪽이 아직 젖어 있다. 걸린 지 얼마 안 됐다. 하루. 이틀.<br><br>
          목덜미 쪽 막이 불룩하다. 째깍 소리는 아직 안 난다.`,
        o:[
          { l:'① 입을 덮은 막을 갈라 숨을 틔운다.', k:'heal', dc:26,
            doom:{ title:'막 안쪽', what:'실이 손목으로 들어갔습니다', dc:20, sec:39,
              text:`칼끝으로 입을 덮은 막을 조금 갈랐다. 사람이 숨을 들이쉰다. 크게. 처음으로.<br><br>막을 더 벌리려고 손가락을 넣었다. 막 안쪽이 젖어 있다. 따뜻하다. 막 안쪽에도 실이 산다.<br>손가락이 간지럽다. 손가락 사이로, 손목 안쪽으로. 막 안의 실은 고치 안 사람보다 이쪽 손이 더 따뜻한 걸 안다.<br><br>고치 안의 사람이 고개를 젓는다. 늦었다는 얼굴이다. 손목에 붉은 줄이 그어진다.`,
              dieText:`고치 속 사람은 한 번 크게 숨을 쉬었다. 그걸로 됐다는 얼굴이었다.<br><br>숨을 틔워 준 손은 이틀 더 걸었다.<br>사흘째에 명찰의 방에 고치가 하나 늘었다. 낮게 걸렸다.` },
            ok:`장갑을 두 겹 끼고 칼끝으로 입을 덮은 막만 갈랐다. 손가락은 넣지 않았다.<br><br>사람이 숨을 들이쉰다. 크게. 그리고 속삭인다. 소리가 아주 작다.<br><span style="color:#d4af37;">"아래... 승강기... 그게 앞에 앉아 있어요. 배 밑... 껍데기 붙었던 자리."</span><br><br>그리고 눈을 감는다. 목덜미에서 째깍 소리가 시작된다. 칼을 그 사람 손 닿는 데 막 틈에 꽂아 두고 왔다.`,
            win:{ exp:23, dream:4 } },
          { l:'② 고치를 끊어 끌어내린다.', k:'bond', dc:26,
            doom:{ title:'마지막 줄', what:'고치째 천장으로 끌려 올라갑니다', dc:20, sec:39,
              text:`고치를 천장에 붙인 막을 끊었다. 고치가 기운다. 받았다. 무겁다. 사람 무게에 막 무게.<br><br>그때 고치를 붙들던 마지막 줄이 당겨진다. 천장 어둠에서. 줄은 끊긴 게 아니었다. 무언가 쥐고 있었다.<br>고치를 놓지 않았다. 놓을 수 없었다. 안에서 사람이 이쪽을 본다.<br><br>줄이 감긴다. 고치가 올라간다. 끌어안은 몸이 같이 들린다. 고치째 천장으로 끌려 올라간다. 고치 막이 팔에 감겨 붙는다.`,
              dieText:`둥지는 걸어 둔 것을 놓지 않는다. 같이 붙은 것도.<br><br>낮게 걸렸던 고치가 다시 걸렸다. 이번엔 조금 더 크다.<br>막 너머로 비치는 얼굴이 둘이었다.` },
            ok:`고치를 끊기 전에 위를 봤다. 고치를 붙든 마지막 줄이 천장 어둠으로 들어간다. 무언가 쥐고 있다.<br><br>줄은 건드리지 않았다. 고치 아래쪽만 갈라 사람의 팔을 빼냈다. 사람이 이쪽 손을 쥔다. 뜨겁다.<br>그 손이 이쪽 손바닥에 무언가를 쥐여 준다. 열쇠다. 꼬리표에 격납고 예비 전원.<br><br>그리고 손을 뺐다. 고치 안으로 도로 넣었다. 고개를 젓는다. 가라는 뜻이다. 갔다.`,
            win:{ exp:23, dream:3 } },
          { l:'③ 막 너머로 손을 맞대고 곁에 있어 준다.', k:'bond', dc:25, only:'bond',
            ok:`막 너머 그 사람 손바닥 자리에 이쪽 손바닥을 댔다. 따뜻하다. 막 한 장 사이다.<br><br>그 사람 손가락이 움직인다. 막 너머로 이쪽 손바닥을 두드린다. 똑. 똑. 두 번. 세 번이 아니다. 사람 박자다.<br>한참 그렇게 있었다. 째깍 소리가 날 때까지. 소리가 나자 그 사람이 먼저 손을 뗐다.<br><br>일어서며 그 사람 명찰을 읽었다. 이름을 외웠다. 나가서 말할 이름이 하나 생겼다.`,
            ng:`손을 맞대는데 막 너머 손이 이쪽 손을 민다. 세게. 가라는 것이다.<br><br>안 갔다. 막이 손바닥에 붙는다. 떼려니 안 떨어진다. 손바닥 살갗째 떼었다.<br>그 사람이 눈을 감았다. 화난 얼굴이었다. 이쪽 때문에. 그게 오래 남았다.`,
            win:{ exp:23, dream:4, spirit:10 },
            lose:{ hp:-36, mind:-22, spirit:-27 } }
        ] },

      { t:'둥지 — 일꾼의 길',
        x:`둥지 바닥에 홈이 파였다. 일꾼들이 오가며 판 길이다. 반들반들하다.<br><br>
          일꾼들이 줄지어 지나간다. 이번엔 막을 지고 있지 않다. 무엇을 하나씩 끌고 간다. 신발. 손전등. 가방.<br>
          떨어진 물건을 모은다. 모아서 어디론가 가져간다. 사람이 남긴 것은 무엇이든.<br><br>
          일행의 가방끈이 홈 쪽으로 늘어져 있다.`,
        o:[
          { l:'① 길 가에 그대로 서서 줄이 지나가길 기다린다.', k:'steady', dc:26,
            doom:{ title:'흘린 것', what:'일꾼 떼에 실려 갑니다', dc:20, sec:39,
              text:`길 가에 섰다. 움직이지 않았다. 일꾼들이 다리 옆을 지나간다. 신발, 손전등, 가방.<br><br>가방끈 하나가 홈에 떨어져 있다. 이쪽 것이다. 언제 풀렸는지 모른다. 일꾼 하나가 끈을 문다. 당긴다. 끈 끝이 이쪽 어깨에 걸려 있다.<br>사람이 흘린 것에 사람이 붙어 있다. 일꾼은 그 둘을 나누지 않는다.<br><br>둘째가 문다. 열째가 문다. 끈째 몸이 홈으로 쓰러진다. 다리 많은 것들이 밑으로 파고든다. 몸이 들린다. 일꾼 떼에 실려 간다.`,
              dieText:`일꾼은 흘린 것을 모은다. 모아서 어미에게 가져간다.<br><br>일꾼의 길은 반들반들하다. 많은 것이 그 위로 실려 갔다.<br>홈 안에 가방끈이 하나 남았다. 다음 일꾼이 그것도 물어 갔다.` },
            ok:`길 가에 서기 전에 가방끈을 다 묶었다. 신발 끈도. 흘릴 것이 없게.<br><br>일꾼들이 다리 옆을 지나간다. 이쪽을 한 번씩 더듬는다. 흘린 게 있는지. 없다. 지나간다.<br>줄이 다 지나갈 때까지 섰다. 마지막 일꾼이 이쪽 신발을 오래 더듬었다. 끈이 단단하다. 그것이 갔다.<br><br>홈을 건너며 봤다. 줄은 모두 한쪽으로 간다. 아래로. 격납고 쪽으로. 거기서 무언가 받는다.`,
            win:{ exp:23, dream:3 } },
          { l:'② 가방을 미끼로 홈에 던지고 그 틈에 건너뛴다.', k:'hide', dc:25,
            ok:`가방 하나를 비워 홈 한가운데에 던졌다. 일꾼들이 몰려간다. 다 같이 문다. 다 같이 들고 간다.<br><br>줄이 가방 쪽으로 쏠린 사이 홈 건너편으로 뛰었다. 하나씩.<br>가방은 금방 사라졌다. 일꾼들이 다시 줄을 섰다. 아무도 이쪽을 안 본다. 흘린 것이 없는 쪽은 안 본다.<br><br>가방에 든 건 막 조각과 돌멩이였다. 돌멩이는 아래층 어딘가에 쌓일 것이다. 사람이 흘린 것 사이에.`,
            ng:`던진 가방이 홈 가장자리에 걸렸다. 일꾼들이 몰려오는 쪽이 이쪽 발밑이다.<br><br>뛰었다. 일꾼 하나가 발목을 물었다. 놓지 않는다. 끌린다. 주먹으로 쳐서 떼었다.<br>발목에 둥근 이빨 자국. 깊다. 피가 홈으로 떨어졌다. 다음 일꾼이 그 자리를 오래 더듬었다.`,
            win:{ exp:22, dream:3 },
            lose:{ hp:-39, spirit:-25 } }
        ] },

      { t:'둥지 — 맑은 웅덩이',
        x:`길이 웅덩이에서 끊겼다. 웅덩이가 맑다. 너무 맑다. 바닥이 안 보인다. 바닥이 없어서다.<br><br>
          맑은 피가 고인 것이다. 둥지 전체에서 흘러내려 여기 모였다. 둘레 막이 하얗게 김을 낸다. 식초 냄새가 눈을 찌른다.<br>
          웅덩이 가운데에 쇠 계단 난간이 반쯤 녹아 솟아 있다. 원래 계단이 있던 자리다.<br><br>
          건너편까지 다섯 걸음. 웅덩이 둘레로 쓰러진 쇠 선반 몇 개가 걸쳐 있다.`,
        o:[
          { l:'① 녹다 만 난간을 디딤돌 삼아 뛰어 건넌다.', k:'evade', dc:26,
            doom:{ title:'바닥 없는 웅덩이', what:'맑은 웅덩이 속으로 가라앉습니다', dc:20, sec:38,
              text:`난간 끝을 향해 뛰었다. 발이 닿았다. 쇠가 물렁하다. 겉만 남았다.<br><br>난간이 무너진다. 몸이 웅덩이로 기운다. 손을 뻗었다. 건너편 막 가장자리가 손끝에 닿는다. 막이 찢어진다.<br>웅덩이는 물보다 무겁다. 빠진 다리가 끌려 들어간다. 바닥이 없다. 무거운 것이 무거운 쪽으로 간다.<br><br>차갑다. 그다음 뜨겁다. 일행이 손을 뻗는다. 손이 웅덩이 위에서 멈칫한다. 몸이 맑은 웅덩이 속으로 가라앉는다.`,
              dieText:`맑은 피는 고이면 맑아진다. 바닥이 없으면 끝까지 보인다.<br><br>웅덩이 표면이 한참 김을 냈다. 그러다 잔잔해졌다.<br>웅덩이 가운데에 녹다 만 난간이 하나 더 솟아 있었다. 아니다. 난간이 아니었다.` },
            ok:`난간 끝에 발을 대기 전에 쇠막대로 쳐 봤다. 물렁하다. 겉만 남았다.<br><br>난간 밑동, 웅덩이에 잠긴 데 바로 위만 아직 단단하다. 녹는 건 위에서부터다. 김이 위로 오르니까.<br>밑동을 디뎌 한 번에 건넜다. 발밑에서 쇠가 운다. 건넜다.<br><br>일행도 같은 데를 디뎠다. 마지막 사람이 디딜 때 밑동이 휘었다. 그래도 건넜다. 신발 밑창이 반쯤 녹았다.`,
            win:{ exp:23, dream:3 } },
          { l:'② 쓰러진 선반 판을 이어 걸치고 건넌다.', k:'fix', dc:25,
            ok:`쓰러진 쇠 선반 셋을 끌어왔다. 다리 쪽은 녹았고 판은 성하다.<br><br>판을 웅덩이 위로 하나씩 밀어 걸쳤다. 하나가 다음 것을 받친다. 다섯 걸음에 셋이면 된다.<br>판 위를 한 사람씩 건넜다. 판 밑에서 김이 오른다. 판이 조금씩 휜다. 휘는 속도보다 빨리 건넜다.<br><br>마지막 사람이 건너자 가운데 판이 웅덩이로 꺾여 들어갔다. 소리도 없이. 판 하나가 한참 동안 천천히 사라졌다.`,
            ng:`판을 걸쳤는데 가운데 판이 짧다. 한 뼘 모자란다. 그 한 뼘을 뛰었다.<br><br>착지한 판 끝이 휘청인다. 한쪽 발이 웅덩이 가장자리를 스쳤다. 신발이 녹고 발등이 탔다.<br>건너편에서 신발을 벗었다. 발등에 동전만 한 구멍이 셋. 신발은 버렸다.`,
            win:{ exp:22, dream:3 },
            lose:{ hp:-40, mind:-22 } },
          { l:'③ 무력으로 다친 동료를 업고 마른 막만 골라 건넌다.', k:'steady', dc:25, cost:{ might:35 },
            doom:{ title:'둘의 무게', what:'업은 채 웅덩이로 가라앉습니다', dc:20, sec:38,
              text:`가장 많이 다친 사람을 업었다. 무력을 다리에 실었다. 웅덩이 가장자리 단단한 막을 골라 디뎠다.<br><br>둘의 무게는 하나의 무게가 아니다. 셋째 디딤에서 막이 꺼진다. 무릎까지 빠졌다.<br>등에 업힌 사람이 내리려 한다. 꽉 잡았다. 놓지 않았다. 둘이 같이 기운다.<br><br>웅덩이가 무거운 쪽을 당긴다. 무릎, 허리. 등의 사람을 건너편으로 밀어 던졌다. 이쪽은 업은 자세 그대로 웅덩이로 가라앉는다.`,
              dieText:`업은 쪽은 끝까지 등을 펴지 않았다.<br><br>밀려 던져진 사람은 건너편 막 위에 떨어졌다. 무사했다.<br>그 사람은 그 뒤로 한동안 누구의 등에도 업히지 않았다.` },
            ok:`가장 많이 다친 사람을 업었다. 무력을 다리에 실었다. 웅덩이 가장자리 막 중에 누렇고 마른 데만 골라 디뎠다.<br><br>셋째 디딤에서 막이 출렁였다. 멈추지 않았다. 멈추면 꺼진다. 무게는 지나가는 동안만 견딘다.<br>다섯째 디딤에서 건너편 바닥을 밟았다. 업힌 사람을 내려놓았다. 다리가 후들거린다. 무력이 바닥났다.<br><br>업혔던 사람이 아무 말 없이 이쪽 신발 끈을 다시 묶어 주었다. 녹아서 끊어져 있었다.`,
            win:{ exp:24, dream:4 } }
        ] },

      { t:'둥지 — 유리알',
        x:`웅덩이 너머는 낮은 방이다. 바닥에 냉각수가 발목까지 고였다. 차갑다. 둥지에서 처음 만나는 찬 것이다.<br><br>
          물속에 알이 깔려 있다. 유리구슬만 하다. 투명하다. 수천 개.<br>
          알 하나하나 안에 무언가 접혀 있다. 자처럼. 손톱만 한 것이 마디마디 접혀 잔다.<br><br>
          찬물이 알을 재운다. 이 물이 데워지면 수천이 한꺼번에 펴진다.`,
        o:[
          { l:'① 알 사이 빈 바닥을 골라 디디며 지난다.', k:'luck', dc:26,
            doom:{ title:'알 지키는 것', what:'냉각수 밑으로 끌려 가라앉습니다', dc:20, sec:38,
              text:`알 사이 빈 바닥을 골라 디뎠다. 냉각수가 발목을 덮는다. 차다. 반갑게 차다.<br><br>세 걸음째에 발밑이 물렁하다. 바닥이 아니다. 매끈하고 길다. 등이다. 물 밑에 펴진 채 누운 것이 있다. 알을 지키는 것이다.<br>그것이 몸을 뒤집는다. 물이 출렁인다. 알들이 굴러간다. 마디가 발목을 감는다.<br><br>찬물 속으로 넘어진다. 발목 깊이인데 몸이 다 잠긴다. 바닥이 한쪽으로 깊다. 물 밑의 것이 그 깊은 데로 끌고 간다. 냉각수 밑으로 끌려 가라앉는다. 알들이 얼굴 옆을 굴러간다.`,
              dieText:`찬물은 알을 재운다. 지키는 것은 안 잔다.<br><br>냉각수 표면이 잔잔해지자 알들이 제자리로 굴러 돌아왔다.<br>물이 아주 조금 따뜻해졌다. 알 몇 개 속의 마디가 한 칸씩 펴졌다.` },
            ok:`알 사이를 디디기 전에 물 위를 오래 봤다. 물결이 한쪽에서만 인다. 바람도 없는데.<br><br>물 밑에 길게 누운 것이 있다. 등이 수면 바로 밑을 지난다. 그것이 지나간 자리에 알이 없다. 알을 피해서 다닌다.<br>그것이 반대편 끝으로 갈 때를 기다렸다. 그리고 알이 빼곡한 데만 골라 발끝으로 디뎠다. 알이 많은 데는 그것도 안 온다.<br><br>건너편에 닿았다. 물 밑의 것이 천천히 돌아왔다. 이쪽이 디딘 자리를 하나씩 지나갔다.`,
            win:{ exp:24, dream:3 } },
          { l:'② 알 속에 접힌 것을 들여다본다.', k:'gaze', dc:25,
            ok:`쭈그려 앉아 알 하나를 들여다봤다. 투명하다. 안의 것이 손톱만 하다.<br><br>접혀 있다. 마디가 열넷. 한쪽으로만 접힌다. 접힌 끝이 판 아래 솔기 밑으로 모인다. 펴질 때 거기가 맨 마지막에 펴진다. 거기가 제일 늦다.<br>큰 것도 그럴 것이다. 다 펴지기 전, 솔기 밑이 열리기 전. 그때가 틈이다.<br><br>일어서는데 그 알 속 판이 아주 조금 이쪽으로 돌아가 있었다. 잠결에.`,
            ng:`들여다보는 사이 숨이 알에 닿았다. 따뜻한 숨이.<br><br>알 속 마디가 한 칸 펴진다. 두 칸. 알이 갈라진다. 손톱만 한 것이 물 위로 튀어 손등에 붙는다. 작다. 그래도 맑은 피는 맑은 피다.<br>떼어 냈다. 손등이 패었다. 주변 알들이 하나씩 금이 가는 소리가 났다. 뛰었다.`,
            win:{ exp:23, dream:3, mind:9 },
            lose:{ hp:-38, mind:-22, spirit:-25 } },
          { l:'③ 마력으로 냉각수를 얼려 알을 가둔다.', k:'fix', dc:25, cost:{ mana:35 },
            ok:`물에 손을 담그고 찬 기운을 밀어 넣었다. 물이 하얗게 언다. 알들이 얼음 속에 갇힌다.<br><br>얼음 위로 건넜다. 발밑 얼음 속에 수천 개의 알. 그 하나하나 안에 접힌 것. 다 잔다.<br>얼음 밑에서 무언가 크게 돌아눕는 소리가 났다. 둔하다. 얼음에 막혀 올라오지 못한다.<br><br>건너편에서 손을 뺐다. 손이 얼음에 붙어 살갗이 남았다. 얼음은 한동안 안 녹을 것이다. 그 밑의 것도 한동안.`,
            ng:`얼리는데 물 밑의 것이 먼저 움직인다. 찬 기운을 안다. 얼기 전에 깨뜨린다.<br><br>반쯤 언 얼음이 밑에서 깨진다. 얼음 조각과 알들이 튄다. 얼음 위에 있던 다리가 물에 빠졌다.<br>끌어냈다. 정강이에 마디 끝 자국이 길게 났다. 깨진 얼음 사이로 알들이 굴러 다시 모였다.`,
            win:{ exp:24, dream:3 },
            lose:{ hp:-39, mind:-21, spirit:-26 } }
        ] },

      { t:'둥지 — 접이들의 잠자리',
        x:`둥지 끝 방 천장이 높다. 천장에 3형들이 매달려 있다. 접힌 채로. 박쥐처럼. 셀 수 없다.<br><br>
          자는 중이다. 얼굴판 솔기가 다 닫혀 있다. 숨 쉴 때마다 마디가 하나씩 덜컥한다.<br>
          바닥에 마른 막과 사람이 남긴 물건이 깔려 있다. 밟으면 바스락거린다.<br><br>
          방 건너편에 아래층 계단이 있다. 8층. 0호 격납고.`,
        o:[
          { l:'① 불을 끄고 살금살금 가로지른다.', k:'hide', dc:26,
            doom:{ title:'깨는 덜컥', what:'천장으로 끌려 올라갑니다', dc:20, sec:37,
              text:`불을 끄고 걸었다. 발끝으로. 바닥의 마른 막을 피하며. 피할 수가 없다. 바닥이 다 막이다.<br><br>바스락. 작은 소리다. 천장에서 마디 하나가 덜컥 한다. 숨 쉬는 덜컥이 아니다. 깨는 덜컥이다.<br>하나가 깨면 옆이 깬다. 옆이 깨면 그 옆이. 천장 전체에서 철컥 소리가 물결처럼 번진다.<br><br>머리 위에서 마디가 내려온다. 셋, 넷. 어깨, 허리, 발목. 몸이 들린다. 천장으로 끌려 올라간다. 위에서 보니 바닥이 하얗다. 막이 다 하얗다.`,
              dieText:`접이들의 잠자리에서 잠이 깬 것은 하나다. 나머지는 곧 다시 잤다.<br><br>천장에 매달린 것이 하나 늘었다. 접히지 않은 채로.<br>바닥의 마른 막 위에 신발 한 짝이 떨어졌다. 아무도 줍지 않았다. 일꾼도.` },
            ok:`불을 끄고 걸었다. 바닥의 마른 막을 피할 수가 없다. 그래서 피하지 않았다. 대신 박자를 맞췄다.<br><br>천장의 것들이 숨 쉴 때마다 마디가 덜컥 한다. 수백 개가 한꺼번에. 그 덜컥 소리에 맞춰 한 걸음.<br>바스락은 덜컥 속에 묻힌다. 방 한가운데에서 한 번 박자를 놓쳤다. 다음 덜컥까지 숨을 참고 서 있었다.<br><br>계단 문을 열 때 덜컥에 맞췄다. 닫을 때도. 문 너머에서 숨을 쉬었다. 다들 다리가 풀렸다.`,
            win:{ exp:24, dream:4 } },
          { l:'② 바닥 물건을 발등으로 밀어 길을 내며 천천히 간다.', k:'sense', dc:25,
            ok:`발 앞의 마른 막과 물건을 발등으로 살살 밀며 걸었다. 밟지 않고 밀었다. 미는 소리는 밟는 소리보다 작다.<br><br>밀린 물건 중에 사진이 든 지갑이 있었다. 손목시계가 있었다. 시계는 아직 간다. 째깍. 고치 소리와 같다.<br>시계는 주워 주머니에 넣었다. 째깍 소리는 이 방에서 이상한 소리가 아니다. 오히려 덮어 준다.<br><br>계단 앞에 닿았다. 등 뒤 천장은 그대로 잔다. 주머니 속 시계가 째깍거렸다. 아래로 갈수록 크게 들렸다.`,
            ng:`밀던 물건 하나가 굴렀다. 깡통이다. 구르는 소리가 길다. 아주 길다.<br><br>천장에서 마디 몇 개가 펴진다. 내려오지는 않는다. 듣는다. 다들 그 자리에 굳었다.<br>한참 뒤 펴졌던 마디들이 하나씩 접혔다. 그동안 숨을 못 쉬어 한 사람이 쓰러졌다. 쓰러지는 몸을 다들 팔로 받았다. 받은 팔이 다 멍들었다.`,
            win:{ exp:23, dream:3 },
            lose:{ hp:-41, mind:-23, spirit:-27 } }
        ] }
    ] },

    // ───────── 8층 ─────────
    { name:'8층 — 0호 격납고', scenes:[

      { t:'격납고 — 벗은 껍데기',
        x:`계단이 끝났다. 격납고는 넓다. 천장 등이 반쯤 나가 끝이 안 보인다.<br><br>
          가운데에 0호가 있다. 검은 돌. 기록대로 냉장고만 하다. 다만 쪼개져 있다. 알처럼. 안이 비었다.<br>
          0호 옆으로 벗은 껍질이 줄지어 놓여 있다. 첫째는 개만 하다. 둘째는 사람만 하다. 줄은 어둠 속으로 이어진다. 갈수록 크다.<br><br>
          어둠 저쪽에서 똑. 똑. 쇠를 치는 소리가 난다. 느리다. 급할 것 없다는 박자다.`,
        o:[
          { l:'① 쪼개진 0호 안쪽을 들여다본다.', k:'gaze', dc:25,
            ok:`껍데기 안쪽에 웅크렸던 자국이 남아 있다. 몸이 닿았던 데가 다 반들반들하다.<br><br>한 군데만 다르다. 배가 닿았던 자리. 껍데기가 살에 붙어 있던 자리다. 뜯겨 나간 결이 보인다. 벗은 게 아니라 뜯은 것이다.<br>벗을 때마다 거기가 같이 뜯긴다. 거기만 늦게 굳는다.<br><br>7층 고치 속 사람 말이 맞다. 배 밑. 껍데기 붙었던 자리. 다들 그 말을 한 번씩 입속으로 외웠다.`,
            ng:`안쪽 바닥에 맑은 것이 한 줄 고여 있다. 물인 줄 알았다.<br><br>들여다보려고 짚은 손 밑에서 김이 올랐다. 장갑이 녹아 손바닥에 붙었다.<br>장갑을 벗는 데 살갗이 따라왔다. 식초 냄새가 코를 찔렀다.<br><br>0호는 석 달이 지나도 안이 마르지 않는다. 그걸 손으로 배웠다.`,
            win:{ exp:23, dream:4 },
            lose:{ hp:-38, mind:-20 } },
          { l:'② 벗은 껍질의 줄을 끝까지 세어 본다.', k:'sense', dc:24, only:'sense',
            ok:`껍질을 셌다. 다섯. 하나 벗을 때마다 갑절로 컸다.<br><br>다섯째 껍질은 승강기 철창보다 크다. 그 옆은 비어 있다. 여섯째 자리다.<br>다섯째를 만져 봤다. 안쪽이 아직 축축하다. 벗은 지 며칠 안 됐다.<br><br>석 달에 다섯. 그리고 지금 제일 새 몸이다. 새 몸은 무르다는 말을 아무도 입 밖에 못 냈다. 저 크기 앞에서는.`,
            ng:`셋째 껍질까지 세고 넷째로 가는데 발밑에서 바스락 소리가 났다.<br><br>바닥에 깔린 게 다 껍질 부스러기다. 밟을 때마다 운다. 어둠 저쪽의 똑. 똑. 소리가 멎었다.<br>다들 그 자리에 굳은 채로 한참 섰다. 소리는 한참 뒤에 다시 시작됐다. 조금 빨라져 있었다.`,
            win:{ exp:23, dream:3, mind:8 },
            lose:{ mind:-21, spirit:-24 } },
          { l:'③ 둘째 껍질 속에 보이는 가방을 꺼낸다.', k:'fix', dc:25,
            doom:{ title:'빌린 껍데기', what:'껍질 속으로 끌려 들어갑니다', dc:20, sec:37,
              text:`사람만 한 둘째 껍질 틈으로 가방끈이 비죽 나와 있다. 연구원 가방이다. 팔을 넣어 끈을 잡았다.<br><br>끈이 당겨지지 않는다. 안에서 누가 쥔 것처럼. 껍질 속이 따뜻하다. 빈 껍질은 따뜻할 이유가 없다.<br>껍질은 비어 있지 않았다. 접힌 것 하나가 남의 껍질을 빌려 자고 있었다.<br><br>마디가 팔을 감는다. 어깨까지. 몸이 틈으로 접혀 들어간다. 껍질 속으로 끌려 들어간다. 틈이 안에서 닫힌다.`,
              dieText:`벗은 껍질의 줄은 그대로였다. 다섯.<br><br>다만 둘째 껍질이 조금 불룩해졌다. 한동안 천천히 들썩였다.<br>가방끈은 다시 비죽 나와 있었다. 미끼는 원래 자리에 두는 법이다.` },
            ok:`끈을 잡기 전에 껍질에 손등을 대 봤다. 따뜻하다. 빈 껍질이 따뜻할 이유가 없다.<br><br>팔을 안 넣었다. 대신 쇠막대를 끈 고리에 걸어 멀찍이서 당겼다. 끈이 팽팽해지더니 안에서 마주 당긴다.<br>놓았다. 끈이 스르륵 안으로 끌려 들어갔다. 틈이 숨처럼 벌어졌다 닫혔다.<br><br>그 뒤로는 어떤 껍질에도 손을 안 댔다. 빈 것처럼 보이는 게 이 집의 법이다.`,
            win:{ exp:24, dream:3 } }
        ] },

      { t:'격납고 — 물건 무덤',
        x:`격납고 왼편에 더미가 있다. 산이다. 신발. 가방. 명찰. 안경. 전화기. 의자 다리까지.<br><br>
          사람 물건이면 무엇이든 있다. 서른넷의 것이라기엔 많다. 표본실 전체가 조금씩 이리로 옮겨지는 중이다.<br>
          일꾼들이 줄지어 와 꼭대기에 하나씩 내려놓고 돌아간다. 쌓는 게 아니다. 자리를 골라 놓는다.<br><br>
          더미 속에 손전등 하나가 켜진 채 묻혀 있다. 불빛이 물건 틈으로 숨처럼 깜박인다.`,
        o:[
          { l:'① 더미 기슭에서 쓸 만한 것을 찾는다.', k:'luck', dc:24,
            ok:`기슭에 매점 상자가 통째로 와 있다. 일꾼들이 상자째 날랐다.<br><br>안에 생수가 줄지어 있다. 병이 성하다. 라벨도 그대로다. 유통기한이 아직 남았다. 그게 이상하게 웃겼다.<br>병을 꺼내 나눠 멨다. 물은 무겁다. 무거운 게 오랜만에 반가웠다.<br><br>상자 밑에 영수증이 깔려 있었다. 떨어진 날 아침 것이다. 생수 서른네 병. 사람 수대로 샀던 물이다.`,
            ng:`기슭을 뒤지는데 손밑에서 명찰 무더기가 쏟아졌다.<br><br>명찰이 바닥에 좍 깔린다. 사진이 다 위를 본다. 서른 몇 개의 얼굴이 한꺼번에 이쪽을 본다.<br>아는 얼굴이 있었다. 7층에서 고치 막 너머로 본 얼굴이다.<br><br>명찰을 도로 쌓는 손이 오래 떨렸다. 일꾼 하나가 와서 그걸 다시 다 흐트러뜨렸다. 원래 자리가 있다는 듯이.`,
            win:{ exp:23, dream:3, item:'맑은 물' },
            lose:{ mind:-22, spirit:-25 } },
          { l:'② 더미를 가로질러 질러간다.', k:'evade', dc:25,
            doom:{ title:'더미 밑', what:'물건 더미 밑으로 끌려 들어갑니다', dc:20, sec:36,
              text:`더미 비탈을 탔다. 신발 더미는 밟아도 소리가 죽는다. 그래서 골랐다.<br><br>중턱에서 발이 꺼졌다. 무릎까지. 더미는 쌓인 게 아니라 떠 있다. 밑이 비었다.<br>빈 데로 일꾼들이 다닌다. 더미 속이 길이다. 꺼진 다리를 다리 열둘이 더듬는다.<br><br>물건들이 양옆에서 무너져 내린다. 몸이 가라앉는다. 신발과 가방과 명찰 사이로. 물건 더미 밑으로 끌려 들어간다. 위에서 불빛이 깜박인다. 묻힌 손전등이다. 점점 멀어진다.`,
              dieText:`더미가 한동안 들썩였다. 그러다 가라앉았다.<br><br>일꾼들이 평소보다 바빴다. 꼭대기에 새 물건이 하나씩 올라왔다. 신발. 가방. 손전등.<br>손전등은 켜진 채였다. 먼저 묻힌 것 옆에서 같이 깜박였다.` },
            ok:`비탈에 발을 올리기 전에 쇠막대로 중턱을 찔러 봤다. 막대가 쑥 들어간다. 밑이 비었다.<br><br>더미는 쌓인 게 아니라 떠 있다. 밑으로 일꾼들이 다닌다. 위를 걷는 건 지붕 위를 걷는 것이다.<br>질러가는 건 접었다. 기슭을 멀리 돌았다. 두 배 걸렸다.<br><br>도는 내내 더미가 숨 쉬듯 들썩였다. 밑에서 무언가 줄지어 지나가는 박자였다.`,
            win:{ exp:24, dream:3 } },
          { l:'③ 일꾼 줄 옆에 붙어 더미 그늘로 지난다.', k:'hide', dc:24, only:'hide',
            ok:`일꾼은 물건을 본다. 나르는 저들끼리는 안 본다. 그 줄 옆에 붙어 짐처럼 걸었다.<br><br>그늘을 반쯤 지났을 때 더미 꼭대기 위 어둠에서 긴 마디 하나가 내려왔다.<br>마디가 꼭대기 물건을 하나 집었다. 전화기였다. 들고 어둠으로 돌아갔다. 고르는 손이었다. 아무거나 집지 않았다.<br><br>어미는 더미에서 사람 물건을 골라 간다. 들여다보려고. 그 생각이 격납고보다 컸다. 다들 걸음이 빨라졌다.`,
            ng:`발밑에서 안경이 밟혔다. 바스락. 작은 소리다. 일꾼 줄이 일제히 멈췄다.<br><br>맨 뒤 일꾼이 돌아와 이쪽 발치를 더듬었다. 깨진 안경을 물고, 바짓단을 물고, 한참 당겼다.<br>바지를 찢어 주고서야 놓였다. 일꾼은 천 조각과 안경을 들고 줄로 돌아갔다.<br><br>둘 다 꼭대기에 올라갔다. 천 조각이 놓인 자리가 하필 잘 보이는 데였다.`,
            win:{ exp:23, dream:4 },
            lose:{ hp:-32, mind:-20 } }
        ] },

      { t:'격납고 — 예비 전원실',
        x:`오른쪽 벽에 작은 철문이 있다. 예비 전원. 7층 고치 속 사람이 준 열쇠가 꼭 맞았다.<br><br>
          안에 발전기와 축전지가 있다. 벽의 배선도에 승강기가 그려져 있다. 본전원 선은 붉은 줄로 지워졌다. 떨어진 날 나간 것이다.<br>
          승강기는 이 방 전기로만 움직인다.<br><br>
          발전기를 돌리면 소리가 난다. 격납고 전체에 들릴 소리다. 어둠 저쪽의 똑. 똑. 이 그 소리를 들을 것이다.`,
        o:[
          { l:'① 발전기 대신 축전지만 조용히 잇는다.', k:'fix', dc:25,
            ok:`발전기는 안 건드렸다. 축전지 단자를 하나씩 제어반에 이었다. 스파크가 튀지 않게 마른 천을 감고.<br><br>제어반에 불이 들어온다. 바늘이 반쯤 찬 데서 멎는다.<br>철창을 한 번 내리고 한 번 올릴 만큼이다. 꼭 한 번씩이다.<br><br>표시등을 천으로 덮었다. 불빛이 켜지면 사람이 온다는 걸 아는 것들이 사는 집이다. 불빛은 숨기는 것이다.`,
            ng:`마지막 단자에서 스파크가 튀었다. 파랗게. 탁 소리와 탄내.<br><br>손끝이 까맣게 눌었다. 제어반 불은 들어왔다. 바늘도 섰다.<br>다만 격납고 쪽에서 똑. 똑. 소리가 멎어 있었다. 한참을.<br><br>문틈으로 내다봤다. 어둠뿐이었다. 소리가 다시 시작될 때까지가 제일 길었다.`,
            win:{ exp:24, dream:3 },
            lose:{ hp:-28, mind:-20 } },
          { l:'② 굳은 연료 밸브를 정확히 한 번 쳐서 연다.', k:'break', dc:24, only:'break',
            ok:`축전지가 못 미더울 때를 대비해 발전기도 살려 두기로 했다. 연료 밸브가 삭아 굳었다.<br><br>돌려서 열릴 쇠가 아니다. 치면 열린다. 다만 한 번에 열어야 한다. 한 번은 사고 소리고 두 번부터는 신호다. 이 집에서 배운 것이다.<br>밸브 어깨, 녹이 갈라진 금에 정을 대고 망치를 한 번 떨어뜨렸다. 밸브가 반 바퀴 돌았다. 기름이 관으로 흘러내리는 소리가 났다.<br><br>격납고는 조용했다. 한 번은 그냥 지나간다. 다들 두 번째를 안 만들려고 연장을 다 내려놨다.`,
            ng:`첫 타가 빗맞았다. 녹만 떨어졌다. 이를 물고 한 번 더 쳤다.<br><br>두 번. 벽 너머 격납고에서 대답이 왔다. 똑. 똑. 두 번.<br>묻는 박자였다. 다들 전원실 바닥에 엎드려 숨을 죽였다. 철문 밖에서 무언가 문을 한 번 더듬고 갔다.<br><br>밸브는 열렸다. 연 값을 치른 셈이다. 얼마짜리인지는 아직 모른다.`,
            win:{ exp:23, dream:3 },
            lose:{ mind:-22, spirit:-26 } },
          { l:'③ 내공으로 발전기 몸통의 떨림을 눌러 소리를 죽인다.', k:'steady', dc:24, cost:{ qi:30 },
            ok:`발전기에 시동을 걸며 몸통에 두 손을 붙였다. 내공을 판판하게 펴서 떨림을 눌렀다.<br><br>털털거릴 소리가 손바닥 안에서 웅웅거림으로 뭉개진다. 떨림이 뼈로 올라온다. 이가 시리다.<br>바늘이 끝까지 찼다. 손을 떼자 발전기를 껐다. 전기는 축전지에 옮겨 담겼다.<br><br>손바닥에 발전기 무늬가 벌겋게 찍혀 있었다. 한동안 주먹이 안 쥐어졌다. 그래도 격납고는 조용했다.`,
            ng:`떨림이 손을 이겼다. 발전기가 한 번 크게 털컥였다. 쇳소리가 철문을 넘어갔다.<br><br>바로 시동을 껐다. 늦었다. 격납고에서 똑. 똑. 소리가 이쪽 벽으로 옮겨 왔다.<br>벽에 붙어 선 채로 들었다. 벽 너머에서 큰 것이 숨 쉬는 소리를. 숨이 길었다. 벽이 미지근했다.<br><br>그것이 돌아간 뒤에도 한참 아무도 벽에서 안 떨어졌다.`,
            win:{ exp:24, dream:3 },
            lose:{ hp:-30, mind:-21, spirit:-24 } }
        ] },

      { t:'격납고 — 냉각 배관',
        x:`천장을 따라 굵은 배관이 지나간다. 위층 유리알 방의 냉각수가 도는 관이다. 겉에 성에가 꼈다.<br><br>
          배관이 격납고 바닥 쪽으로 내려오는 데에 밸브가 넷 달려 있다. 비상 방출. 손잡이가 다 얼어붙었다.<br>
          경비 일지의 연필 글씨를 다들 기억하고 있다. 놈들은 따뜻한 쪽으로 간다. 추우면 느리다.<br><br>
          이 물을 바닥에 깔면 격납고가 통째로 차가워진다.`,
        o:[
          { l:'① 얼어붙은 밸브 넷을 차례로 깨워 연다.', k:'break', dc:25,
            ok:`손잡이는 돌리는 게 아니라 깨우는 것이다. 얼음이 문 데를 정확히 쳐서 금을 내고, 그다음 돌렸다.<br><br>하나. 둘. 셋. 넷. 배관 아가리에서 찬 안개가 쏟아져 바닥으로 깔린다. 무릎 높이로. 바닥이 하얗게 운다.<br>격납고 공기가 금세 서늘해졌다. 숨이 하얗게 보이기 시작했다.<br><br>어둠 저쪽의 똑. 똑. 이 눈에 띄게 느려졌다. 똑. ……똑. 급할 것 없던 박자가 급할 수 없는 박자가 됐다.`,
            ng:`셋째 밸브가 손잡이째 부러졌다. 삭은 쇠가 얼음 속에서 버티질 못했다.<br><br>부러진 관에서 냉각수가 통째로 쏟아졌다. 피할 새 없이 뒤집어썼다. 얼음물이다.<br>숨이 턱 막혔다. 젖은 옷이 그대로 뻣뻣해진다. 이가 딱딱 부딪히는 소리가 제일 큰 소리였다.<br><br>바닥엔 안개가 깔렸다. 깔긴 깔았다. 몸값으로.`,
            win:{ exp:24, dream:3 },
            lose:{ hp:-39, spirit:-24 } },
          { l:'② 배관을 타고 올라가 막힌 윗밸브를 연다.', k:'evade', dc:26,
            doom:{ title:'다섯째 배관', what:'천장 배관 위로 끌려 올라갑니다', dc:20, sec:36,
              text:`벽의 거치대를 밟고 배관 위로 올라섰다. 성에 낀 관을 안고 윗밸브까지 기었다.<br><br>안은 관이 숨을 쉰다. 들숨에 굵어지고 날숨에 가늘어진다. 냉각관은 숨을 쉬지 않는다.<br>배관은 넷이라고 했다. 안고 있는 것까지 다섯이다.<br><br>성에인 줄 알았던 흰 것이 얼굴판 솔기를 연다. 마디가 펴지며 몸을 감는다. 관을 안은 자세 그대로 천장 배관 위로 끌려 올라간다. 아래에서 안개가 쏟아지기 시작한다. 하얗고, 멀다.`,
              dieText:`밸브는 결국 아래에서 열었다. 안개가 격납고에 깔렸다.<br><br>천장 배관은 넷이었다. 세어 보면 늘 넷이었다.<br>다만 넷 중 어느 것이 어제의 넷째인지 아무도 자신 있게 말하지 못했다.` },
            ok:`올라가기 전에 버릇대로 셌다. 배선도에는 배관이 넷. 천장에는 다섯.<br><br>다섯째는 성에가 안 꼈다. 성에 대신 희고 마른 막이 입혀져 있다. 숨 쉬듯 굵기가 변한다.<br>그쪽은 안 탔다. 제일 먼 넷째 관을 골라 윗밸브를 열고 바로 내려왔다.<br><br>내려와서 보니 다섯째 관이 조금 자리를 옮겨 있었다. 배관은 자리를 옮기지 않는다. 다들 그 밑으로는 안 다녔다.`,
            win:{ exp:24, dream:4 } },
          { l:'③ 제일 찬 물줄기 밑에 제가 서서 판을 받친다.', k:'steady', dc:24, only:'steady',
            ok:`방출구 바로 밑은 물벼락이다. 안개가 되기 전의 날 냉각수가 쏟아진다. 거기 누가 서서 철판을 받치면 물이 판을 타고 넓게 퍼진다.<br><br>제가 섰다. 판을 어깨에 얹고. 얼음물이 판을 때리고 어깨를 때린다. 숨을 작게 쪼개 쉬며 버텼다.<br>물이 판을 타고 부챗살로 퍼졌다. 안개가 격납고 끝까지 고르게 깔렸다.<br><br>판을 내려놓자 어깨가 남의 것 같았다. 일행이 마른 옷을 벗어 둘러 줬다. 안개 저쪽에서 똑. ……똑. 소리가 아주 느려져 있었다.`,
            ng:`판이 물벼락에 밀렸다. 버티는 다리가 얼음 바닥에서 미끄러졌다.<br><br>판째 넘어지며 냉각수를 정통으로 받았다. 귀가 멍하고 손발 감각이 없다.<br>일행이 끌어냈을 때 입술이 파랬다. 한참 주물러서야 말이 나왔다.<br><br>안개는 고르게 깔리지 못했다. 격납고 가운데가 듬성하다. 저 듬성한 데를 지나가야 한다.`,
            win:{ exp:24, dream:3, spirit:10 },
            lose:{ hp:-41, spirit:-25 } }
        ] },

      { t:'격납고 — 어미',
        x:`격납고 끝. 벽에 지상 승강기의 철창 통로가 붙어 있다. 통로에 비상등이 하나 켜져 있다.<br><br>
          그 앞에 그것이 앉아 있다. 접힌 채로. 접히고도 버스만 하다. 벗은 껍질 다섯 개 치의 몸이다.<br>
          배를 바닥에 붙이고 얼굴판 솔기를 닫은 채, 앞마디 사이에 손전등을 쥐고 있다. 켠다. 끈다. 켠다. 끈다. 똑. 똑. 그 소리였다.<br><br>
          7층 사람 말 그대로다. 그게 앞에 앉아 있어요. 승강기 앞에. 사람이 어디로 가고 싶어 하는지 아는 자리에.`,
        o:[
          { l:'① 숨의 박자와 배 밑을 끝까지 살핀다.', k:'gaze', dc:26,
            ok:`안개 너머로 오래 봤다. 숨을 쉴 때마다 몸이 아주 조금 뜬다. 들숨 끝에 제일 높이.<br><br>그때 배 밑이 보인다. 허옇고 매끈한 자리. 손바닥 둘 크기. 껍데기가 붙어 있다 뜯긴 자리다. 거기만 판이 없다.<br>숨은 느리다. 안개 덕이다. 들숨 끝에서 다음 날숨까지가 길다. 그 사이가 틈이다.<br><br>눈을 떼는데 어미가 손전등을 껐다. 그리고 켜지 않았다. 보는 동안은 세지 않는 모양이다. 이쪽 말이 아니라 저쪽 말로.`,
            win:{ exp:24, dream:4 },
            ng:`보는 데 정신이 팔려 안개가 얕아진 걸 몰랐다. 무릎 밑이 허전하다.<br><br>어미의 얼굴판이 이쪽으로 아주 천천히 돌았다. 솔기는 닫힌 채다. 눈은 없다. 그래도 돈다.<br>안개가 다시 차오를 때까지 아무도 숨을 제대로 못 쉬었다. 얼굴판은 제자리로 돌아갔다.<br><br>본 것은 건졌다. 배 밑, 허연 자리. 값은 이쪽 심장이 치렀다.`,
            lose:{ mind:-23, spirit:-27 } },
          { l:'② 벽을 따라 철창까지의 거리를 재러 간다.', k:'hide', dc:26,
            doom:{ title:'바닥으로 듣는 것', what:'어미 앞으로 끌려갑니다', dc:20, sec:35,
              text:`벽에 붙어 안개 속을 걸었다. 발꿈치를 들고. 소리는 안 났다. 확실히 안 났다.<br><br>어미의 손전등이 꺼졌다. 켜지지 않는다. 격납고가 조용하다. 바닥이 조용하지 않다는 걸 그때 알았다. 걸음은 바닥으로 내려간다. 어미는 바닥으로 듣는다.<br>앞마디가 안개를 갈랐다. 소리도 없이. 허리에 마디가 감긴다. 차고 단단하다.<br><br>몸이 들린다. 안개 위로. 어미 앞으로 끌려간다. 얼굴판 솔기가 코앞에서 천천히 벌어진다. 안에서 나오는 숨이 따뜻하다. 이 집에서 제일 따뜻하다.`,
              dieText:`어미는 새로 온 것을 오래 들여다봤다. 손전등을 들듯이 들고. 이리 돌리고. 저리 돌리고.<br><br>그리고 둥지 쪽으로 올려 보냈다. 일꾼들이 줄을 비켰다.<br>승강기 앞자리로 돌아간 어미가 손전등을 다시 켰다. 끄고. 켜고. 세던 것을 마저 셌다.` },
            ok:`벽에 붙기 전에 바닥에 손바닥을 대 봤다. 멀리서 일꾼 지나가는 걸음이 손바닥에 울렸다. 바닥이 귀다.<br><br>걷지 않았다. 배관 거치대와 빈 상자 위로만, 바닥에 발을 안 대고 건너가며 쟀다.<br>철창까지 쉰 걸음. 어미의 앞마디가 닿는 데까지는 서른 걸음. 스무 걸음 분량의 목숨이 남는 셈이다.<br><br>돌아오는 길에 어미가 손전등을 한 번 길게 켰다 껐다. 세던 박자가 아니었다. 그 생각은 아무한테도 말 안 했다.`,
            win:{ exp:25, dream:3 } },
          { l:'③ 더미 그늘에 모여 손짓으로만 순서를 짠다.', k:'bond', dc:24,
            ok:`입은 안 열었다. 손가락으로 짰다. 전원 넣을 사람. 단추 누를 사람. 제일 다친 사람을 업을 사람. 맨 뒤에 설 사람.<br><br>맨 뒤 자리에 서로 저를 가리켰다. 가위바위보로 정했다. 소리 안 나는 가위바위보는 처음 해 봤다.<br>마지막으로 서로의 신발 끈을 봐 줬다. 흘릴 것이 없게. 이 집에서 배운 것이다.<br><br>손전등 불빛이 안개 너머에서 깜박였다. 켜고. 끄고. 어미도 제 순서를 세고 있을 것이다.`,
            ng:`손짓이 길어지다 누군가의 속삭임이 샜다. 반 마디. 바람 소리만 한.<br><br>안개 너머에서 손전등 깜박임이 뚝 멎었다. 격납고가 귀가 됐다.<br>다들 입을 틀어막고 더미 그늘에 박혔다. 일꾼 한 줄이 이쪽을 돌아 지나갔다. 신발 코앞으로.<br><br>깜박임이 다시 시작될 때까지가 하룻밤 같았다. 그 뒤로 손가락도 반만 움직였다.`,
            win:{ exp:23, dream:3, spirit:8 },
            lose:{ mind:-21, spirit:-24 } }
        ] },

      { t:'격납고 — 찬 안개 건너기',
        x:`안개가 격납고 바닥에 가득 깔렸다. 무릎 높이. 그 밑은 안 보인다.<br><br>
          어미의 숨이 길어졌다. 손전등 박자가 느리다. 켜고. 한참. 끄고. 잠인지 잠든 척인지 모른다.<br>
          철창 통로까지 안개를 가로질러야 한다. 안개 밑 바닥에는 일꾼들의 길이 지난다.<br><br>
          어미의 앞마디 하나가 안개 위를 느리게 쓸고 있다. 자면서도 쓴다. 그물처럼.`,
        o:[
          { l:'① 안개 밑으로 허리를 굽혀 바닥길을 간다.', k:'hide', dc:26,
            doom:{ title:'안개 밑의 줄', what:'일꾼 떼에 실려 갑니다', dc:20, sec:35,
              text:`안개 속으로 허리를 굽혔다. 안개 밑은 하얗고 조용하다. 발밑도 안 보인다.<br><br>세 걸음째에 밟았다. 단단하고 둥근 것. 등딱지다. 밟힌 일꾼이 발목을 문다. 놓으라고 무는 게 아니다. 가지려고 무는 것이다.<br>안개 밑에서 줄 전체가 방향을 튼다. 다리 열둘이 수십 벌로 불어난다.<br><br>발밑이 사라진다. 등딱지들 위에 실린다. 안개 밑으로, 더미 쪽으로. 일꾼 떼에 실려 간다. 안개 위로 뻗은 손만 한동안 보였다.`,
              dieText:`안개가 다시 고요해졌다. 쓸고 다니던 앞마디도 제자리로 돌아갔다.<br><br>더미 꼭대기에 새 물건이 차례로 올라왔다. 신발 둘. 가방 하나. 가지런했다.<br>일꾼들은 좋은 것을 주운 날처럼 오래 바빴다.` },
            ok:`굽히기 전에 빈 물병 하나를 안개 속 멀찍이 굴렸다. 데구루루. 안개 밑에서 줄 하나가 그쪽으로 꺾이는 기척이 났다.<br><br>일꾼의 길이 비는 건 그때뿐이다. 굽히고 걸었다. 발끝으로 바닥을 쓸며, 둥근 것이 닿으면 비켜서.<br>안개 속에서는 숨도 하얗게 안 보인다. 그게 유일하게 좋은 점이었다.<br><br>통로 벽에 손이 닿았다. 차례로 다 닿았다. 굴린 물병은 더미 꼭대기에 올라가 있을 것이다.`,
            win:{ exp:25, dream:4 } },
          { l:'② 쓸고 지나가는 앞마디의 박자를 읽고 그 틈을 뛴다.', k:'evade', dc:25,
            doom:{ title:'그물의 틈', what:'마디에 감겨 끌려 올라갑니다', dc:20, sec:35,
              text:`앞마디는 그네처럼 오간다. 여섯을 세면 한 번. 지나간 자리가 틈이다.<br><br>여섯에 뛰었다. 네 걸음. 다섯 걸음. 등 뒤에서 안개가 갈라지는 소리가 났다. 박자가 바뀌었다. 자던 박자가 아니다.<br>마디는 그물이고, 그물은 걸린 게 있으면 빨라진다.<br><br>무릎 뒤를 마디가 후려 감는다. 발이 바닥에서 떨어진다. 안개 위로, 비상등 위로, 마디에 감겨 끌려 올라간다. 아래에서 일행의 얼굴들이 하얗게 올려다본다.`,
              dieText:`앞마디가 제 박자로 돌아왔다. 여섯에 한 번. 느리게.<br><br>어미는 자리를 뜨지 않았다. 승강기 앞은 좋은 자리다. 기다리면 오는 자리다.<br>한참 뒤 손전등이 켜졌다. 끄지 않았다. 켜 둔 채였다. 미끼는 켜 두는 법이다.`},
            ok:`앞마디가 오가는 걸 셌다. 여섯에 한 번. 쓸고 간 자리가 다시 쓸리기까지 여섯.<br><br>여섯을 세고 뛰고, 엎드리고, 다시 여섯을 세고 뛰었다. 한 사람씩. 안개가 몸을 받아 줬다.<br>마지막 사람이 건널 때 박자가 다섯으로 줄었다. 자면서도 센다. 이쪽이 세는 걸 저쪽도 센다.<br><br>그래도 다섯이면 넉넉했다. 통로 그늘에 다 모였다. 아무도 안 걸렸다. 그물이 빈 건 오늘이 처음일 것이다.`,
            win:{ exp:25, dream:3 } },
          { l:'③ 내공으로 일행의 체온을 안개 온도까지 내린다.', k:'steady', dc:25, cost:{ qi:34 },
            ok:`한 사람씩 등에 손바닥을 대고 내공을 흘렸다. 피가 느려진다. 몸이 식는다. 안개와 같은 온도까지.<br><br>다섯이 식은 채로 안개를 걸었다. 천천히. 바닥으로 울리는 걸음만 조심하면 됐다. 따뜻한 것이 없으면 어미의 그물에 걸릴 것도 없다.<br>어미 앞마디가 머리 위를 두 번 지나갔다. 두 번 다 그냥 지나갔다. 찬 것은 세지 않는다.<br><br>통로에 닿아 내공을 거뒀다. 몸이 다시 데워지며 다들 한참 떨었다. 떨리는 게 살아 있는 쪽 일이다.`,
            ng:`셋째 사람까지 식히고 손이 떨렸다. 내공이 바닥을 긁었다.<br><br>넷째 사람이 반만 식은 채로 걸었다. 안개 속에서 그 사람 둘레만 안개가 옅다. 김이 오른다.<br>앞마디가 그쪽으로 꺾였다. 일행이 그 사람을 잡아채 바닥에 눕히고 다 같이 안개 밑에 엎드렸다. 마디가 머리 위를 오래 더듬었다.<br><br>통로까지 기어서 갔다. 무릎이 다 까졌다. 깐 무릎이 따뜻해서 무서웠다.`,
            win:{ exp:25, dream:3 },
            lose:{ hp:-38, mind:-22, spirit:-26 } }
        ] },

      { t:'격납고 — 호출 단추',
        x:`철창 통로 옆 기둥에 단추가 하나 있다. 지상. 그 하나뿐이다. 제어반 불은 들어와 있다.<br><br>
          누르면 위에서 철창이 내려온다. 권양기가 운다. 벽의 때 묻은 안내판에 승강 시간 약 2분이라고 적혀 있다.<br>
          2분 동안 격납고의 모든 것이 그 소리를 들을 것이다. 어미는 단추에서 서른 걸음에 앉아 있다.<br><br>
          어미가 왜 이 앞에 사는지 다들 안다. 눌리기를 기다리는 것이다.`,
        o:[
          { l:'① 전선을 이어 더미 뒤에서 단추를 누르게 만든다.', k:'fix', dc:26,
            ok:`구리선을 단추 뒤 단자에 물리고, 선을 벽을 타고 더미 그늘까지 끌었다. 끝에 손전등 스위치를 달았다.<br><br>다 숨고 나서 스위치를 넣었다. 서른 걸음 밖에서 단추가 눌렸다. 권양기가 울기 시작한다. 쇠가 쇠를 감는 소리.<br>어미가 일어났다. 단추 앞으로 갔다. 아무도 없다. 얼굴판이 단추를 오래 들여다봤다.<br><br>그리고 도로 앉았다. 철창 바로 밑에. 눌린 단추 다음에 오는 것을 아는 것이다. 숨은 쪽도 그걸 안다. 2분이 시작됐다.`,
            ng:`선을 끌다가 중간에서 끊겼다. 삭은 구리였다. 스위치를 넣어도 단추는 멀쩡히 꺼져 있다.<br><br>결국 한 사람이 뛰어가 맨손으로 눌렀다. 권양기가 울자마자 어미가 일어나는 그림자가 안개 위로 솟았다.<br>그 사람은 안개에 엎드려 상자 밑으로 기어 돌아왔다. 어깨 위로 앞마디가 두 번 지나갔다.<br><br>돌아온 사람 손바닥에 단추 자국이 하얗게 박혀 있었다. 한동안 안 지워졌다.`,
            win:{ exp:25, dream:4 },
            lose:{ hp:-36, mind:-22 } },
          { l:'② 반대편 벽을 두드려 어미를 그쪽으로 보낸다.', k:'bond', dc:25,
            doom:{ title:'대답하는 벽', what:'어둠 속으로 끌려갑니다', dc:20, sec:36,
              text:`반대편 벽까지 멀리 돌아가 쇠막대로 벽을 쳤다. 두 번. 이 집의 말로. 와 보라고.<br><br>어미는 안 움직였다. 대신 벽이 대답했다. 안쪽에서. 두 번.<br>이 집에서 두 번은 신호다. 신호는 보낸 쪽으로 돌아온다. 벽 환기구 덮개가 안으로 열린다. 1층에서 배운 문이다. 배운 걸 너무 늦게 떠올렸다.<br><br>어둠에서 마디가 나와 손목을 감는다. 쇠막대가 바닥에 떨어진다. 몸이 덮개 틀을 지나 어둠 속으로 끌려간다. 등 뒤에서 권양기 소리가 아득해진다.`,
              dieText:`벽 안쪽은 환기구로 다 이어져 있다. 1층부터 8층까지.<br><br>두드림은 한동안 벽을 타고 위로 올라갔다. 층마다 한 번씩. 멀어지며.<br>떨어진 쇠막대는 다음 날 일꾼이 물어 갔다. 더미 꼭대기, 잘 보이는 자리에 올라갔다.` },
            ok:`벽을 치기 전에 벽에 귀를 대 봤다. 벽 안쪽에서 숨소리가 났다. 벽은 비어 있지 않다. 이 집의 벽은 한 번도 비어 있던 적이 없다.<br><br>치지 않았다. 대신 빈 생수병 여남은 개를 끈으로 엮어 반대편 상자 더미에 걸고, 끈을 길게 끌고 왔다.<br>때가 오면 멀리서 당기기로 했다. 병 무더기가 쏟아지는 소리는 사고 소리다. 신호가 아니다. 사고는 보러 간다.<br><br>끈 끝을 제일 손 빠른 사람이 쥐었다. 쥔 손에 땀이 안 마르게 번갈아 쥐었다.`,
            win:{ exp:24, dream:3 } },
          { l:'③ 무력으로 배전함을 쳐 격납고 끝 등을 한꺼번에 터뜨린다.', k:'break', dc:25, cost:{ might:36 },
            ok:`격납고 끝 쪽 배전함에 무력을 실어 주먹을 박았다. 함이 우그러지며 그쪽 벽의 등이 한꺼번에 터졌다. 파팍. 불꽃이 쏟아진다.<br><br>어미가 일어났다. 빛 쪽으로 갔다. 불빛이 켜지면 사람이 온다. 연구 일지의 그 줄을 어미도 안다. 저들에게 가르친 게 어미다.<br>어미가 불꽃을 들여다보는 사이 단추를 눌렀다. 권양기 소리가 불꽃 튀는 소리에 반쯤 묻혔다.<br><br>어미는 꺼진 등을 하나씩 짚어 보고 있었다. 사람이 안 온다는 걸 깨닫기까지, 2분 중 1분을 벌었다.`,
            ng:`주먹은 배전함을 뚫었다. 등도 터졌다. 다만 불꽃이 손목을 타고 올라왔다.<br><br>감전이다. 팔이 제멋대로 튀고 입에서 쇠 맛이 났다. 일행이 옷으로 감아 끌어냈다.<br>어미는 빛 쪽으로 갔다. 가다가 멈췄다. 얼굴판이 이쪽을 향했다. 탄내는 사람 냄새다.<br><br>단추는 눌렀다. 권양기가 운다. 어미가 돌아오고 있다. 벌어 둔 시간이 없다.`,
            win:{ exp:25, dream:3 },
            lose:{ hp:-40, mind:-20 } }
        ] }
    ],
    boss:
      { t:'0호 격납고 — 어미',
        x:`권양기가 운다. 철창이 내려온다. 천천히. 2분이 이렇게 긴 시간인 줄 아무도 몰랐다.<br><br>
          어미가 일어선다. 접힌 것이 펴진다. 펴지고, 또 펴진다. 비상등이 어미 등에 가려 격납고가 한 단 더 어두워진다.<br>
          찬 안개 속인데도 빠르다. 느려진 것이 이 정도다. 손전등이 바닥에 떨어져 켜진 채 구른다.<br><br>
          철창이 바닥에 닿는다. 문이 열린다. 어미와 철창 사이, 서른 걸음이 스무 걸음이 됐다.`,
        o:[
          { l:'① 들숨 끝을 기다려 배 밑 껍데기 자리를 친다.', k:'break', dc:26,
            ok:`어미가 몸을 세우며 숨을 들이쉰다. 들숨 끝. 배가 제일 높이 뜬다. 허연 자리가 비상등에 드러난다.<br><br>그 밑으로 미끄러져 들어가 쇠막대를 박았다. 손바닥 둘 크기의, 판이 없는 자리에. 끝까지.<br>어미가 운다. 격납고의 쇠란 쇠가 다 같이 운다. 어미가 아픈 데를 바닥에 붙이려고 몸을 접는다. 길이 열린다.<br><br>철창으로 뛰었다. 맑은 피가 바닥을 지글지글 녹이며 따라왔다. 마지막 사람 신발 뒤축이 녹아 문턱에 눌어붙었다. 문이 닫혔다. 철창이 오른다.`,
            ng:`박았다. 다만 한 뼘 빗나갔다. 허연 자리 옆 판을 쳤다. 쇠막대가 튕겨 손아귀가 찢어졌다.<br><br>어미의 마디가 후려쳤다. 몸이 안개를 가르고 날아가 더미에 박혔다. 명찰이 쏟아져 내렸다.<br>갈라진 판 틈에서 맑은 피가 한 방울 떨어져 팔뚝에 닿았다. 지졌다. 뼈까지 닿는 줄 알았다.<br><br>일행이 끌어냈다. 철창은 열려 있다. 어미는 이제 다 폈다.`,
            win:{ exp:25, dream:4 },
            lose:{ hp:-44, mind:-23 } },
          { l:'② 마디 사이를 질러 철창으로 내달린다.', k:'evade', dc:26,
            doom:{ title:'세 번째 마디', what:'어미 손에 잡혀 올라갑니다', dc:20, sec:35,
              text:`뛰었다. 첫 마디가 바닥을 쓸며 왔다. 뛰어넘었다. 둘째 마디가 안개를 갈랐다. 숙여서 흘렸다.<br><br>셋째는 못 봤다. 위에서 왔다. 어미는 마디가 몇인지 보여 준 적이 없다.<br>어깨가 잡힌다. 바닥이 멀어진다. 철창이, 일행이, 켜진 손전등이 작아진다. 어미 손에 잡혀 올라간다.<br><br>얼굴판 솔기 앞에서 멎는다. 솔기가 벌어진다. 안은 따뜻하다. 이 집 맨 밑에서 제일 따뜻한 데다.`,
              dieText:`어미는 쥔 것을 바로 어쩌지 않았다. 철창 쪽을 향해 쥔 채로 서 있었다. 보란 듯이.<br><br>철창이 올라가는 동안 다들 위를 안 보려고 했다. 다 봤다.<br>격납고 바닥에 손전등만 남아 켜진 채 굴렀다. 일꾼이 와서 그것도 물어 갔다.` },
            ok:`뛰기 전에 셌다. 안개를 쓸던 마디가 둘. 일어설 때 짚은 마디가 둘. 보이는 게 넷이면 안 보이는 게 더 있다.<br><br>곧장 안 뛰었다. 더미 기슭을 끼고 반원을 돌았다. 마디는 길지만 더미 위로는 못 쓸어 온다. 제 물건 무덤이라.<br>마지막 열 걸음만 곧장 뛰었다. 머리 위에서 바람이 한 번 지나갔다. 위에서 오는 다섯째였다. 늦었다. 이쪽이 더 빨랐다.<br><br>철창 안으로 굴러 들어갔다. 등 뒤에서 마디가 철창을 감았다 놓쳤다. 쇠 긁는 소리가 길게 남았다.`,
            win:{ exp:25, dream:4 } },
          { l:'③ 닫히려는 철창 문을 붙들고 마지막 사람까지 버틴다.', k:'steady', dc:25,
            ok:`철창 문이 무게추에 끌려 닫히려 든다. 문틀을 등으로 받치고 두 팔로 버텼다. 들어와. 하나씩. 빨리.<br><br>어미의 마디가 철창을 후려쳤다. 철창이 통째로 운다. 이가 흔들렸다. 버텼다. 셋. 넷.<br>마지막 사람이 바닥을 굴러 들어왔다. 손을 놓자 문이 쾅 닫혔다. 권양기가 당긴다. 철창이 바닥에서 뜬다.<br><br>어미가 철창을 따라 몸을 세웠다. 얼굴판이 철창 높이를 따라 올라온다. 오래 따라 올라왔다. 솔기가 한 번 벌어졌다 닫혔다. 배웅 같은 건 아니었을 것이다.`,
            ng:`마디가 문틀을 쳤다. 받치고 있던 등으로 그 울림이 다 들어왔다. 갈비뼈가 어긋나는 소리를 제 귀로 들었다.<br><br>무릎이 꺾였다. 문이 반 뼘 내려왔다. 마지막 사람이 그 반 뼘 밑으로 기어 들어왔다. 머리카락 몇 올이 문에 끼어 뜯겼다.<br>문이 닫히고 철창이 떴다. 철창 틈으로 어미의 숨이 들어왔다. 따뜻했다. 올라가는 내내 따뜻했다.<br><br>그게 제일 오래 남았다. 찬 바람이 들어오고서야 다들 숨을 놓았다.`,
            win:{ exp:24, dream:4, spirit:10 },
            lose:{ hp:-42, spirit:-28 } }
        ] } }
  ]
});
